    [MenuItem("WarlineCapture/UI/Install Phase 1 Bootstrap In Game Scene")]
    public static void InstallBootstrapInGameScene()
    {
        const string scenePath = "Assets/Game/Scenes/Game2D.unity";
        BuildAll();

        UnityEngine.SceneManagement.Scene scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        GameObject bootstrapObject = GameObject.Find("WarlineCaptureUIBootstrap");
        if (bootstrapObject == null)
            bootstrapObject = new GameObject("WarlineCaptureUIBootstrap");

        WarlineCaptureUiBootstrap bootstrap = bootstrapObject.GetComponent<WarlineCaptureUiBootstrap>();
        if (bootstrap == null)
            bootstrap = bootstrapObject.AddComponent<WarlineCaptureUiBootstrap>();

        SetSerializedObject(bootstrap, "appCanvasPrefab", AssetDatabase.LoadAssetAtPath<GameObject>(ShellPrefabPath));
        SetSerializedEnum(bootstrap, "startupMode", (int)WarlineCaptureUiStartupMode.UseLegacyMenu);
        SetSerializedBool(bootstrap, "enableParallelUiOnStart", false);

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        Debug.Log("[WarlineCaptureUI] Installed disabled Phase 1 UI bootstrap in Game.unity.");
    }

    [MenuItem("WarlineCapture/UI/Enable Parallel UI In Game Scene")]
    public static void EnableParallelUiInGameScene()
    {
        const string scenePath = "Assets/Game/Scenes/Game2D.unity";
        BuildAll();

        UnityEngine.SceneManagement.Scene scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        GameObject bootstrapObject = GameObject.Find("WarlineCaptureUIBootstrap");
        if (bootstrapObject == null)
            bootstrapObject = new GameObject("WarlineCaptureUIBootstrap");

        WarlineCaptureUiBootstrap bootstrap = bootstrapObject.GetComponent<WarlineCaptureUiBootstrap>();
        if (bootstrap == null)
            bootstrap = bootstrapObject.AddComponent<WarlineCaptureUiBootstrap>();

        SetSerializedObject(bootstrap, "appCanvasPrefab", AssetDatabase.LoadAssetAtPath<GameObject>(ShellPrefabPath));
        SetSerializedEnum(bootstrap, "startupMode", (int)WarlineCaptureUiStartupMode.UseParallelCodexUi);
        SetSerializedBool(bootstrap, "enableParallelUiOnStart", true);
        SetSerializedEnum(bootstrap, "parallelStartupRoute", (int)WarlineCaptureRoute.Splash);

        GameObject legacyCanvas = GameObject.Find("UI_Canvas");
        if (legacyCanvas != null)
            legacyCanvas.SetActive(false);

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        Debug.Log("[WarlineCaptureUI] Enabled parallel UI in Game.unity and deactivated legacy UI_Canvas without removing it.");
    }

