    private static readonly Color MatchOverlayQaBackgroundColor = new(0.10f, 0.13f, 0.12f, 1f);

    private static void CaptureScreenPrefab(string prefabPath, string outputPath, int width, int height)
    {
        CaptureScreenPrefab(prefabPath, outputPath, width, height, new Color(0.018f, 0.026f, 0.03f, 1f));
    }

    private static void CaptureScreenPrefab(string prefabPath, string outputPath, int width, int height, Color backgroundColor)
    {
        CaptureScreenPrefab(prefabPath, outputPath, width, height, backgroundColor, null);
    }

    private static void CaptureScreenPrefab(string prefabPath, string outputPath, int width, int height, Color backgroundColor, System.Action<GameObject> configureInstance)
    {
        if (SystemInfo.graphicsDeviceType == GraphicsDeviceType.Null)
        {
            throw new System.InvalidOperationException(
                $"Cannot capture visible UI for {prefabPath} while Unity is running with NullGfxDevice. Run batch capture without -nographics.");
        }

        GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
        if (prefab == null)
            throw new FileNotFoundException($"UI prefab not found at {prefabPath}");

        EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

        RenderTexture renderTexture = null;
        Texture2D screenshot = null;
        GameObject cameraObject = null;
        GameObject canvasObject = null;
        GameObject instance = null;
        RenderTexture previousActiveTexture = RenderTexture.active;

        try
        {
            renderTexture = new RenderTexture(width, height, 24, RenderTextureFormat.ARGB32)
            {
                antiAliasing = 1
            };
            renderTexture.Create();

            cameraObject = new GameObject("WarlineCaptureUiCaptureCamera");
            Camera camera = cameraObject.AddComponent<Camera>();
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = backgroundColor;
            camera.orthographic = true;
            camera.orthographicSize = height * 0.5f;
            camera.nearClipPlane = 0.1f;
            camera.farClipPlane = 100f;
            camera.targetTexture = renderTexture;
            cameraObject.transform.position = new Vector3(0f, 0f, -10f);

            canvasObject = CreateRectObject("WarlineCaptureUiCaptureCanvas", null);
            Canvas canvas = canvasObject.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;
            canvas.worldCamera = camera;

            CanvasScaler scaler = canvasObject.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ConstantPixelSize;

            RectTransform canvasTransform = (RectTransform)canvasObject.transform;
            canvasTransform.sizeDelta = new Vector2(width, height);
            canvasTransform.localPosition = Vector3.zero;
            canvasTransform.localScale = Vector3.one;

            instance = Object.Instantiate(prefab, canvasObject.transform);
            instance.name = prefab.name;
            instance.SetActive(true);
            RectTransform instanceTransform = (RectTransform)instance.transform;
            instanceTransform.anchorMin = Vector2.zero;
            instanceTransform.anchorMax = Vector2.one;
            instanceTransform.offsetMin = Vector2.zero;
            instanceTransform.offsetMax = Vector2.zero;
            instanceTransform.localScale = Vector3.one;
            configureInstance?.Invoke(instance);

            Canvas.ForceUpdateCanvases();
            RenderTexture.active = renderTexture;
            GL.Clear(true, true, backgroundColor);
            camera.Render();

            RenderTexture.active = renderTexture;
            screenshot = new Texture2D(width, height, TextureFormat.RGBA32, false);
            screenshot.ReadPixels(new Rect(0, 0, width, height), 0, 0);
            screenshot.Apply();

            File.WriteAllBytes(outputPath, screenshot.EncodeToPNG());
            Debug.Log($"[WarlineCaptureUI] Captured {prefabPath} to {outputPath}");
        }
        finally
        {
            RenderTexture.active = previousActiveTexture;
            Camera camera = cameraObject == null ? null : cameraObject.GetComponent<Camera>();
            if (camera != null)
                camera.targetTexture = null;
            if (screenshot != null)
                Object.DestroyImmediate(screenshot);
            if (renderTexture != null)
                Object.DestroyImmediate(renderTexture);
            if (instance != null)
                Object.DestroyImmediate(instance);
            if (canvasObject != null)
                Object.DestroyImmediate(canvasObject);
            if (cameraObject != null)
                Object.DestroyImmediate(cameraObject);
        }
    }

    private static void RefreshAspectVariantSwitchers(GameObject instance)
    {
        if (instance == null)
            return;

        WarlineCaptureAspectVariantSwitcher[] switchers = instance.GetComponentsInChildren<WarlineCaptureAspectVariantSwitcher>(true);
        foreach (WarlineCaptureAspectVariantSwitcher switcher in switchers)
            switcher.Refresh();
    }

    private static void OpenBuildDrawerForCapture(GameObject instance)
    {
        BuildDrawerPanelController drawerController = instance.GetComponent<BuildDrawerPanelController>();
        if (drawerController != null)
        {
            drawerController.Open();
            return;
        }

        Transform drawer = instance.transform.Find("BuildDrawerCanvas");
        if (drawer != null)
            drawer.gameObject.SetActive(true);
    }

    private static void OpenAssistantPanelForCapture(GameObject instance)
    {
        WarlineCaptureMissionSession.BeginMission(ChapterOneMissionCatalog.FirstContactMissionId, WarlineCaptureRoute.SagaMap);
        InitialUnitsRuntimeState.PlayRequested = true;

        AssistantRuntimeBinding assistantRuntimeBinding = instance.GetComponent<AssistantRuntimeBinding>();
        if (assistantRuntimeBinding != null)
            assistantRuntimeBinding.RefreshNow();

        SetCaptureRootActive(instance, "AssistantLayer/AssistantEntryButton", true);
        SetCaptureRootActive(instance, "AssistantLayer/AssistantPanelDock", true);

        AssistantPanelController assistantPanelController = instance.GetComponent<AssistantPanelController>();
        if (assistantPanelController != null)
        {
            assistantPanelController.TogglePresentation();
            return;
        }

        Transform assistantPanelDock = instance.transform.Find("AssistantLayer/AssistantPanelDock");
        if (assistantPanelDock != null)
            assistantPanelDock.gameObject.SetActive(true);
    }

    private static void OpenCommandWheelForCapture(GameObject instance)
    {
        CommandWheelPanelController wheelController = instance.GetComponent<CommandWheelPanelController>();
        if (wheelController != null)
        {
            wheelController.Open();
            return;
        }

        Transform wheel = instance.transform.Find("CommandWheelCanvas");
        if (wheel != null)
            wheel.gameObject.SetActive(true);
    }

    private static void OpenTacticalFeedbackForCapture(GameObject instance)
    {
        Transform preview = instance.transform.Find("TacticalMapQaPreview");
        if (preview != null)
        {
            preview.gameObject.SetActive(true);
            preview.SetAsFirstSibling();
        }

        BattleHudTacticalFeedbackController feedbackController = instance.GetComponent<BattleHudTacticalFeedbackController>();
        if (feedbackController != null)
        {
            feedbackController.SetWorldMarkersVisible(true);
            feedbackController.ShowCommandMode("ATTACK TARGETING");
            feedbackController.ShowSelectedEntity("RIFLE SQUAD 01", "120 / 120");
            feedbackController.ShowInvalidCommand("INVALID: Target outside mission area");
            return;
        }

        foreach (string path in new[] { "WorldCommandMarkerLayer", "CommandModeBanner", "SelectedEntityPanel", "InvalidCommandToast" })
        {
            Transform surface = instance.transform.Find(path);
            if (surface != null)
                surface.gameObject.SetActive(true);
        }
    }

