        CaptureM01RouteDrivenSafeAreaState(width, height, resolutionLabel, safeAreaInsets, M01IntegratedCaptureState.AssistantOpen, "AssistantOpen");
        CaptureM01RouteDrivenSafeAreaState(width, height, resolutionLabel, safeAreaInsets, M01IntegratedCaptureState.AssistantTakeoverStop, "AssistantTakeoverStop");
        CaptureM01RouteDrivenSafeAreaState(width, height, resolutionLabel, safeAreaInsets, M01IntegratedCaptureState.ResultPopup, "ResultPopup");
