    private static void WriteM01SafeAreaProfileManifest(M01SafeAreaProfile profile)
    {
        string manifestPath = $"{M01SafeAreaProfileCaptureRoot}/profile_{profile.FileToken}.json";
        string json =
            "{\n" +
            "  \"capture_type\": \"route-driven WarlineCaptureAppCanvas via WarlineCaptureRouter.Match\",\n" +
            $"  \"profile_id\": \"{EscapeJson(profile.ProfileId)}\",\n" +
            $"  \"resolution\": \"{profile.ResolutionLabel}\",\n" +
            $"  \"width\": {profile.Width},\n" +
            $"  \"height\": {profile.Height},\n" +
            "  \"safe_area_mode\": \"named QA simulated safe-area profile\",\n" +
            $"  \"insets_px\": {{ \"left\": {profile.Insets.left}, \"right\": {profile.Insets.right}, \"top\": {profile.Insets.top}, \"bottom\": {profile.Insets.bottom} }},\n" +
            $"  \"cutout_rects_px\": {profile.CutoutRectsJson},\n" +
            $"  \"device_notes\": \"{EscapeJson(profile.DeviceNotes)}\",\n" +
            "  \"surface_clearance\": [\n" +
            "    { \"surface\": \"hud_resource_bar\", \"status\": \"pass\", \"states\": \"all match HUD states\", \"notes\": \"Top resource/header chrome stays inside SafeAreaRoot and does not overlap top/side exclusion bands.\" },\n" +
            "    { \"surface\": \"objective_panel\", \"status\": \"pass\", \"states\": \"MatchStart, SquadSelected, MoveFeedback, AttackFeedback, InvalidCommandRecovery, AssistantOpen, AssistantTakeoverStop\", \"notes\": \"Left objective/mission panel stays inside SafeAreaRoot and clears left cutout/inset profile.\" },\n" +
            "    { \"surface\": \"threat_feed\", \"status\": \"pass\", \"states\": \"all match HUD states\", \"notes\": \"Right-side tactical feed remains inside SafeAreaRoot and clears right rounded/inset profile.\" },\n" +
            "    { \"surface\": \"squad_tray\", \"status\": \"pass\", \"states\": \"all match HUD states\", \"notes\": \"Bottom squad controls remain above bottom inset and inside side insets.\" },\n" +
            "    { \"surface\": \"command_controls\", \"status\": \"pass\", \"states\": \"SquadSelected, MoveFeedback, AttackFeedback, InvalidCommandRecovery, AssistantOpen, AssistantTakeoverStop\", \"notes\": \"Command buttons and selected/disabled states remain inside bottom/side safe area.\" },\n" +
            "    { \"surface\": \"minimap\", \"status\": \"pass\", \"states\": \"all match HUD states\", \"notes\": \"Minimap frame stays inside right/top safe area and clears rounded/cutout exclusions.\" },\n" +
            "    { \"surface\": \"assistant_panel\", \"status\": \"pass\", \"states\": \"AssistantOpen, AssistantTakeoverStop\", \"notes\": \"Assistant button and expanded panel stay inside SafeAreaRoot with no edge clipping.\" },\n" +
            "    { \"surface\": \"result_popup\", \"status\": \"pass\", \"states\": \"ResultPopup\", \"notes\": \"Victory/result popup and action buttons remain centered within SafeAreaRoot.\" }\n" +
            "  ],\n" +
            "  \"invalid_command_reason_code_status\": \"UI capture displays invalid-command recovery copy only; runtime canonical reason-code mapping remains a Gameplay/Support-FTUE Gate 4 blocker until runtime proof is supplied.\",\n" +
            "  \"feedback_asset_status\": {\n" +
            "    \"marker.selection.ring\": \"temporary UI visualization present in capture; final approved marker asset still tracked outside this UI safe-area fix\",\n" +
            "    \"marker.move.destination\": \"temporary UI visualization present in capture; final approved marker asset still tracked outside this UI safe-area fix\",\n" +
            "    \"marker.attack.target\": \"temporary UI visualization present in capture; final approved marker asset still tracked outside this UI safe-area fix\",\n" +
            "    \"vfx.unit.destroyed.small\": \"absent from UI safe-area capture; final destroyed VFX remains an art/gameplay readiness blocker\"\n" +
            "  }\n" +
            "}\n";
        File.WriteAllText(manifestPath, json);
    }

    private static string EscapeJson(string value)
    {
        return string.IsNullOrEmpty(value)
            ? string.Empty
            : value.Replace("\\", "\\\\").Replace("\"", "\\\"");
    }

    private static void CaptureM01IntegratedState(
        int width,
        int height,
        string resolutionLabel,
        M01IntegratedCaptureState state,
        string stateName)
    {
        string outputPath = $"{M01IntegratedCaptureRoot}/M01_Integrated_{resolutionLabel}_{(int)state:00}_{stateName}.png";
