    private static void CaptureM01RouteDrivenSafeAreaState(
        int width,
        int height,
        string resolutionLabel,
        RectOffset safeAreaInsets,
        M01IntegratedCaptureState state,
        string stateName)
    {
        string outputPath = $"{M01RouteDrivenCaptureRoot}/M01_RouteSafeArea_{resolutionLabel}_{(int)state:00}_{stateName}.png";
        CaptureScreenPrefab(
            ShellPrefabPath,
            outputPath,
            width,
            height,
            MatchOverlayQaBackgroundColor,
            shell => ConfigureM01RouteDrivenSafeAreaState(shell, state, safeAreaInsets, width, height));
    }

    private static void ConfigureM01RouteDrivenSafeAreaState(
        GameObject shell,
        M01IntegratedCaptureState state,
        RectOffset safeAreaInsets,
        int width,
        int height)
    {
        ApplySimulatedSafeAreaForCapture(shell, safeAreaInsets, width, height);

        WarlineCaptureRouter router = shell.GetComponent<WarlineCaptureRouter>();
        if (router == null)
            throw new MissingComponentException("WarlineCaptureAppCanvas prefab must contain WarlineCaptureRouter for route-driven capture.");

        router.Initialize();
        router.GoTo(WarlineCaptureRoute.Match, false);

        WarlineCaptureScreenController matchScreen = FindRouteScreenForCapture(shell, WarlineCaptureRoute.Match);
        if (matchScreen == null)
            throw new MissingReferenceException("Route-driven capture could not resolve Screen_MatchOverlay after routing to Match.");

        if (state == M01IntegratedCaptureState.ResultPopup)
        {
            WarlineCaptureMissionSession.BeginMission(ChapterOneMissionCatalog.FirstContactMissionId, WarlineCaptureRoute.SagaMap);
            InitialUnitsRuntimeState.PlayRequested = true;
            ConfigureM01IntegratedCaptureState(matchScreen.gameObject, M01IntegratedCaptureState.SquadSelected);

            WarlineCaptureMatchResultFlow resultFlow = shell.GetComponent<WarlineCaptureMatchResultFlow>();
            if (resultFlow == null)
                throw new MissingComponentException("WarlineCaptureAppCanvas prefab must contain WarlineCaptureMatchResultFlow for route-driven result capture.");

            resultFlow.ShowResult(CreateM01MissionResultDataForCapture(), WarlineCaptureRoute.SagaMap);
            return;
        }

        ConfigureM01IntegratedCaptureState(matchScreen.gameObject, state);
    }

    private static void ApplySimulatedSafeAreaForCapture(
        GameObject shell,
        RectOffset safeAreaInsets,
        int width,
        int height)
    {
        Transform safeAreaRoot = shell.transform.Find("SafeAreaRoot");
        if (safeAreaRoot == null)
            throw new MissingReferenceException("WarlineCaptureAppCanvas prefab is missing SafeAreaRoot.");

        RectTransform safeAreaRect = safeAreaRoot as RectTransform;
        if (safeAreaRect == null)
            throw new MissingComponentException("SafeAreaRoot must be a RectTransform.");

        safeAreaRect.anchorMin = new Vector2(
            Mathf.Clamp01(safeAreaInsets.left / Mathf.Max(1f, width)),
            Mathf.Clamp01(safeAreaInsets.bottom / Mathf.Max(1f, height)));
        safeAreaRect.anchorMax = new Vector2(
            Mathf.Clamp01((width - safeAreaInsets.right) / Mathf.Max(1f, width)),
            Mathf.Clamp01((height - safeAreaInsets.top) / Mathf.Max(1f, height)));
        safeAreaRect.offsetMin = Vector2.zero;
        safeAreaRect.offsetMax = Vector2.zero;
    }

    private static WarlineCaptureScreenController FindRouteScreenForCapture(GameObject shell, WarlineCaptureRoute route)
    {
        foreach (WarlineCaptureScreenController screen in shell.GetComponentsInChildren<WarlineCaptureScreenController>(true))
        {
            if (screen != null && screen.Route == route)
                return screen;
        }

        return null;
    }

    private static void WriteM01RouteSafeAreaManifest(
        int width,
        int height,
        string resolutionLabel,
        RectOffset safeAreaInsets)
    {
        string manifestPath = $"{M01RouteDrivenCaptureRoot}/safe_area_{resolutionLabel}.json";
        string json =
            "{\n" +
            "  \"capture_type\": \"route-driven WarlineCaptureAppCanvas via WarlineCaptureRouter.Match\",\n" +
            $"  \"resolution\": \"{resolutionLabel}\",\n" +
            $"  \"width\": {width},\n" +
            $"  \"height\": {height},\n" +
            "  \"safe_area_mode\": \"simulated landscape inset\",\n" +
            $"  \"insets_px\": {{ \"left\": {safeAreaInsets.left}, \"right\": {safeAreaInsets.right}, \"top\": {safeAreaInsets.top}, \"bottom\": {safeAreaInsets.bottom} }},\n" +
            "  \"notes\": \"SafeAreaRoot is inset before route capture; visible outer margins represent excluded device cutout/rounded-corner regions.\"\n" +
            "}\n";
        File.WriteAllText(manifestPath, json);
    }

    private static void ConfigureM01IntegratedCaptureState(GameObject instance, M01IntegratedCaptureState state)
    {
        ConfigureM01NoSelectionCaptureState(instance);
        BattleHudTacticalFeedbackController feedbackController = instance.GetComponent<BattleHudTacticalFeedbackController>();

        switch (state)
        {
            case M01IntegratedCaptureState.SquadSelected:
                feedbackController?.SetWorldMarkersVisible(true);
                ShowM01SelectedSquad(feedbackController);
                break;
            case M01IntegratedCaptureState.MoveFeedback:
                feedbackController?.SetWorldMarkersVisible(true);
                ShowM01SelectedSquad(feedbackController);
                feedbackController?.ShowCommandMode("MOVE ORDER");
                break;
            case M01IntegratedCaptureState.AttackFeedback:
                feedbackController?.SetWorldMarkersVisible(true);
                ShowM01SelectedSquad(feedbackController);
                feedbackController?.ShowCommandMode("ATTACK TARGETING");
                break;
            case M01IntegratedCaptureState.InvalidCommandRecovery:
                feedbackController?.SetWorldMarkersVisible(true);
                ShowM01SelectedSquad(feedbackController);
                feedbackController?.ShowCommandMode("RECOVERY");
                feedbackController?.ShowInvalidCommand("INVALID: Select a valid hostile target");
                break;
            case M01IntegratedCaptureState.AssistantOpen:
                OpenAssistantPanelForCapture(instance);
                EnableM01IntegratedPreview(instance);
                feedbackController?.SetWorldMarkersVisible(true);
                break;
            case M01IntegratedCaptureState.AssistantTakeoverStop:
                ShowM01AssistantTakeoverForCapture(instance);
                EnableM01IntegratedPreview(instance);
                feedbackController?.SetWorldMarkersVisible(true);
                break;
            case M01IntegratedCaptureState.ResultPopup:
                ShowM01SelectedSquad(feedbackController);
                AddM01MissionResultPopupForCapture(instance);
                break;
        }
    }

    private static void ConfigureM01NoSelectionCaptureState(GameObject instance)
    {
        WarlineCaptureMissionSession.BeginMission(ChapterOneMissionCatalog.FirstContactMissionId, WarlineCaptureRoute.SagaMap);
        InitialUnitsRuntimeState.PlayRequested = true;
        EnableM01IntegratedPreview(instance);

        MatchObjectivePanelController objectivePanel = instance.GetComponent<MatchObjectivePanelController>();
        objectivePanel?.RefreshForTests();

        M01InfantryOnlyHudScopeController m01Scope = instance.GetComponent<M01InfantryOnlyHudScopeController>();
        m01Scope?.Refresh();

        BattleHudTacticalFeedbackController feedbackController = instance.GetComponent<BattleHudTacticalFeedbackController>();
        feedbackController?.HideSelectedEntity();
        feedbackController?.HideCommandMode();
        feedbackController?.HideInvalidCommand();
        feedbackController?.SetWorldMarkersVisible(false);

        AssistantPanelController assistantPanelController = instance.GetComponent<AssistantPanelController>();
        assistantPanelController?.Hide();

        BuildDrawerPanelController buildDrawerController = instance.GetComponent<BuildDrawerPanelController>();
        buildDrawerController?.Close();

        CommandWheelPanelController commandWheelController = instance.GetComponent<CommandWheelPanelController>();
        commandWheelController?.Close();

        SetCaptureRootActive(instance, "AssistantLayer/AssistantEntryButton", false);
        SetCaptureRootActive(instance, "AssistantLayer/AssistantPanelDock", false);
    }

    private static void SetCaptureRootActive(GameObject instance, string path, bool active)
    {
        Transform target = instance != null ? instance.transform.Find(path) : null;
        if (target != null)
            target.gameObject.SetActive(active);
    }

    private static void EnableM01IntegratedPreview(GameObject instance)
    {
        Transform preview = instance.transform.Find("TacticalMapQaPreview");
        if (preview != null)
        {
            preview.gameObject.SetActive(true);
            preview.SetAsFirstSibling();
        }
    }

    private static void ShowM01SelectedSquad(BattleHudTacticalFeedbackController feedbackController)
    {
        feedbackController?.ShowSelectedEntity("RIFLE SQUAD 01", "120 / 120");
    }

    private static void ShowM01AssistantTakeoverForCapture(GameObject instance)
    {
        WarlineCaptureMissionSession.BeginMission(ChapterOneMissionCatalog.FirstContactMissionId, WarlineCaptureRoute.SagaMap);
        InitialUnitsRuntimeState.PlayRequested = true;

        AssistantRuntimeBinding binding = instance.GetComponent<AssistantRuntimeBinding>();
        if (binding != null)
        {
            binding.RefreshNow();
            binding.AssistantService.SessionState.SetActiveTakeover("do.move_to_cover");
            binding.RefreshNow();
        }

        SetCaptureRootActive(instance, "AssistantLayer/AssistantEntryButton", true);
        SetCaptureRootActive(instance, "AssistantLayer/AssistantPanelDock", true);

        AssistantPanelController controller = instance.GetComponent<AssistantPanelController>();
        if (controller != null)
        {
            controller.ShowCurrentPresentation();
            return;
        }

        Transform assistantPanelDock = instance.transform.Find("AssistantLayer/AssistantPanelDock");
        if (assistantPanelDock != null)
            assistantPanelDock.gameObject.SetActive(true);
    }

    private static void AddM01MissionResultPopupForCapture(GameObject instance)
    {
        GameObject popupPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Prefabs/UI/Popups/MissionResultPopup.prefab");
        if (popupPrefab == null)
            throw new FileNotFoundException("Missing MissionResultPopup prefab.");

        GameObject popup = Object.Instantiate(popupPrefab, instance.transform);
        popup.name = "MissionResultPopup";
        popup.SetActive(true);

        RectTransform popupRect = popup.transform as RectTransform;
        if (popupRect != null)
        {
            popupRect.anchorMin = Vector2.zero;
            popupRect.anchorMax = Vector2.one;
            popupRect.offsetMin = Vector2.zero;
            popupRect.offsetMax = Vector2.zero;
            popupRect.localScale = Vector3.one;
        }

        MissionResultPopupController controller = popup.GetComponent<MissionResultPopupController>();
        controller?.Show(CreateM01MissionResultDataForCapture());
