    private static void EnsureButtonAnimationAssets()
    {
        EnsureFolder("Assets/Game/Animations", "UI");

        AnimationClip normalClip = EnsureButtonAnimationClip(UiButtonNormalClipPath, "WarlineCapture_Button_Normal", Color.white, 1f, 0.1f);
        AnimationClip highlightedClip = EnsureButtonAnimationClip(UiButtonHighlightedClipPath, "WarlineCapture_Button_Highlighted", Color.white, 1.035f, 0.08f);
        AnimationClip pressedClip = EnsureButtonAnimationClip(UiButtonPressedClipPath, "WarlineCapture_Button_Pressed", Color.white, 0.965f, 0.045f);
        AnimationClip selectedClip = EnsureButtonAnimationClip(UiButtonSelectedClipPath, "WarlineCapture_Button_Selected", Color.white, 1.045f, 0.08f);
        AnimationClip disabledClip = EnsureButtonAnimationClip(UiButtonDisabledClipPath, "WarlineCapture_Button_Disabled", new Color(0.38f, 0.40f, 0.42f, 0.42f), 1f, 0.08f);

        AssetDatabase.DeleteAsset(UiButtonLegacyAnimatorControllerPath);
        EnsureButtonAnimatorOverrideController(normalClip, highlightedClip, pressedClip, selectedClip, disabledClip);
        AssetDatabase.SaveAssets();
    }

    private static void EnsureButtonAnimatorOverrideController(
        AnimationClip normalClip,
        AnimationClip highlightedClip,
        AnimationClip pressedClip,
        AnimationClip selectedClip,
        AnimationClip disabledClip)
    {
        RuntimeAnimatorController baseController = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(UiButtonAnimatorTemplateControllerPath);
        if (baseController == null)
            throw new FileNotFoundException($"Button animator template not found at {UiButtonAnimatorTemplateControllerPath}");

        AnimatorOverrideController overrideController = AssetDatabase.LoadAssetAtPath<AnimatorOverrideController>(UiButtonAnimatorControllerPath);
        if (overrideController == null)
        {
            overrideController = new AnimatorOverrideController(baseController);
            AssetDatabase.CreateAsset(overrideController, UiButtonAnimatorControllerPath);
        }

        overrideController.name = Path.GetFileNameWithoutExtension(UiButtonAnimatorControllerPath);
        overrideController.runtimeAnimatorController = baseController;

        var overrides = new List<KeyValuePair<AnimationClip, AnimationClip>>();
        overrideController.GetOverrides(overrides);
        for (int i = 0; i < overrides.Count; i++)
        {
            AnimationClip sourceClip = overrides[i].Key;
            if (sourceClip == null)
                continue;

            AnimationClip replacementClip = sourceClip.name switch
            {
                "ANIM_Button_MilitaryCombat_Basic_01_Normal" => normalClip,
                "ANIM_Button_MilitaryCombat_Basic_01_Highlighted" => highlightedClip,
                "ANIM_Button_MilitaryCombat_Basic_01_Pressed" => pressedClip,
                "ANIM_Button_MilitaryCombat_Basic_01_Selected" => selectedClip,
                "ANIM_Button_MilitaryCombat_Basic_01_Disabled" => disabledClip,
                _ => overrides[i].Value
            };

            overrides[i] = new KeyValuePair<AnimationClip, AnimationClip>(sourceClip, replacementClip);
        }

        overrideController.ApplyOverrides(overrides);
        EditorUtility.SetDirty(overrideController);
    }

    private static AnimationClip EnsureButtonAnimationClip(string path, string clipName, Color color, float scale, float duration)
    {
        AnimationClip clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
        if (clip == null)
        {
            clip = new AnimationClip();
            AssetDatabase.CreateAsset(clip, path);
        }

        clip.name = clipName;
        clip.frameRate = 60f;
        clip.ClearCurves();
        clip.wrapMode = WrapMode.ClampForever;

        SetConstantCurve(clip, typeof(Transform), "m_LocalScale.x", scale, duration);
        SetConstantCurve(clip, typeof(Transform), "m_LocalScale.y", scale, duration);
        SetConstantCurve(clip, typeof(Transform), "m_LocalScale.z", 1f, duration);
        SetConstantCurve(clip, typeof(Image), "m_Color.r", color.r, duration);
        SetConstantCurve(clip, typeof(Image), "m_Color.g", color.g, duration);
        SetConstantCurve(clip, typeof(Image), "m_Color.b", color.b, duration);
        SetConstantCurve(clip, typeof(Image), "m_Color.a", color.a, duration);

        EditorUtility.SetDirty(clip);
        return clip;
    }

    private static void SetConstantCurve(AnimationClip clip, System.Type type, string propertyName, float value, float duration)
    {
        var binding = EditorCurveBinding.FloatCurve(string.Empty, type, propertyName);
        var curve = new AnimationCurve(new Keyframe(0f, value), new Keyframe(duration, value));
        AnimationUtility.SetEditorCurve(clip, binding, curve);
    }

    private static void SaveShellPrefab()
    {
        GameObject root = CreateRectObject("WarlineCaptureAppCanvas", null);
        try
        {
            Canvas canvas = root.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            root.AddComponent<GraphicRaycaster>();

            CanvasScaler scaler = root.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = MainMenuReferenceResolution;
            scaler.matchWidthOrHeight = 0.5f;

            WarlineCaptureRouter router = root.AddComponent<WarlineCaptureRouter>();
            WarlineCaptureModalController modal = root.AddComponent<WarlineCaptureModalController>();
            WarlineCaptureMatchResultFlow resultFlow = root.AddComponent<WarlineCaptureMatchResultFlow>();
            WarlineCaptureOperationModalFlow operationFlow = root.AddComponent<WarlineCaptureOperationModalFlow>();
            WarlineCaptureUiAccessibilityApplier accessibilityApplier = root.AddComponent<WarlineCaptureUiAccessibilityApplier>();

            GameObject safeAreaRoot = CreateRectObject("SafeAreaRoot", root.transform);
            WarlineCaptureSafeArea safeArea = safeAreaRoot.AddComponent<WarlineCaptureSafeArea>();
            GameObject headerBar = CreateRectObject("HeaderBar", safeAreaRoot.transform);
            GameObject contentRoot = CreateRectObject("ContentRoot", safeAreaRoot.transform);
            GameObject footerBar = CreateRectObject("FooterBar", safeAreaRoot.transform);
            GameObject modalOverlay = CreateRectObject("ModalOverlay", safeAreaRoot.transform);
            GameObject tooltipLayer = CreateRectObject("TooltipLayer", safeAreaRoot.transform);

            ConfigureVerticalBand((RectTransform)headerBar.transform, 0.88f, 1f);
            ConfigureVerticalBand((RectTransform)contentRoot.transform, 0f, 1f);
            ConfigureVerticalBand((RectTransform)footerBar.transform, 0f, 0.12f);
            headerBar.SetActive(false);
            footerBar.SetActive(false);
            modalOverlay.SetActive(false);
            GameObject placeholderPopup = CreatePlaceholderPopup(modalOverlay.transform, out TMP_Text popupTitle, out TMP_Text popupBody, out Button popupCloseButton);

            SetSerializedObject(router, "contentRoot", contentRoot.transform);
            SetSerializedArray(
                router,
                "screenPrefabs",
                LoadScreenPrefabController("Screen_Splash"),
                LoadScreenPrefabController("Screen_MainMenu"),
                LoadScreenPrefabController("Screen_Settings"),
                LoadScreenPrefabController("Screen_QuickCustomSetup"),
                LoadScreenPrefabController("Screen_MatchOverlay"),
                LoadScreenPrefabController("Screen_SagaMap"),
                LoadScreenPrefabController("Screen_MissionBriefing"),
                LoadScreenPrefabController("Screen_LoadoutSquadPrep"),
                LoadScreenPrefabController("Screen_CommanderProfile"),
                LoadScreenPrefabController("Screen_Armory"),
                LoadScreenPrefabController("Screen_CommandExchange"),
                LoadScreenPrefabController("Screen_Inbox"),
                LoadScreenPrefabController("Screen_Events"),
                LoadScreenPrefabController("Screen_Ranking"),
                LoadScreenPrefabController("Screen_CommandFeed"),
                LoadScreenPrefabController("Screen_OperationDashboard"),
                LoadScreenPrefabController("Screen_DistrictDetail"));
            SetSerializedObject(modal, "modalOverlay", modalOverlay);
            SetSerializedObject(modal, "placeholderContent", placeholderPopup);
            SetSerializedObject(modal, "placeholderTitleText", popupTitle);
            SetSerializedObject(modal, "placeholderBodyText", popupBody);
            SetSerializedObject(modal, "closeButton", popupCloseButton);
            SetSerializedObject(resultFlow, "router", router);
            SetSerializedObject(resultFlow, "modalOverlay", modalOverlay.transform);
            SetSerializedObject(resultFlow, "missionResultPopupPrefab", LoadMissionResultPopupPrefabController());
            SetSerializedObject(operationFlow, "modalOverlay", modalOverlay.transform);
            SetSerializedObject(operationFlow, "confirmRaidPopupPrefab", LoadPopupPrefab("ConfirmRaidPopup"));
            SetSerializedObject(operationFlow, "endOfDayReportPopupPrefab", LoadPopupPrefab("EndOfDayReportPopup"));
            SetSerializedObject(operationFlow, "intelRevealPopupPrefab", LoadPopupPrefab("IntelRevealPopup"));
            SetSerializedObject(accessibilityApplier, "scaleRoot", contentRoot.transform);
            SetSerializedFloat(accessibilityApplier, "largeTextScale", 1.08f);
            SetSerializedObject(safeArea, "target", safeAreaRoot.transform);

            PrefabUtility.SaveAsPrefabAsset(root, ShellPrefabPath);
        }
        finally
        {
            Object.DestroyImmediate(root);
        }
    }

