    private static GameObject CreateSettingsScreen()
    {
        GameObject screen = CreateRectObject("Screen_Settings", null);
        SettingsScreenController controller = screen.AddComponent<SettingsScreenController>();
        controller.SetRouteForTests(WarlineCaptureRoute.Settings);
        Image background = screen.AddComponent<Image>();
        background.color = new Color(0.004f, 0.016f, 0.019f, 1f);
        background.raycastTarget = false;
        WarlineCaptureUiAccessibilityApplier accessibilityApplier = screen.AddComponent<WarlineCaptureUiAccessibilityApplier>();
        SetSerializedBool(accessibilityApplier, "skipScaleWhenParentApplierExists", true);
        SetSerializedArray(accessibilityApplier, "highContrastTargets", background);

        CreateSharedScreenOuterFrame("OuterFrame", screen.transform);

        GameObject headerBar = CreateRectObject("HeaderBar", screen.transform);
        ConfigurePixelRect((RectTransform)headerBar.transform, 34f, 18f, 1604f, 104f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
        Image headerBackground = headerBar.AddComponent<Image>();
        headerBackground.color = Color.white;
        headerBackground.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsHeaderPanelPath);
        headerBackground.type = Image.Type.Sliced;
        headerBackground.raycastTarget = false;

        Button backButton = CreateSettingsBackButton("BackButton", headerBar.transform);
        RectTransform backRect = (RectTransform)backButton.transform;
        ConfigurePixelRect(backRect, 14f, 18f, 104f, 70f, 1604f, 104f);
        TMP_Text backLabel = backButton.GetComponentInChildren<TMP_Text>();
        if (backLabel != null)
            backLabel.fontSize = 54f;
        ScreenRouteButton backRoute = backButton.gameObject.AddComponent<ScreenRouteButton>();
        SetSerializedBool(backRoute, "useBackNavigation", true);

        TMP_Text titleText = CreateText("TitleText", headerBar.transform, "SETTINGS", 58f, TextAlignmentOptions.Left);
        RectTransform titleRect = (RectTransform)titleText.transform;
        ConfigurePixelRect(titleRect, 160f, 18f, 980f, 72f, 1604f, 104f);
        titleText.fontStyle = FontStyles.Bold;
        ConfigureSingleLineText(titleText);

        GameObject tabStrip = CreateRectObject("TabStrip", screen.transform);
        ConfigurePixelRect((RectTransform)tabStrip.transform, 66f, 132f, 1540f, 68f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
        Button tabGeneral = CreateSettingsTabButton("Tab_General", tabStrip.transform, "GENERAL", true);
        ConfigurePixelRect((RectTransform)tabGeneral.transform, 0f, 0f, 380f, 66f, 1540f, 68f);
        Button tabControls = CreateSettingsTabButton("Tab_Controls", tabStrip.transform, "CONTROLS", false);
        ConfigurePixelRect((RectTransform)tabControls.transform, 402f, 0f, 360f, 66f, 1540f, 68f);
        Button tabNotifications = CreateSettingsTabButton("Tab_Notifications", tabStrip.transform, "NOTIFICATIONS", false);
        ConfigurePixelRect((RectTransform)tabNotifications.transform, 786f, 0f, 366f, 66f, 1540f, 68f);
        Button tabAccessibility = CreateSettingsTabButton("Tab_Accessibility", tabStrip.transform, "ACCESSIBILITY", false);
        ConfigurePixelRect((RectTransform)tabAccessibility.transform, 1176f, 0f, 364f, 66f, 1540f, 68f);

        GameObject scrollView = CreateRectObject("SettingsScrollView", screen.transform);
        RectTransform scrollRectTransform = (RectTransform)scrollView.transform;
        Stretch(scrollRectTransform);

        GameObject viewport = CreateRectObject("Viewport", scrollView.transform);
        Image viewportImage = viewport.AddComponent<Image>();
        viewportImage.color = new Color(1f, 1f, 1f, 0.02f);
        Mask viewportMask = viewport.AddComponent<Mask>();
        viewportMask.showMaskGraphic = false;

        GameObject content = CreateRectObject("Content", viewport.transform);
        RectTransform contentRect = (RectTransform)content.transform;
        Stretch(contentRect);

        GameObject audioSection = CreateSettingsSection("AudioSection", content.transform, "AUDIO");
        ConfigurePixelRect((RectTransform)audioSection.transform, 60f, 219f, 760f, 336f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
        WarlineCaptureSliderRowView masterVolume = CreateSettingsSliderRow("MasterVolumeRow", audioSection.transform, "Master Volume", 80f);
        WarlineCaptureSliderRowView musicVolume = CreateSettingsSliderRow("MusicVolumeRow", audioSection.transform, "Music", 60f);
        WarlineCaptureSliderRowView sfxVolume = CreateSettingsSliderRow("SfxVolumeRow", audioSection.transform, "SFX", 85f);
        CreateSettingsSliderRow("VoiceVolumeRow", audioSection.transform, "Voice", 75f);

        GameObject graphicsSection = CreateSettingsSection("GraphicsSection", content.transform, "GRAPHICS");
        ConfigurePixelRect((RectTransform)graphicsSection.transform, 852f, 219f, 752f, 336f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
        WarlineCaptureSegmentedControlView qualityControl = CreateSettingsSegmentedControl("GraphicsQualityControl", graphicsSection.transform, new[] { "LOW", "MEDIUM", "HIGH", "ULTRA" }, 2);
        WarlineCaptureSegmentedControlView frameRateControl = CreateSettingsLabeledSegmentedControl("FrameRateControl", graphicsSection.transform, "Frame Rate", new[] { "30 FPS", "60 FPS", "120 FPS" }, 1);

        GameObject controlsSection = CreateSettingsSection("ControlsSection", content.transform, "CONTROLS");
        WarlineCaptureSliderRowView cameraSensitivity = CreateSettingsSliderRow("CameraSensitivityRow", controlsSection.transform, "CAMERA SENSITIVITY", 55f);
        controlsSection.SetActive(false);

        GameObject notificationsSection = CreateSettingsSection("NotificationsSection", content.transform, "NOTIFICATIONS");
        WarlineCaptureToggleRowView threatWarnings = CreateSettingsToggleRow("ThreatWarningsRow", notificationsSection.transform, "THREAT WARNINGS", "Show tactical warning overlays during missions.", true);
        notificationsSection.SetActive(false);

        GameObject accessibilitySection = CreateSettingsSection("AccessibilitySection", content.transform, "ACCESSIBILITY");
        ConfigurePixelRect((RectTransform)accessibilitySection.transform, 60f, 566f, 760f, 318f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
        TMP_Dropdown colorblindMode = CreateDropdownRow("ColorblindModeDropdownRow", accessibilitySection.transform, "Colorblind Mode", new[] { "Off", "Protanopia", "Deuteranopia", "Tritanopia" });
        WarlineCaptureToggleRowView highContrast = CreateSettingsToggleRow("HighContrastRow", accessibilitySection.transform, "High Contrast UI", string.Empty, true);
        WarlineCaptureToggleRowView largeText = CreateSettingsToggleRow("LargeTextRow", accessibilitySection.transform, "Large Text", string.Empty, false);

        GameObject languageSection = CreateSettingsSection("LanguageSection", content.transform, "LANGUAGE");
        ConfigurePixelRect((RectTransform)languageSection.transform, 852f, 566f, 752f, 318f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
        TMP_Dropdown language = CreateDropdownRow("LanguageDropdownRow", languageSection.transform, "Language", new[] { "English", "German", "French", "Spanish" });

        GameObject footerButtons = CreateRectObject("FooterButtons", screen.transform);
        RectTransform footerRect = (RectTransform)footerButtons.transform;
        ConfigurePixelRect(footerRect, 1190f, 850f, 414f, 64f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
        Button resetButton = CreateSettingsChromeButton("ResetButton", footerButtons.transform, "RESET", false, 196f, 64f);
        ConfigurePixelRect((RectTransform)resetButton.transform, 0f, 0f, 196f, 64f, 414f, 64f);
        Button applyButton = CreateSettingsChromeButton("ApplyButton", footerButtons.transform, "APPLY", true, 196f, 64f);
        ConfigurePixelRect((RectTransform)applyButton.transform, 218f, 0f, 196f, 64f, 414f, 64f);

        SetSerializedObject(controller, "masterVolumeRow", masterVolume);
        SetSerializedObject(controller, "musicVolumeRow", musicVolume);
        SetSerializedObject(controller, "sfxVolumeRow", sfxVolume);
        SetSerializedObject(controller, "graphicsQualityControl", qualityControl);
        SetSerializedObject(controller, "frameRateControl", frameRateControl);
        SetSerializedObject(controller, "cameraSensitivityRow", cameraSensitivity);
        SetSerializedObject(controller, "threatWarningsRow", threatWarnings);
        SetSerializedObject(controller, "highContrastRow", highContrast);
        SetSerializedObject(controller, "largeTextRow", largeText);
        SetSerializedObject(controller, "colorblindModeDropdown", colorblindMode);
        SetSerializedObject(controller, "languageDropdown", language);
        SetSerializedObject(controller, "resetButton", resetButton);
        SetSerializedObject(controller, "applyButton", applyButton);
        SetSerializedObject(accessibilityApplier, "scaleRoot", contentRect);
        SetSerializedObject(controller, "accessibilityApplier", accessibilityApplier);
        footerButtons.SetActive(false);
        ApplyScreenTypography(screen, "HeaderBar/TitleText");
        return screen;
    }

