    private static GameObject CreateQuickCustomPanel(string name, Transform parent, string title, float width, float height)
    {
        GameObject panel = CreateRectObject(name, parent);
        Image background = panel.AddComponent<Image>();
        background.color = Color.white;
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(QuickCustomPanelPath);
        background.type = Image.Type.Sliced;
        background.raycastTarget = false;

        Image accentBar = CreateImage("AccentBar", panel.transform, new Color(0.03f, 0.78f, 1f, 1f));
        ConfigurePixelRect((RectTransform)accentBar.transform, 22f, 24f, 6f, 28f, width, height);
        accentBar.raycastTarget = false;

        TMP_Text titleText = CreateText("SectionTitleText", panel.transform, title, 24f, TextAlignmentOptions.Left);
        titleText.fontStyle = FontStyles.Bold;
        titleText.enableAutoSizing = true;
        titleText.fontSizeMin = 17f;
        titleText.fontSizeMax = 24f;
        ConfigureSingleLineText(titleText);
        ConfigurePixelRect((RectTransform)titleText.transform, 40f, 17f, width - 54f, 40f, width, height);

        Image divider = CreateImage("Divider", panel.transform, new Color(0.46f, 0.58f, 0.60f, 0.42f));
        ConfigurePixelRect((RectTransform)divider.transform, 22f, 64f, width - 44f, 2f, width, height);
        divider.raycastTarget = false;
        return panel;
    }

    private static void AddFixedLayout(GameObject target, float width, float height)
    {
        LayoutElement layout = target.GetComponent<LayoutElement>();
        if (layout == null)
            layout = target.AddComponent<LayoutElement>();

        layout.minWidth = width;
        layout.minHeight = height;
        layout.preferredWidth = width;
        layout.preferredHeight = height;
        layout.flexibleWidth = 0f;
        layout.flexibleHeight = 0f;
    }

    private static TMP_Dropdown CreateQuickCustomDropdownRow(string name, Transform parent, string label, string[] options, float x, float y, float width, float height, float referenceWidth, float referenceHeight)
    {
        GameObject row = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)row.transform, x, y, width, height, referenceWidth, referenceHeight);

        TMP_Text labelText = CreateText("LabelText", row.transform, label, 22f, TextAlignmentOptions.Left);
        labelText.fontStyle = FontStyles.Bold;
        ConfigureSingleLineText(labelText);
        ConfigurePixelRect((RectTransform)labelText.transform, 0f, 0f, width, 30f, width, height);

        GameObject dropdownObject = CreateRectObject("Dropdown", row.transform);
        ConfigurePixelRect((RectTransform)dropdownObject.transform, 0f, 40f, width, 52f, width, height);
        Image dropdownBackground = dropdownObject.AddComponent<Image>();
        dropdownBackground.color = Color.white;
        dropdownBackground.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsDropdownPath);
        dropdownBackground.type = Image.Type.Sliced;
        TMP_Dropdown dropdown = dropdownObject.AddComponent<TMP_Dropdown>();

        TMP_Text captionText = CreateText("Label", dropdownObject.transform, options.Length > 0 ? options[0] : string.Empty, 21f, TextAlignmentOptions.Left);
        ConfigurePixelRect((RectTransform)captionText.transform, 20f, 9f, width - 80f, 34f, width, 52f);
        captionText.color = new Color(0.92f, 0.96f, 0.98f, 1f);
        captionText.textWrappingMode = TextWrappingModes.NoWrap;
        captionText.overflowMode = TextOverflowModes.Ellipsis;

        Image arrowImage = CreateImage("Arrow", dropdownObject.transform, Color.white);
        ConfigurePixelRect((RectTransform)arrowImage.transform, width - 50f, 15f, 30f, 22f, width, 52f);
        arrowImage.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsDropdownChevronPath);
        arrowImage.preserveAspect = true;
        arrowImage.raycastTarget = false;

        GameObject template = CreateDropdownTemplate(dropdownObject.transform, out TMP_Text itemText);
        dropdown.template = (RectTransform)template.transform;
        dropdown.captionText = captionText;
        dropdown.itemText = itemText;
        dropdown.options.Clear();
        foreach (string option in options)
            dropdown.options.Add(new TMP_Dropdown.OptionData(option));
        dropdown.SetValueWithoutNotify(0);
        template.SetActive(false);
        return dropdown;
    }

    private static WarlineCaptureSegmentedControlView CreateQuickCustomSegmentedControl(string name, Transform parent, string label, string[] labels, int selectedIndex, float x, float y, float width, float height, float referenceWidth, float referenceHeight)
    {
        GameObject root = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)root.transform, x, y, width, height, referenceWidth, referenceHeight);
        WarlineCaptureSegmentedControlView view = root.AddComponent<WarlineCaptureSegmentedControlView>();

        TMP_Text labelText = CreateText("LabelText", root.transform, label, 22f, TextAlignmentOptions.Left);
        labelText.fontStyle = FontStyles.Bold;
        ConfigureSingleLineText(labelText);
        ConfigurePixelRect((RectTransform)labelText.transform, 0f, 0f, width, 30f, width, height);

        GameObject segmentRoot = CreateRectObject("SegmentRoot", root.transform);
        ConfigurePixelRect((RectTransform)segmentRoot.transform, 0f, 40f, width, 52f, width, height);
        HorizontalLayoutGroup layout = segmentRoot.AddComponent<HorizontalLayoutGroup>();
        layout.spacing = -1f;
        layout.childControlWidth = true;
        layout.childControlHeight = true;
        layout.childForceExpandWidth = true;
        layout.childForceExpandHeight = true;

        Button[] buttons = new Button[labels.Length];
        TMP_Text[] labelTexts = new TMP_Text[labels.Length];
        for (int i = 0; i < labels.Length; i++)
        {
            bool selected = i == selectedIndex;
            buttons[i] = CreateQuickCustomChromeButton($"Segment_{i + 1}", segmentRoot.transform, labels[i], selected, width / labels.Length, 52f);
            labelTexts[i] = buttons[i].GetComponentInChildren<TMP_Text>();
            if (labelTexts[i] != null)
            {
                labelTexts[i].fontSize = labels.Length > 3 ? 18f : 23f;
                labelTexts[i].fontStyle = FontStyles.Bold;
                labelTexts[i].textWrappingMode = TextWrappingModes.NoWrap;
                labelTexts[i].overflowMode = TextOverflowModes.Ellipsis;
            }
        }

        SetSerializedObject(view, "segmentRoot", segmentRoot.transform);
        SetSerializedArray(view, "segmentButtons", buttons);
        SetSerializedArray(view, "segmentLabels", labelTexts);
        ConfigureQuickCustomSegmentVisuals(view);
        view.Bind(labels, selectedIndex);
        ApplyQuickCustomSegmentedControlVisualSelection(view, selectedIndex);
        return view;
    }

