        fill.color = new Color(0.03f, 0.78f, 1f, 1f);
        fill.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsSliderFillPath);
        fill.type = Image.Type.Sliced;

        GameObject handleArea = CreateRectObject("Handle Slide Area", sliderObject.transform);
        RectTransform handleAreaRect = (RectTransform)handleArea.transform;
        handleAreaRect.anchorMin = new Vector2(0f, 0.5f);
        handleAreaRect.anchorMax = new Vector2(1f, 0.5f);
        handleAreaRect.offsetMin = new Vector2(8f, 0f);
        handleAreaRect.offsetMax = new Vector2(-8f, 0f);
        GameObject handleObject = CreateRectObject("Handle", handleArea.transform);
        RectTransform handleRect = (RectTransform)handleObject.transform;
        handleRect.anchorMin = new Vector2(0.62f, 0f);
        handleRect.anchorMax = new Vector2(0.62f, 1f);
        handleRect.pivot = new Vector2(0.5f, 0.5f);
        handleRect.anchoredPosition = Vector2.zero;
        handleRect.sizeDelta = new Vector2(34f, 34f);
        Image handle = handleObject.AddComponent<Image>();
        handle.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsToggleHandlePath);
        handle.color = new Color(0.84f, 0.91f, 0.93f, 1f);
        Image handleCore = CreateImage("HandleCore", handleObject.transform, new Color(0.015f, 0.05f, 0.06f, 1f));
        RectTransform handleCoreRect = (RectTransform)handleCore.transform;
        handleCoreRect.anchorMin = new Vector2(0.35f, 0.35f);
        handleCoreRect.anchorMax = new Vector2(0.65f, 0.65f);
        handleCore.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsToggleHandlePath);
        handleCore.raycastTarget = false;

        slider.fillRect = (RectTransform)fillObject.transform;
        slider.handleRect = handleRect;
        slider.targetGraphic = handle;
        slider.minValue = 0f;
        slider.maxValue = 100f;
        slider.SetValueWithoutNotify(62f);

        Image separator = CreateImage("Separator", root.transform, new Color(0.25f, 0.42f, 0.46f, 0.34f));
        ConfigurePixelRect((RectTransform)separator.transform, 88f, height - 2f, width - 100f, 1f, width, height);
        separator.raycastTarget = false;

        SetSerializedObject(view, "labelText", labelText);
        SetSerializedObject(view, "valueText", valueText);
        SetSerializedObject(view, "slider", slider);
        return view;
    }

