    private static Button CreateQuickCustomLaunchButton(Transform parent)
    {
        GameObject buttonObject = CreateRectObject("LaunchButton", parent);
        Button launchButton = buttonObject.AddComponent<Button>();
        Image background = buttonObject.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(QuickCustomLaunchButtonPath);
        background.type = Image.Type.Sliced;
        background.color = Color.white;
        launchButton.targetGraphic = background;
        ConfigureButtonTint(launchButton, Color.white, new Color(1f, 0.94f, 0.55f, 1f), new Color(0.95f, 0.58f, 0.08f, 1f));
        ConfigurePixelRect((RectTransform)launchButton.transform, 1036f, 756f, 580f, 104f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);

        Image leftArrow = CreateImage("LeftChevronIcon", buttonObject.transform, Color.white);
        leftArrow.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(QuickCustomLaunchArrowLeftPath);
        leftArrow.preserveAspect = true;
        leftArrow.raycastTarget = false;
