    private static Button CreateQuickCustomChromeButton(string name, Transform parent, string label, bool selected, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        SetSize(buttonObject, width, height);
        Image background = buttonObject.AddComponent<Image>();
        background.color = Color.white;
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(selected ? QuickCustomButtonSelectedPath : QuickCustomButtonNormalPath);
        background.type = Image.Type.Sliced;
        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(button, Color.white, new Color(0.88f, 0.97f, 1f, 1f), new Color(0.58f, 0.78f, 0.88f, 1f));

        TMP_Text labelText = CreateText("LabelText", buttonObject.transform, label, 24f, TextAlignmentOptions.Center);
        labelText.color = selected ? new Color(0.98f, 1f, 1f, 1f) : new Color(0.91f, 0.96f, 1f, 1f);
        return button;
    }

    private static GameObject CreateQuickCustomColumn(string name, Transform parent)
    {
        GameObject column = CreateRectObject(name, parent);
        VerticalLayoutGroup layout = column.AddComponent<VerticalLayoutGroup>();
        layout.spacing = 6f;
        layout.childControlWidth = true;
        layout.childControlHeight = true;
        layout.childForceExpandWidth = true;
        layout.childForceExpandHeight = false;
        return column;
    }

    private static TMP_InputField CreateQuickCustomSeedInput(string name, Transform parent, string value)
    {
        GameObject inputObject = CreateRectObject(name, parent);
        LayoutElement layout = inputObject.AddComponent<LayoutElement>();
        layout.preferredHeight = 56f;
        Image background = inputObject.AddComponent<Image>();
        background.color = Color.white;
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsDropdownPath);
        background.type = Image.Type.Sliced;
        TMP_InputField input = inputObject.AddComponent<TMP_InputField>();

        TMP_Text label = CreateText("LabelText", inputObject.transform, "Seed", 22f, TextAlignmentOptions.Left);
        ConfigureSingleLineText(label);
        RectTransform labelRect = (RectTransform)label.transform;
        labelRect.anchorMin = new Vector2(0.06f, 0.12f);
        labelRect.anchorMax = new Vector2(0.28f, 0.88f);

        TMP_Text text = CreateText("Text", inputObject.transform, value, 22f, TextAlignmentOptions.Right);
        ConfigureSingleLineText(text);
        RectTransform textRect = (RectTransform)text.transform;
        textRect.anchorMin = new Vector2(0.32f, 0.12f);
        textRect.anchorMax = new Vector2(0.92f, 0.88f);
        text.color = new Color(0.90f, 0.95f, 0.96f, 1f);

        input.textComponent = text;
        input.lineType = TMP_InputField.LineType.SingleLine;
        input.SetTextWithoutNotify(value);
        input.characterLimit = 9;
        input.contentType = TMP_InputField.ContentType.IntegerNumber;
        return input;
    }

