    private static WarlineCaptureSagaMissionNodeMetadata CreateSagaNode(string name, Transform parent, string code, MissionConfig mission, string frameLayer, float x, float y, bool routesToBriefing, bool locked = false, string lockedReason = "")
    {
        Button node = CreateCampaignButton(name, parent, SagaMapGeneratedRoot, frameLayer, !locked, 144f, 118f);
        node.interactable = !locked;
        ConfigurePixelRect((RectTransform)node.transform, x, y, 144f, 118f, 1198f, 618f);
        WarlineCaptureSagaMissionNodeMetadata metadata = node.gameObject.AddComponent<WarlineCaptureSagaMissionNodeMetadata>();
        SetSerializedString(metadata, "missionId", mission.MissionId);
        SetSerializedInt(metadata, "chapterIndex", 1);
        SetSerializedInt(metadata, "missionIndex", GetMissionIndexFromCode(code));
        SetSerializedBool(metadata, "locked", locked);
        SetSerializedString(metadata, "lockedReason", lockedReason);

        TMP_Text codeText = CreateText("CodeText", node.transform, code, 24f, TextAlignmentOptions.Center);
        codeText.fontStyle = FontStyles.Bold;
        ConfigurePixelRect((RectTransform)codeText.transform, 14f, 15f, 116f, 30f, 144f, 118f);
        TMP_Text titleText = CreateText("TitleText", node.transform, mission.DisplayName, 13f, TextAlignmentOptions.Center);
        titleText.fontStyle = FontStyles.Bold;
        titleText.enableAutoSizing = true;
        titleText.fontSizeMin = 10f;
        titleText.fontSizeMax = 13f;
        ConfigurePixelRect((RectTransform)titleText.transform, 12f, 60f, 120f, 36f, 144f, 118f);
        Image lockIcon = CreateCampaignImage("LockIcon", node.transform, SagaMapGeneratedRoot, "icon_lock.png");
        ConfigurePixelRect((RectTransform)lockIcon.transform, 55f, 42f, 34f, 34f, 144f, 118f);
        lockIcon.gameObject.SetActive(locked);

        Image star = CreateCampaignImage("StarIcon", node.transform, SagaMapGeneratedRoot, "icon_star.png");
        ConfigurePixelRect((RectTransform)star.transform, 104f, 12f, 26f, 26f, 144f, 118f);
        star.gameObject.SetActive(!locked);

        if (routesToBriefing)
        {
            WarlineCaptureMissionSessionButton missionSession = node.gameObject.AddComponent<WarlineCaptureMissionSessionButton>();
            SetSerializedString(missionSession, "missionId", mission.MissionId);
            SetSerializedEnum(missionSession, "returnRoute", (int)WarlineCaptureRoute.SagaMap);
            ScreenRouteButton route = node.gameObject.AddComponent<ScreenRouteButton>();
            SetSerializedEnum(route, "route", (int)WarlineCaptureRoute.MissionBriefing);
        }

        return metadata;
    }

    private static int GetMissionIndexFromCode(string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return 0;

        int separator = code.LastIndexOf('-');
        if (separator < 0 || separator >= code.Length - 1)
            return 0;

        return int.TryParse(code[(separator + 1)..], out int value) ? value : 0;
    }

