    private static void CreateLoadoutShell(Transform parent)
    {
        Image fill = CreateCampaignImage("ShellFill", parent, LoadoutGeneratedRoot, "screen_shell_fill.png");
        Stretch((RectTransform)fill.transform);
        Sprite underlay = AssetDatabase.LoadAssetAtPath<Sprite>(CampaignLayerPath(LoadoutGeneratedRoot, "target_depth_underlay.png"));
        if (underlay != null)
        {
            fill.sprite = underlay;
            fill.type = Image.Type.Simple;
        }
        else
        {
            fill.type = Image.Type.Sliced;
        }

        Image frame = CreateCampaignImage("ShellFrame", parent, LoadoutGeneratedRoot, "screen_shell_frame.png");
        Stretch((RectTransform)frame.transform);
        frame.type = Image.Type.Sliced;
    }

