    private static void CreateLoadoutSummaryPanel(Transform parent, string name, string title, string[] labels, string[] values, float y, bool star)
    {
        GameObject panel = CreateCampaignPanel(name, parent, LoadoutGeneratedRoot, star ? "star_goal_panel_frame.png" : "objective_panel_frame.png", 20f, y, 392f, 180f, 432f, 762f);
        TMP_Text titleText = CreateText("TitleText", panel.transform, title, 20f, TextAlignmentOptions.Left);
        titleText.fontStyle = FontStyles.Bold;
        ConfigurePixelRect((RectTransform)titleText.transform, 34f, 16f, 310f, 28f, 392f, 180f);
        string[] objectiveIcons =
        {
            "objective_crosshair_target_icon.png",
            "objective_shield_target_icon.png",
            "objective_flag_target_icon.png"
        };
        for (int i = 0; i < labels.Length; i++)
        {
            Image icon = CreateCampaignImage($"Row_{i + 1}_Icon", panel.transform, star ? LoadoutGeneratedRoot : LoadoutTargetCropRoot, star ? "icon_star.png" : objectiveIcons[Mathf.Min(i, objectiveIcons.Length - 1)]);
            icon.preserveAspect = true;
            ConfigurePixelRect((RectTransform)icon.transform, 22f, 55f + i * 38f, 30f, 30f, 392f, 180f);
            TMP_Text label = CreateText($"Row_{i + 1}_LabelText", panel.transform, labels[i], 17f, TextAlignmentOptions.Left);
            label.enableAutoSizing = true;
            label.fontSizeMin = 13f;
            label.fontSizeMax = 17f;
            label.textWrappingMode = TextWrappingModes.NoWrap;
            label.overflowMode = TextOverflowModes.Ellipsis;
            ConfigurePixelRect((RectTransform)label.transform, 62f, 54f + i * 38f, 246f, 30f, 392f, 180f);
            TMP_Text value = CreateText($"Row_{i + 1}_ValueText", panel.transform, values[i], 18f, TextAlignmentOptions.Right);
            value.fontStyle = FontStyles.Bold;
            value.color = star ? new Color(1f, 0.74f, 0.10f, 1f) : new Color(0.10f, 0.82f, 1f, 1f);
            ConfigurePixelRect((RectTransform)value.transform, star ? 292f : 316f, 54f + i * 38f, 54f, 30f, 392f, 180f);
            if (star)
            {
                Image badge = CreateCampaignImage($"Row_{i + 1}_RewardBadge", panel.transform, LoadoutTargetCropRoot, "star_reward_badge_target_icon.png");
                badge.preserveAspect = true;
                ConfigurePixelRect((RectTransform)badge.transform, 352f, 54f + i * 38f, 24f, 28f, 392f, 180f);
            }
        }
    }

