    private static void ConfigureSagaCampaignMultilineText(GameObject screen)
    {
        foreach (string path in new[]
        {
            "NodeInfoPanel/SelectedBodyText",
            "BriefingText/BodyText"
        })
        {
            Transform target = screen.transform.Find(path);
            if (target == null || !target.TryGetComponent(out TMP_Text text))
                continue;
            text.textWrappingMode = TextWrappingModes.Normal;
            text.overflowMode = TextOverflowModes.Overflow;
        }
    }

    private static void ConfigureLoadoutText(GameObject screen)
    {
        foreach (TMP_Text text in screen.GetComponentsInChildren<TMP_Text>(true))
        {
            text.richText = true;
            if (text.name.Contains("LabelText") || text.name.Contains("TitleText") || text.name.Contains("ValueText"))
                text.textWrappingMode = TextWrappingModes.NoWrap;
            if (text.name.Contains("LabelText") || text.name.Contains("TitleText"))
                text.overflowMode = TextOverflowModes.Ellipsis;
        }
    }

