        GameObject panel = CreateCampaignPanel(name, parent, MissionBriefingGeneratedRoot, frame, x, y, 498f, 262f);
        TMP_Text titleText = CreateText("TitleText", panel.transform, title, 23f, TextAlignmentOptions.Left);
