        ConfigurePixelRect((RectTransform)titleText.transform, 28f, 20f, 430f, 32f, 498f, 262f);
        for (int i = 0; i < rows.Length; i++)
        {
            TMP_Text row = CreateText($"Row_{i + 1}_Text", panel.transform, rows[i], 21f, TextAlignmentOptions.Left);
            row.color = new Color(0.82f, 0.90f, 0.90f, 1f);
            row.textWrappingMode = TextWrappingModes.NoWrap;
            row.overflowMode = TextOverflowModes.Ellipsis;
            ConfigurePixelRect((RectTransform)row.transform, 48f, 76f + i * 48f, 400f, 34f, 498f, 262f);

            Image bullet = CreateCampaignImage($"Row_{i + 1}_Icon", panel.transform, MissionBriefingGeneratedRoot, star ? "icon_star.png" : "icon_intel.png");
            ConfigurePixelRect((RectTransform)bullet.transform, 24f, 80f + i * 48f, 20f, 20f, 498f, 262f);
        }
    }

