    private static TMP_Text CreateCampaignText(Transform parent, string name, string value, float fontSize, float x, float y, float width, float height, bool bold, Color? color = null)
    {
        TMP_Text text = CreateText(name, parent, value, fontSize, TextAlignmentOptions.Left);
        text.fontStyle = bold ? FontStyles.Bold : FontStyles.Normal;
        text.color = color ?? new Color(0.92f, 0.97f, 0.97f, 1f);
        text.textWrappingMode = TextWrappingModes.Normal;
        text.overflowMode = TextOverflowModes.Overflow;
        RectTransform parentRect = (RectTransform)parent;
        float referenceWidth = parentRect.rect.width > 0f ? parentRect.rect.width : parentRect.sizeDelta.x > 0f ? parentRect.sizeDelta.x : MainMenuReferenceResolution.x;
        float referenceHeight = parentRect.rect.height > 0f ? parentRect.rect.height : parentRect.sizeDelta.y > 0f ? parentRect.sizeDelta.y : MainMenuReferenceResolution.y;
        ConfigurePixelRect((RectTransform)text.transform, x, y, width, height, referenceWidth, referenceHeight);
        return text;
    }

