    private static Button CreateArmoryButton(string name, Transform parent, string spritePath, bool selected, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        SetSize(buttonObject, width, height);
        Image background = buttonObject.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(spritePath);
        background.type = Image.Type.Sliced;
        background.color = Color.white;
        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureAnimatedButton(button, selected);
        return button;
    }

    private static Image CreateArmoryIcon(string name, Transform parent, string iconFile)
    {
        Image icon = CreateImage(name, parent, Color.white);
        icon.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(ArmoryLayerPath(iconFile));
        icon.preserveAspect = true;
        icon.raycastTarget = false;
        return icon;
    }

    private static GameObject CreateCommandExchangeScreen()
    {
        GameObject screen = CreateRectObject("Screen_CommandExchange", null);
        WarlineCaptureScreenController controller = screen.AddComponent<WarlineCaptureScreenController>();
        controller.SetRouteForTests(WarlineCaptureRoute.CommandExchange);

        Image shellFill = CreateImage("ShellFill", screen.transform, Color.white);
        Stretch((RectTransform)shellFill.transform);
        Sprite depthUnderlay = AssetDatabase.LoadAssetAtPath<Sprite>(CommandExchangeLayerPath("Frames/target_depth_underlay.png"));
        if (depthUnderlay != null)
        {
            shellFill.sprite = depthUnderlay;
            shellFill.type = Image.Type.Simple;
        }
        else
        {
            shellFill.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(CommandExchangeLayerPath("Frames/screen_shell_fill.png"));
            shellFill.type = Image.Type.Sliced;
        }
        shellFill.raycastTarget = false;

        Image shellFrame = CreateImage("ShellFrame", screen.transform, Color.white);
        Stretch((RectTransform)shellFrame.transform);
        shellFrame.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(CommandExchangeLayerPath("Frames/screen_shell_frame.png"));
        shellFrame.type = Image.Type.Sliced;
        shellFrame.raycastTarget = false;

        CreateCommandExchangeHeader(screen.transform);
        CreateCommandExchangeCategoryRail(screen.transform);
        CreateCommandExchangeFeaturedPanel(screen.transform);
        CreateCommandExchangeStarterPacks(screen.transform);
        CreateCommandExchangeShopGrid(screen.transform);
        CreateCommandExchangeFooter(screen.transform);

        ApplyScreenTypography(
            screen,
            "HeaderBar/TitleText",
            "CategoryRail/FeaturedButton/LabelText",
            "FeaturedPanel/TitleText",
            "StarterPacksTitleText",
            "ShopItemsTitleText",
            "FooterBrandText");
        return screen;
    }

