    private static void CreateCommandExchangeStarterCard(string name, Transform parent, string artPath, string title, string subtitle, string priceText, float x, float y, float width, bool selected)
    {
        Button card = CreateCommandExchangeButton(name, parent, selected ? "Cards/starter_pack_card_frame.png" : "Cards/starter_pack_card_frame.png", selected, width, 202f);
        ConfigurePixelRect((RectTransform)card.transform, x, y, width, 202f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);

        TMP_Text titleText = CreateText("TitleText", card.transform, title, title.Length > 18 ? 22f : 25f, TextAlignmentOptions.Left);
        titleText.fontStyle = FontStyles.Bold;
        titleText.color = new Color(0.94f, 0.97f, 0.96f, 1f);
        titleText.enableAutoSizing = true;
        titleText.fontSizeMin = 17f;
        titleText.fontSizeMax = title.Length > 18 ? 22f : 25f;
        ConfigurePixelRect((RectTransform)titleText.transform, 22f, 15f, width - 44f, 36f, width, 202f);

        TMP_Text subtitleText = CreateText("SubtitleText", card.transform, subtitle, 16f, TextAlignmentOptions.Left);
        subtitleText.color = new Color(0.72f, 0.80f, 0.82f, 1f);
        subtitleText.fontStyle = FontStyles.Bold;
        ConfigurePixelRect((RectTransform)subtitleText.transform, 22f, 51f, width - 44f, 26f, width, 202f);

        string contentArtPath = artPath;
        float artX = width - 226f;
        float artY = 30f;
        float artWidth = 204f;
        float artHeight = 118f;
        bool preserveAspect = true;
        if (name == "ReconPackCard")
        {
            contentArtPath = "Content/target_recon_pack_content.png";
            artX = 24f;
            artY = 78f;
            artWidth = 360f;
            artHeight = 94f;
            preserveAspect = false;
        }
        else if (name == "BaseBuilderPackCard")
        {
            contentArtPath = "Content/target_base_builder_pack_content.png";
            artX = 18f;
            artY = 76f;
            artWidth = 420f;
            artHeight = 94f;
            preserveAspect = false;
        }
        else if (name == "OperationFounderPackCard")
        {
            contentArtPath = "Content/target_operation_founder_pack_content.png";
            artX = 20f;
            artY = 76f;
            artWidth = 430f;
            artHeight = 96f;
            preserveAspect = false;
        }

        Image art = CreateCommandExchangeArt("ArtImage", card.transform, contentArtPath, preserveAspect);
        ConfigurePixelRect((RectTransform)art.transform, artX, artY, artWidth, artHeight, width, 202f);

        Button price = CreateCommandExchangePriceButton("PriceButton", card.transform, priceText, width - 132f, 156f, 118f, 34f, width, 202f);
        price.interactable = false;
    }

