    private static Button CreateCommandExchangeButton(string name, Transform parent, string spritePath, bool selected, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        SetSize(buttonObject, width, height);
        Image background = buttonObject.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(CommandExchangeLayerPath(spritePath));
        background.type = Image.Type.Sliced;
        background.color = Color.white;
        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureAnimatedButton(button, selected);
        return button;
    }

    private static Image CreateCommandExchangeIcon(string name, Transform parent, string iconPath)
    {
        Image icon = CreateImage(name, parent, Color.white);
        icon.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(CommandExchangeLayerPath(iconPath));
        icon.preserveAspect = true;
        icon.raycastTarget = false;
        return icon;
    }

    private static Image CreateCommandExchangeArt(string name, Transform parent, string artPath, bool preserveAspect = true)
    {
        Image art = CreateImage(name, parent, Color.white);
        art.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(CommandExchangeLayerPath(artPath));
        art.preserveAspect = preserveAspect;
        art.raycastTarget = false;
        return art;
    }

    private struct DesignedUnavailableCard
    {
        public readonly string Title;
        public readonly string Status;
        public readonly string Body;

        public DesignedUnavailableCard(string title, string status, string body)
        {
            Title = title;
            Status = status;
            Body = body;
        }
    }

    private struct DesignedUnavailableFeed
    {
        public readonly string Tag;
        public readonly string Body;

        public DesignedUnavailableFeed(string tag, string body)
        {
            Tag = tag;
            Body = body;
        }
    }

