        SaveScreenPrefab(CreateEventsScreen(), $"{ScreensFolder}/Screen_Events.prefab");
        SaveScreenPrefab(CreateRankingScreen(), $"{ScreensFolder}/Screen_Ranking.prefab");
        SaveScreenPrefab(CreateCommandFeedScreen(), $"{ScreensFolder}/Screen_CommandFeed.prefab");
        SaveScreenPrefab(CreateOperationDashboardScreen(), $"{ScreensFolder}/Screen_OperationDashboard.prefab");
        SaveScreenPrefab(CreateDistrictDetailScreen(), $"{ScreensFolder}/Screen_DistrictDetail.prefab");
    }

    private static GameObject CreateCommanderProfileScreen()
    {
        GameObject screen = CreateDesignedUnavailableScreen(
            "Screen_CommanderProfile",
            WarlineCaptureRoute.CommanderProfile,
            CommanderProfileGeneratedRoot,
            "COMMANDER PROFILE",
            "PROFILE / PROGRESSION",
            "PROFILE SHELL READY",
            "Commander stats, upgrade links, cosmetics, and history will bind here after profile persistence is enabled.",
            new[] { "OVERVIEW", "UPGRADES", "HISTORY", "COSMETICS", "STATS", "SETTINGS" },
            new[]
            {
                new DesignedUnavailableCard("COMMAND LEVEL", "LV. 32", "Commander XP and rank rewards bind to profile data."),
                new DesignedUnavailableCard("UPGRADE LINKS", "Armory ready", "Owned unit and upgrade details open through Armory."),
                new DesignedUnavailableCard("BATTLE HISTORY", "No saved report", "Mission results will populate this panel.")
            },
            new[]
            {
                new DesignedUnavailableFeed("PROFILE", "Local commander profile route is active."),
                new DesignedUnavailableFeed("ARMORY", "Upgrade details are available through the Armory shell."),
                new DesignedUnavailableFeed("HISTORY", "Battle report persistence is pending.")
            });
        CreateCommanderProfileRewardTrackPanel(screen.transform, CommanderProfileGeneratedRoot);
        ApplyCommanderProfileTargetLayout(screen.transform, CommanderProfileGeneratedRoot);
        screen.AddComponent<CommanderProfileScreenController>();
        return screen;
    }

    private static void ApplyCommanderProfileTargetLayout(Transform screen, string generatedRoot)
    {
        Transform shellFrame = screen.Find("ShellFrame");
        if (shellFrame != null && shellFrame.TryGetComponent(out Image shellFrameImage))
        {
            shellFrameImage.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(DesignedUnavailableLayerPath(generatedRoot, "Frames/screen_shell_frame.png"));
            shellFrameImage.type = Image.Type.Sliced;
            shellFrameImage.color = Color.white;
            foreach (Image border in shellFrame.GetComponentsInChildren<Image>(true))
            {
                if (border.name.StartsWith("Border_"))
                    border.gameObject.SetActive(false);
            }
        }

        Transform header = screen.Find("HeaderBar");
        if (header != null)
        {
            ConfigurePixelRect((RectTransform)header, 24f, 22f, 1624f, 98f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
            if (header.TryGetComponent(out Image headerImage))
            {
                headerImage.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(DesignedUnavailableLayerPath(generatedRoot, "Frames/header_bar_frame.png"));
                headerImage.type = Image.Type.Sliced;
                headerImage.color = Color.white;
            }
            foreach (Image border in header.GetComponentsInChildren<Image>(true))
            {
                if (border.name.StartsWith("Border_"))
                    border.gameObject.SetActive(false);
            }

            foreach (string counterName in new[] { "CreditsCounter", "MaterialsCounter", "AuthorityCounter" })
            {
                Transform counter = header.Find(counterName);
                if (counter != null)
                    counter.gameObject.SetActive(false);
            }

            Transform title = header.Find("TitleText");
            if (title != null && title.TryGetComponent(out TMP_Text titleText))
            {
                titleText.fontSize = 48f;
                titleText.fontSizeMax = 48f;
                titleText.characterSpacing = 3f;
                ConfigurePixelRect((RectTransform)title, 176f, 20f, 720f, 60f, 1624f, 98f);
            }

            Transform backButton = header.Find("BackButton");
            if (backButton != null)
            {
                ConfigurePixelRect((RectTransform)backButton, 30f, 14f, 88f, 64f, 1624f, 98f);
                Transform backIconText = backButton.Find("IconText");
                if (backIconText != null)
                    backIconText.gameObject.SetActive(false);
                Image backIcon = CreateDesignedUnavailableIcon("IconImage", backButton, generatedRoot, "Icons/back_chevron_icon.png");
                ConfigurePixelRect((RectTransform)backIcon.transform, 22f, 14f, 42f, 36f, 88f, 64f);
            }

            Transform settingsButton = header.Find("SettingsButton");
            if (settingsButton != null)
            {
                ConfigurePixelRect((RectTransform)settingsButton, 1508f, 14f, 78f, 66f, 1624f, 98f);
                Transform gearText = settingsButton.Find("GearIcon");
                if (gearText != null)
                    gearText.gameObject.SetActive(false);
                Image gearIcon = CreateDesignedUnavailableIcon("IconImage", settingsButton, generatedRoot, "Icons/settings_gear_icon.png");
                ConfigurePixelRect((RectTransform)gearIcon.transform, 18f, 12f, 42f, 42f, 78f, 66f);
            }
        }

        Transform rail = screen.Find("CategoryRail");
        if (rail != null)
        {
            ConfigurePixelRect((RectTransform)rail, 488f, 144f, 1086f, 72f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
            string[] labels = { "OVERVIEW", "UPGRADES", "STATS", "BADGES", "HISTORY", "SETTINGS" };
            for (int i = 0; i < labels.Length; i++)
            {
                Transform tab = rail.Find($"Tab_{i + 1}");
                if (tab == null)
                    continue;

                float width = i < 4 ? 266f : 0f;
                ConfigurePixelRect((RectTransform)tab, i * 280f, 0f, Mathf.Max(1f, width), 68f, 1086f, 72f);
                if (i >= 4)
                {
                    tab.gameObject.SetActive(false);
                    continue;
                }

                if (tab.TryGetComponent(out Image tabBackground))
                {
                    tabBackground.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(
                        DesignedUnavailableLayerPath(generatedRoot, i == 0 ? "Buttons/nav_button_selected_background.png" : "Buttons/nav_button_normal_background.png"));
                    tabBackground.type = Image.Type.Sliced;
                    tabBackground.color = Color.white;
                }
                if (tab.TryGetComponent(out Button tabButton))
                    ForceWhiteButtonTint(tabButton);
                foreach (Image border in tab.GetComponentsInChildren<Image>(true))
                {
                    if (border.name.StartsWith("Border_"))
                        border.gameObject.SetActive(false);
                }

                Transform iconText = tab.Find("IconText");
                if (iconText != null)
                    iconText.gameObject.SetActive(false);

                Transform icon = tab.Find("IconImage");
                if (icon != null)
                    icon.gameObject.SetActive(false);

                Transform label = tab.Find("LabelText");
                if (label != null && label.TryGetComponent(out TMP_Text labelText))
                {
                    labelText.text = labels[i];
                    labelText.alignment = TextAlignmentOptions.Center;
                    labelText.fontSize = 24f;
                    labelText.fontSizeMax = 24f;
                    labelText.fontSizeMin = 16f;
                    ConfigurePixelRect((RectTransform)label, 18f, 10f, 230f, 48f, 266f, 68f);
                }
            }
        }

        CreateCommanderProfilePortraitPanel(screen, generatedRoot);
        ConfigureCommanderProfileHero(screen);
        ConfigureCommanderProfileStatCards(screen);
        ConfigureCommanderProfileRewardTrack(screen, generatedRoot);
        ConfigureCommanderProfileFeed(screen);
    }

