    private static void ConfigureCommanderProfileStatCards(Transform screen)
    {
        string[] titles = { "Power Rating", "Victories", "Units Unlocked" };
        string[] statuses = { "58,720", "146", "38" };
        string[] icons =
        {
            "Content/profile_icon_power_clean.png",
            "Content/profile_icon_victory_clean.png",
            "Content/profile_icon_units_clean.png"
        };
        for (int i = 0; i < 3; i++)
        {
            Transform card = screen.Find($"StatusCard_{i + 1}");
            if (card == null)
                continue;

            ConfigurePixelRect((RectTransform)card, 488f + i * 282f, 230f, 268f, 288f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
