            new Vector4(246f, 183f, 126f, 33f),
            new Vector4(459f, 183f, 127f, 33f),
            new Vector4(694f, 183f, 128f, 33f),
            new Vector4(909f, 183f, 128f, 33f)
        };

        for (int i = 0; i < 3; i++)
        {
            Transform existingNode = panel.Find($"TrackNode_{i + 1}");
            if (existingNode != null)
                existingNode.gameObject.SetActive(false);
        }

        for (int i = 0; i < 4; i++)
        {
            Image connector = CreateImage($"TrackConnector_{i + 1}", panel, new Color(0.04f, 0.84f, 1f, 0.82f));
            ConfigurePixelRect((RectTransform)connector.transform, 178f + i * 206f, 139f, 72f, 6f, 1088f, 246f);
            connector.raycastTarget = false;
        }

        for (int i = 0; i < 5; i++)
        {
            Image node = CreateDesignedUnavailableArt($"RewardNode_{(i + 1) * 10}TargetComposite", panel, generatedRoot, nodeLayers[i]);
            Vector4 rect = nodeRects[i];
            ConfigurePixelRect((RectTransform)node.transform, rect.x, rect.y, rect.z, rect.w, 1088f, 246f);
            node.preserveAspect = false;
            node.transform.SetAsLastSibling();

            Image plaque = CreateDesignedUnavailableArt($"RewardNode_{(i + 1) * 10}PlaqueTargetComposite", panel, generatedRoot, plaqueLayers[i]);
            Vector4 plaqueRect = plaqueRects[i];
            ConfigurePixelRect((RectTransform)plaque.transform, plaqueRect.x, plaqueRect.y, plaqueRect.z, plaqueRect.w, 1088f, 246f);
            plaque.preserveAspect = false;
            plaque.transform.SetAsLastSibling();
        }
    }

    private static void ConfigureCommanderProfileFeed(Transform screen)
    {
        Transform feedTitle = screen.Find("FeedTitleText");
        if (feedTitle != null)
        {
            ConfigurePixelRect((RectTransform)feedTitle, 54f, 902f, 220f, 28f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
            feedTitle.gameObject.SetActive(false);
        }

        for (int i = 0; i < 3; i++)
        {
            Transform row = screen.Find($"FeedRow_{i + 1}");
            if (row == null)
                continue;

            row.gameObject.SetActive(false);
            ConfigurePixelRect((RectTransform)row, 278f + i * 382f, 890f, 352f, 36f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
            Transform tag = row.Find("TagText");
            if (tag != null)
                ConfigurePixelRect((RectTransform)tag, 16f, 4f, 76f, 28f, 352f, 36f);

            Transform body = row.Find("BodyText");
            if (body != null)
                ConfigurePixelRect((RectTransform)body, 94f, 4f, 238f, 28f, 352f, 36f);
        }
    }

    private static void CreateCommanderProfileRewardTrackPanel(Transform screen, string generatedRoot)
    {
        Transform panel = screen.Find("ImplementationNotePanel");
        if (panel == null)
            return;

        panel.name = "RewardTrackPanel";

        Transform title = panel.Find("TitleText");
        if (title != null && title.TryGetComponent(out TMP_Text titleText))
            titleText.text = "REWARD TRACK";

        Transform body = panel.Find("BodyText");
        if (body != null && body.TryGetComponent(out TMP_Text bodyText))
        {
            bodyText.text = "Claim deterministic commander milestones.";
            bodyText.fontSize = 13f;
            bodyText.enableAutoSizing = true;
            bodyText.fontSizeMin = 10f;
            bodyText.fontSizeMax = 13f;
            ConfigurePixelRect((RectTransform)bodyText.transform, 28f, 50f, 384f, 22f, 440f, 154f);
        }

        for (int i = 0; i < 3; i++)
        {
            Button row = CreateDesignedUnavailableButton($"TrackNode_{i + 1}", panel, generatedRoot, "Frames/resource_counter_frame.png", i == 0, 384f, 24f);
            ConfigurePixelRect((RectTransform)row.transform, 28f, 74f + i * 25f, 384f, 24f, 440f, 154f);

            TMP_Text levelText = CreateText("LevelText", row.transform, $"LV. {i + 2}", 12f, TextAlignmentOptions.Left);
            levelText.fontStyle = FontStyles.Bold;
            levelText.color = new Color(0.96f, 0.68f, 0.18f, 1f);
            ConfigurePixelRect((RectTransform)levelText.transform, 10f, 2f, 54f, 20f, 384f, 24f);

            TMP_Text nodeTitle = CreateText("TitleText", row.transform, i == 0 ? "Field Budget" : i == 1 ? "Material Reserve" : "Rapid Orders", 12f, TextAlignmentOptions.Left);
            nodeTitle.fontStyle = FontStyles.Bold;
            nodeTitle.color = new Color(0.88f, 0.96f, 0.96f, 1f);
            ConfigurePixelRect((RectTransform)nodeTitle.transform, 70f, 2f, 154f, 20f, 384f, 24f);

            TMP_Text statusText = CreateText("StatusText", row.transform, i == 0 ? "READY" : "LOCKED", 11f, TextAlignmentOptions.Right);
            statusText.fontStyle = FontStyles.Bold;
            statusText.color = i == 0 ? new Color(0.10f, 0.86f, 1f, 1f) : new Color(0.62f, 0.70f, 0.72f, 1f);
            ConfigurePixelRect((RectTransform)statusText.transform, 236f, 2f, 136f, 20f, 384f, 24f);
        }
    }

