    private static GameObject CreateOperationRouteRoot(string screenName, WarlineCaptureRoute route)
    {
        GameObject screen = CreateRectObject(screenName, null);
        WarlineCaptureScreenController controller = screen.AddComponent<WarlineCaptureScreenController>();
        controller.SetRouteForTests(route);

        Image shellFill = CreateImage("ShellFill", screen.transform, new Color(0.003f, 0.018f, 0.022f, 1f));
        Stretch((RectTransform)shellFill.transform);
        shellFill.raycastTarget = false;
        CreateOperationPanel("OuterShellFrame", screen.transform, 8f, 8f, 1656f, 925f, OperationPanelFrameCyanPath);
        return screen;
    }

    private static void CreateOperationHeader(Transform parent, string title, string subtitle, string generatedRoot)
    {
        GameObject header = CreateOperationPanel("HeaderBar", parent, 32f, 30f, 1608f, 78f, OperationPanelFrameCyanPath);
        Button backButton = CreateOperationIconButton("BackButton", header.transform, OperationIconBackPath, 10f, 8f, 96f, 62f, 1608f, 78f);
        ScreenRouteButton backRoute = backButton.gameObject.AddComponent<ScreenRouteButton>();
        SetSerializedBool(backRoute, "useBackNavigation", true);

        TMP_Text titleText = CreateText("TitleText", header.transform, title, title.Length > 18 ? 40f : 48f, TextAlignmentOptions.Left);
        titleText.color = new Color(0.92f, 0.94f, 0.94f, 1f);
        titleText.fontStyle = FontStyles.Bold;
        titleText.characterSpacing = 1f;
        ConfigurePixelRect((RectTransform)titleText.transform, 150f, 10f, 560f, 62f, 1608f, 78f);

        Image calendar = CreateOperationImage("CalendarIcon", header.transform, OperationDashboardCalendarIconPath);
        calendar.preserveAspect = true;
        ConfigurePixelRect((RectTransform)calendar.transform, 702f, 17f, 42f, 42f, 1608f, 78f);

        TMP_Text dayTime = CreateText("DayTimeText", header.transform, subtitle, subtitle.Length > 16 ? 27f : 30f, TextAlignmentOptions.Left);
        dayTime.color = subtitle.Contains("HIGH") ? new Color(1f, 0.30f, 0.20f, 1f) : new Color(0.96f, 0.96f, 0.92f, 1f);
        ConfigurePixelRect((RectTransform)dayTime.transform, 756f, 17f, 270f, 44f, 1608f, 78f);

        CreateOperationResourceCounter("CreditsCounter", header.transform, DesignedUnavailableLayerPath(generatedRoot, "Icons/icon_credits.png"), "24.8K", 1000f, 144f);
        CreateOperationResourceCounter("MaterialsCounter", header.transform, DesignedUnavailableLayerPath(generatedRoot, "Icons/icon_materials.png"), "12.6K", 1150f, 144f);
        CreateOperationResourceCounter("GemsCounter", header.transform, DesignedUnavailableLayerPath(generatedRoot, "Icons/icon_rush_ticket.png"), "1,250", 1300f, 144f);
        CreateOperationResourceCounter("PopulationCounter", header.transform, OperationIconPeoplePath, "68/80", 1438f, 130f);

        Button settings = CreateOperationIconButton("SettingsButton", header.transform, OperationIconGearPath, 1568f, 8f, 58f, 62f, 1608f, 78f);
        ScreenRouteButton settingsRoute = settings.gameObject.AddComponent<ScreenRouteButton>();
        SetSerializedEnum(settingsRoute, "route", (int)WarlineCaptureRoute.Settings);
    }

    private static GameObject CreateOperationPanel(string name, Transform parent, float x, float y, float width, float height, string framePath, float referenceWidth = 1672f, float referenceHeight = 941f)
    {
        GameObject panel = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)panel.transform, x, y, width, height, referenceWidth, referenceHeight);
        Image fill = CreateOperationImage("FillBackground", panel.transform, OperationPanelFillPath);
        fill.type = Image.Type.Sliced;
        Stretch((RectTransform)fill.transform);
        Image frame = CreateOperationImage("FrameChrome", panel.transform, framePath);
        frame.type = Image.Type.Sliced;
        Stretch((RectTransform)frame.transform);
        return panel;
    }

    private static Image CreateOperationImage(string name, Transform parent, string path)
    {
        Image image = CreateImage(name, parent, Color.white);
        image.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(path);
        image.raycastTarget = false;
        image.preserveAspect = false;
        return image;
    }

    private static void CreateOperationSectionTitle(Transform parent, string title, float x, float y, float width, float referenceWidth, float referenceHeight)
    {
        Image accent = CreateImage("TitleAccent", parent, FlatTargetCyan);
        ConfigurePixelRect((RectTransform)accent.transform, x - 12f, y + 6f, 5f, 28f, referenceWidth, referenceHeight);
        TMP_Text titleText = CreateText("SectionTitleText", parent, title, 28f, TextAlignmentOptions.Left);
        titleText.color = new Color(0.90f, 0.94f, 0.94f, 1f);
        titleText.fontStyle = FontStyles.Bold;
        ConfigurePixelRect((RectTransform)titleText.transform, x, y, width, 42f, referenceWidth, referenceHeight);
    }

    private static void CreateOperationResourceCounter(string name, Transform parent, string iconPath, string value, float x, float width)
    {
        GameObject counter = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)counter.transform, x, 13f, width, 52f, 1608f, 78f);
        Image icon = CreateOperationImage("IconImage", counter.transform, iconPath);
        icon.preserveAspect = true;
        ConfigurePixelRect((RectTransform)icon.transform, 10f, 9f, 34f, 34f, width, 52f);
        TMP_Text valueText = CreateText("ValueText", counter.transform, value, width < 136f ? 22f : 24f, TextAlignmentOptions.Left);
        valueText.fontStyle = FontStyles.Bold;
        valueText.color = new Color(0.92f, 0.94f, 0.92f, 1f);
        valueText.enableAutoSizing = true;
        valueText.fontSizeMin = 18f;
        valueText.fontSizeMax = width < 136f ? 22f : 24f;
        ConfigurePixelRect((RectTransform)valueText.transform, 52f, 8f, width - 50f, 36f, width, 52f);
    }

    private static void CreateOperationMetric(Transform parent, string name, string iconPath, string label, string value, string state, float normalized, Color color, float y)
    {
        GameObject row = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)row.transform, 18f, y, 288f, 112f, 326f, 688f);
