        ConfigurePixelRect((RectTransform)icon.transform, 0f, 10f, 70f, 70f, 288f, 112f);
        TMP_Text labelText = CreateText("LabelText", row.transform, label, 20f, TextAlignmentOptions.Left);
        labelText.fontStyle = FontStyles.Bold;
        ConfigurePixelRect((RectTransform)labelText.transform, 84f, 0f, 190f, 28f, 288f, 112f);
        TMP_Text valueText = CreateText("ValueText", row.transform, value, 30f, TextAlignmentOptions.Left);
        valueText.fontStyle = FontStyles.Bold;
