        ConfigurePixelRect((RectTransform)valueText.transform, 84f, 30f, 100f, 38f, 288f, 112f);
        CreateOperationProgress(row.transform, "Progress", 84f, 70f, 210f, 14f, normalized, ProgressFillForColor(color), 288f, 112f);
        TMP_Text stateText = CreateText("StateText", row.transform, state, 17f, TextAlignmentOptions.Left);
        stateText.fontStyle = FontStyles.Bold;
        stateText.color = color;
        ConfigurePixelRect((RectTransform)stateText.transform, 84f, 86f, 160f, 24f, 288f, 112f);
    }

    private static string ProgressFillForColor(Color color)
    {
        if (color.r > 0.9f && color.g < 0.4f)
            return OperationProgressFillRedPath;
        if (color.r > 0.9f && color.g > 0.45f)
            return OperationProgressFillOrangePath;
        if (color.g > 0.8f)
            return OperationProgressFillGreenPath;
        return OperationProgressFillCyanPath;
    }

    private static void CreateOperationProgress(Transform parent, string name, float x, float y, float width, float height, float normalized, string fillPath, float referenceWidth, float referenceHeight)
    {
        GameObject root = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)root.transform, x, y, width, height, referenceWidth, referenceHeight);
        Image track = CreateOperationImage("Track", root.transform, OperationProgressTrackPath);
        track.type = Image.Type.Sliced;
        Stretch((RectTransform)track.transform);
        Image fill = CreateOperationImage("Fill", root.transform, fillPath);
        fill.type = Image.Type.Sliced;
        RectTransform fillRect = (RectTransform)fill.transform;
        fillRect.anchorMin = Vector2.zero;
        fillRect.anchorMax = new Vector2(Mathf.Clamp01(normalized), 1f);
        fillRect.offsetMin = Vector2.zero;
        fillRect.offsetMax = Vector2.zero;
    }

    private static void CreateOperationLegend(Transform parent)
    {
