        for (int i = 0; i < labels.Length; i++)
        {
            TMP_Text icon = CreateText($"LegendIcon_{i + 1}", legend.transform, i == 0 ? "S" : i == 1 ? "*" : "!", 20f, TextAlignmentOptions.Center);
