    private static Button CreateOperationButton(string name, Transform parent, string label, string fillPath, string framePath, float x, float y, float width, float height, float referenceWidth, float referenceHeight, float fontSize)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)buttonObject.transform, x, y, width, height, referenceWidth, referenceHeight);
        Image fill = CreateOperationImage("FillBackground", buttonObject.transform, fillPath);
        fill.type = Image.Type.Sliced;
        Stretch((RectTransform)fill.transform);
        Image frame = CreateOperationImage("FrameChrome", buttonObject.transform, framePath);
        frame.type = Image.Type.Sliced;
        Stretch((RectTransform)frame.transform);
        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = fill;
        ConfigureButtonTint(button, Color.white, new Color(0.86f, 0.98f, 1f, 1f), new Color(0.72f, 0.88f, 0.94f, 1f));
        if (!string.IsNullOrEmpty(label))
        {
            TMP_Text text = CreateText("LabelText", buttonObject.transform, label, fontSize, TextAlignmentOptions.Center);
            text.fontStyle = FontStyles.Bold;
            text.color = new Color(0.94f, 0.94f, 0.90f, 1f);
            ConfigurePixelRect((RectTransform)text.transform, 12f, 0f, width - 24f, height, width, height);
            ConfigureSingleLineText(text);
        }
        return button;
    }

