    private static void ConfigureOperationText(GameObject screen)
    {
        foreach (TMP_Text text in screen.GetComponentsInChildren<TMP_Text>(true))
        {
            text.overflowMode = TextOverflowModes.Overflow;
            text.textWrappingMode = text.text.Contains("\n") ? TextWrappingModes.Normal : TextWrappingModes.NoWrap;
        }
    }

    private static GameObject CreateDesignedUnavailableScreen(
        string screenName,
        WarlineCaptureRoute route,
        string generatedRoot,
        string title,
        string eyebrow,
        string heroTitle,
        string body,
        string[] tabs,
        DesignedUnavailableCard[] cards,
        DesignedUnavailableFeed[] feedItems)
    {
        GameObject screen = CreateRectObject(screenName, null);
        WarlineCaptureScreenController controller = screen.AddComponent<WarlineCaptureScreenController>();
        controller.SetRouteForTests(route);

        Image shellFill = CreateImage("ShellFill", screen.transform, FlatTargetScreenFill);
        Stretch((RectTransform)shellFill.transform);
        Sprite underlay = screenName == "Screen_CommanderProfile"
            ? AssetDatabase.LoadAssetAtPath<Sprite>(DesignedUnavailableLayerPath(generatedRoot, "target_blurred_underlay.png"))
            : null;
        if (underlay != null)
        {
            shellFill.color = Color.white;
            shellFill.sprite = underlay;
            shellFill.type = Image.Type.Simple;
        }
        shellFill.raycastTarget = false;

        CreateFlatPanel("ShellFrame", screen.transform, 10f, 8f, 1652f, 924f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y, Color.clear, FlatTargetCyanDim, 2f, false);

        CreateDesignedUnavailableHeader(screen.transform, generatedRoot, title);
        CreateDesignedUnavailableRail(screen.transform, generatedRoot, tabs);
        CreateDesignedUnavailableHero(screen.transform, generatedRoot, eyebrow, heroTitle, body);
        CreateDesignedUnavailableCards(screen.transform, generatedRoot, cards);
        CreateDesignedUnavailableFeed(screen.transform, generatedRoot, feedItems);
        CreateDesignedUnavailableNote(screen.transform, generatedRoot);

        ApplyScreenTypography(
            screen,
            "HeaderBar/TitleText",
            "CategoryRail/Tab_1/LabelText",
            "HeroPanel/HeroTitleText",
            "StatusPanelsTitleText",
            "FeedTitleText",
            "FooterBrandText");
        ConfigureDesignedUnavailableMultilineText(screen);
        return screen;
    }

    private static void ConfigureDesignedUnavailableMultilineText(GameObject screen)
    {
        foreach (string path in new[]
        {
            "HeroPanel/BodyText",
            "StatusCard_1/BodyText",
            "StatusCard_2/BodyText",
            "StatusCard_3/BodyText",
            "StatusCard_4/BodyText",
            "StatusCard_5/BodyText",
            "StatusCard_6/BodyText",
            "ImplementationNotePanel/BodyText",
            "RewardTrackPanel/BodyText"
        })
        {
            Transform target = screen.transform.Find(path);
            if (target == null || !target.TryGetComponent(out TMP_Text text))
                continue;

            text.textWrappingMode = TextWrappingModes.Normal;
            text.overflowMode = TextOverflowModes.Overflow;
        }
    }

    private static void CreateDesignedUnavailableHeader(Transform parent, string generatedRoot, string title)
    {
        GameObject header = CreateFlatPanel("HeaderBar", parent, 28f, 32f, 1614f, 72f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y, FlatTargetPanelFill, FlatTargetCyan, 2f, false);

        Button backButton = CreateFlatButton("BackButton", header.transform, false, 78f, 54f, FlatTargetPanelFill, FlatTargetCyanDim, false);
        ConfigurePixelRect((RectTransform)backButton.transform, 20f, 9f, 78f, 54f, 1614f, 72f);
        TMP_Text backIcon = CreateText("IconText", backButton.transform, "<", 48f, TextAlignmentOptions.Center);
