        CreateDesignedUnavailableResourceCounter("CreditsCounter", header.transform, generatedRoot, "Icons/icon_credits.png", "CREDITS", "24.8K", 884f);
        CreateDesignedUnavailableResourceCounter("MaterialsCounter", header.transform, generatedRoot, "Icons/icon_materials.png", "MATERIALS", "12.6K", 1088f);
        CreateDesignedUnavailableResourceCounter("AuthorityCounter", header.transform, generatedRoot, "Icons/icon_command_authority.png", "AUTHORITY", "1,250", 1292f, 220f);

        Button settingsButton = CreateFlatButton("SettingsButton", header.transform, false, 68f, 54f, FlatTargetPanelFill, FlatTargetCyanDim, false);
        ConfigurePixelRect((RectTransform)settingsButton.transform, 1524f, 9f, 68f, 54f, 1614f, 72f);
        TMP_Text gearIcon = CreateText("GearIcon", settingsButton.transform, "□", 26f, TextAlignmentOptions.Center);
