    private static void CreateDesignedUnavailableCards(Transform parent, string generatedRoot, DesignedUnavailableCard[] cards)
    {
        TMP_Text title = CreateText("StatusPanelsTitleText", parent, "STATUS PANELS", 21f, TextAlignmentOptions.Left);
        title.color = new Color(0.10f, 0.86f, 1f, 1f);
        title.fontStyle = FontStyles.Bold;
        ConfigurePixelRect((RectTransform)title.transform, 278f, 430f, 260f, 32f, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);

        bool compactGrid = cards.Length > 3;
        float cardWidth = 420f;
        float cardHeight = compactGrid ? 96f : 174f;
        float startX = 268f;
        float startY = 462f;
        float gapX = 455f;
        float gapY = 112f;
        int columns = compactGrid ? 3 : Mathf.Max(1, cards.Length);

        for (int i = 0; i < cards.Length; i++)
        {
            DesignedUnavailableCard card = cards[i];
            int column = compactGrid ? i % columns : i;
            int row = compactGrid ? i / columns : 0;
            Button button = CreateFlatButton($"StatusCard_{i + 1}", parent, i == 0, cardWidth, cardHeight, FlatTargetCardFill, FlatTargetOrange, false);
            ConfigurePixelRect((RectTransform)button.transform, startX + column * gapX, startY + row * gapY, cardWidth, cardHeight, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);

            TMP_Text cardTitle = CreateText("TitleText", button.transform, card.Title, compactGrid ? 19f : 24f, TextAlignmentOptions.Left);
