    private static GameObject CreateFlatPanel(
        string name,
        Transform parent,
        float x,
        float yFromTop,
        float width,
        float height,
        float referenceWidth,
        float referenceHeight,
        Color fill,
        Color border,
        float borderThickness,
        bool raycastTarget)
    {
        GameObject panel = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)panel.transform, x, yFromTop, width, height, referenceWidth, referenceHeight);
        Image background = panel.AddComponent<Image>();
        background.color = fill;
        background.raycastTarget = raycastTarget;

        if (borderThickness > 0f && border.a > 0f)
            AddFlatBorder(panel.transform, border, borderThickness);

        return panel;
    }

    private static Button CreateFlatButton(
        string name,
        Transform parent,
        bool selected,
        float width,
        float height,
        Color fill,
        Color border,
        bool animated)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        SetSize(buttonObject, width, height);
        Image background = buttonObject.AddComponent<Image>();
        background.color = fill;

        AddFlatBorder(buttonObject.transform, border, selected ? 2f : 1f);

        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        if (animated)
        {
            ConfigureAnimatedButton(button, selected);
        }
        else
        {
            button.transition = Selectable.Transition.ColorTint;
            ColorBlock colors = button.colors;
            colors.normalColor = fill;
            colors.highlightedColor = Color.Lerp(fill, Color.white, 0.08f);
            colors.pressedColor = Color.Lerp(fill, Color.black, 0.10f);
            colors.selectedColor = Color.Lerp(fill, FlatTargetCyan, 0.15f);
            colors.disabledColor = new Color(fill.r, fill.g, fill.b, 0.65f);
            colors.fadeDuration = 0.08f;
            button.colors = colors;

            UiMotionFeedback feedback = button.GetComponent<UiMotionFeedback>();
            if (feedback == null)
                feedback = button.gameObject.AddComponent<UiMotionFeedback>();

            feedback.ConfigureButtonDefaults(selected);
        }

        return button;
    }

    private static void ForceWhiteButtonTint(Button button)
    {
        ColorBlock colors = button.colors;
        colors.normalColor = Color.white;
        colors.highlightedColor = Color.white;
        colors.pressedColor = Color.white;
        colors.selectedColor = Color.white;
        colors.disabledColor = new Color(1f, 1f, 1f, 0.65f);
        button.colors = colors;
    }

    private static void AddFlatBorder(Transform parent, Color color, float thickness)
    {
        float line = Mathf.Max(1f, thickness);
        Image top = CreateImage("Border_Top", parent, color);
        RectTransform topRect = (RectTransform)top.transform;
        topRect.anchorMin = new Vector2(0f, 1f);
        topRect.anchorMax = new Vector2(1f, 1f);
        topRect.pivot = new Vector2(0.5f, 1f);
        topRect.offsetMin = new Vector2(0f, -line);
        topRect.offsetMax = Vector2.zero;
        top.raycastTarget = false;

        Image bottom = CreateImage("Border_Bottom", parent, color);
        RectTransform bottomRect = (RectTransform)bottom.transform;
        bottomRect.anchorMin = Vector2.zero;
        bottomRect.anchorMax = new Vector2(1f, 0f);
        bottomRect.pivot = new Vector2(0.5f, 0f);
        bottomRect.offsetMin = Vector2.zero;
        bottomRect.offsetMax = new Vector2(0f, line);
        bottom.raycastTarget = false;

        Image left = CreateImage("Border_Left", parent, color);
        RectTransform leftRect = (RectTransform)left.transform;
        leftRect.anchorMin = Vector2.zero;
        leftRect.anchorMax = new Vector2(0f, 1f);
        leftRect.pivot = new Vector2(0f, 0.5f);
        leftRect.offsetMin = Vector2.zero;
        leftRect.offsetMax = new Vector2(line, 0f);
        left.raycastTarget = false;

        Image right = CreateImage("Border_Right", parent, color);
        RectTransform rightRect = (RectTransform)right.transform;
        rightRect.anchorMin = new Vector2(1f, 0f);
        rightRect.anchorMax = Vector2.one;
        rightRect.pivot = new Vector2(1f, 0.5f);
        rightRect.offsetMin = new Vector2(-line, 0f);
        rightRect.offsetMax = Vector2.zero;
        right.raycastTarget = false;
    }

