    private static void AddLayeredFrame(Transform parent, string fillName, string frameName, string fillPath, string framePath)
    {
        Image fill = CreateImage(fillName, parent, Color.white);
        Stretch((RectTransform)fill.transform);
        fill.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(fillPath);
        fill.type = Image.Type.Sliced;
        fill.raycastTarget = false;

        Image frame = CreateImage(frameName, parent, Color.white);
        Stretch((RectTransform)frame.transform);
        frame.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(framePath);
        frame.type = Image.Type.Sliced;
        frame.raycastTarget = false;
    }

