    private static GameObject CreateBuildDrawerPanel(string name, Transform parent, float x, float y, float width, float height, string title)
    {
        GameObject panel = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)panel.transform, x, y, width, height, 1664f, 650f);
        Image fill = CreateImage("FillBackground", panel.transform, Color.white);
        Stretch((RectTransform)fill.transform);
        fill.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(MatchHudOneGoObjectivePanelFillPath);
        fill.type = Image.Type.Sliced;
        fill.raycastTarget = false;

        if (!string.IsNullOrEmpty(title))
        {
            Image accent = CreateImage("AccentBar", panel.transform, new Color(0.03f, 0.78f, 1f, 1f));
            ConfigurePixelRect((RectTransform)accent.transform, 22f, 24f, 5f, 30f, width, height);
            accent.raycastTarget = false;

            TMP_Text titleText = CreateText("SectionTitleText", panel.transform, title, 20f, TextAlignmentOptions.Left);
            titleText.fontStyle = FontStyles.Bold;
            ConfigurePixelRect((RectTransform)titleText.transform, 38f, 18f, width - 70f, 42f, width, height);

            CreateMatchDivider("HeaderDivider", panel.transform, 22f, 62f, width - 44f, 1.5f, width, height);
        }

        Image frame = CreateImage("FrameChrome", panel.transform, Color.white);
        Stretch((RectTransform)frame.transform);
        frame.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(MatchHudOneGoObjectivePanelPath);
        frame.type = Image.Type.Sliced;
        frame.raycastTarget = false;
        frame.transform.SetSiblingIndex(1);
        return panel;
    }

    private static void CreateBuildDrawerTabs(Transform parent)
    {
        string[] labels = { "INFANTRY", "VEHICLES", "AIR", "DEFENSE", "SUPPORT" };
        float[] xPositions = { 32f, 252f, 464f, 676f, 884f };
        for (int i = 0; i < labels.Length; i++)
