            Button tab = CreateMatchChromeButton($"Tab_{labels[i]}", parent, i == 0 ? MatchHudOneGoButtonSelectedPath : MatchHudOneGoButtonNormalPath, 202f, 58f);
            ConfigurePixelRect((RectTransform)tab.transform, xPositions[i], 104f, 202f, 58f, 1664f, 650f);
            TMP_Text label = CreateText("LabelText", tab.transform, labels[i], 20f, TextAlignmentOptions.Center);
            label.fontStyle = FontStyles.Bold;
            ConfigurePixelRect((RectTransform)label.transform, 12f, 11f, 178f, 34f, 202f, 58f);
            ConfigureAnimatedButton(tab, i == 0);
        }
    }

