    private static void CreateBuildDrawerProgressBar(Transform parent, string name, float x, float y, float width, float height, float referenceWidth, float referenceHeight, float fillAmount)
    {
        GameObject track = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)track.transform, x, y, width, height, referenceWidth, referenceHeight);
        Image trackImage = track.AddComponent<Image>();
        trackImage.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsSliderTrackPath);
        trackImage.type = Image.Type.Sliced;
        trackImage.color = Color.white;
        trackImage.raycastTarget = false;

        Image fill = CreateImage("Fill", track.transform, Color.white);
        RectTransform fillRect = (RectTransform)fill.transform;
        fillRect.anchorMin = new Vector2(0f, 0f);
        fillRect.anchorMax = new Vector2(Mathf.Clamp01(fillAmount), 1f);
        fillRect.offsetMin = Vector2.zero;
        fillRect.offsetMax = Vector2.zero;
        fill.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsSliderFillPath);
        fill.type = Image.Type.Sliced;
        fill.raycastTarget = false;
    }

    private static GameObject CreateMatchPanel(string name, Transform parent, string title, float x, float y, float width, float height)
    {
        GameObject panel = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)panel.transform, x, y, width, height, MainMenuReferenceResolution.x, MainMenuReferenceResolution.y);
        Image fill = CreateImage("FillBackground", panel.transform, Color.white);
        Stretch((RectTransform)fill.transform);
        fill.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(GetMatchPanelFillSpritePath(name));
        fill.type = Image.Type.Sliced;
        fill.raycastTarget = false;

        if (!string.IsNullOrEmpty(title))
        {
            float titleX = name == "ThreatFeedPanel" ? 36f : 46f;
            float accentX = name == "ThreatFeedPanel" ? 24f : 28f;
            float dividerX = name == "ThreatFeedPanel" ? 28f : 28f;
            Image accentBar = CreateImage("AccentBar", panel.transform, new Color(0.03f, 0.78f, 1f, 1f));
            ConfigurePixelRect((RectTransform)accentBar.transform, accentX, 22f, 5f, 28f, width, height);
            accentBar.raycastTarget = false;

            TMP_Text titleText = CreateText("SectionTitleText", panel.transform, title, 18f, TextAlignmentOptions.Left);
            titleText.fontStyle = FontStyles.Bold;
            ConfigurePixelRect((RectTransform)titleText.transform, titleX, 17f, width - titleX - 26f, 36f, width, height);

            Image divider = CreateImage("Divider", panel.transform, new Color(0.46f, 0.58f, 0.60f, 0.42f));
            ConfigurePixelRect((RectTransform)divider.transform, dividerX, 58f, width - dividerX - 28f, 2f, width, height);
            divider.raycastTarget = false;
        }

        return panel;
    }

    private static void AddMatchFrameChrome(Transform parent, string panelName)
    {
        Image frame = CreateImage("FrameChrome", parent, Color.white);
        Stretch((RectTransform)frame.transform);
        frame.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(GetMatchPanelSpritePath(panelName));
        frame.type = Image.Type.Sliced;
        frame.raycastTarget = false;

        if (panelName is "ObjectivePanel" or "ThreatFeedPanel" or "MiniMapPanel")
            frame.transform.SetSiblingIndex(1);
    }

    private static string GetMatchPanelSpritePath(string name)
    {
        return name switch
        {
            "ObjectivePanel" => MatchHudOneGoObjectivePanelPath,
            "ThreatFeedPanel" => MatchHudOneGoThreatPanelPath,
            "MiniMapPanel" => MatchHudOneGoMiniMapPanelPath,
            _ => MatchHudPanelPath
        };
    }

    private static string GetMatchPanelFillSpritePath(string name)
    {
        return name switch
        {
            "ObjectivePanel" => MatchHudOneGoObjectivePanelFillPath,
            "ThreatFeedPanel" => MatchHudOneGoThreatPanelFillPath,
            "MiniMapPanel" => MatchHudOneGoMiniMapPanelFillPath,
            _ => MatchHudPanelPath
        };
    }

    private static Button CreateMatchChromeButton(string name, Transform parent, string spritePath, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        SetSize(buttonObject, width, height);
        Image background = buttonObject.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(spritePath);
        background.type = Image.Type.Sliced;
        background.color = Color.white;
        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(button, Color.white, new Color(0.90f, 0.97f, 1f, 1f), new Color(0.66f, 0.84f, 0.92f, 1f));
        return button;
    }

    private static void HideGraphic(Graphic graphic)
    {
        if (graphic == null)
            return;

        Color color = graphic.color;
        color.a = 0f;
        graphic.color = color;
        graphic.raycastTarget = false;
    }

    private static void HideDescendantGraphics(Transform root, bool includeSelf)
    {
        foreach (Graphic graphic in root.GetComponentsInChildren<Graphic>(true))
        {
            if (!includeSelf && graphic.transform == root)
                continue;

            HideGraphic(graphic);
        }
    }

    private static GameObject CreateMatchObjectiveRow(string name, Transform parent, string label, float x, float y, float width, float height, bool star)
    {
        GameObject row = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)row.transform, x, y, width, height, 358f, 282f);
        if (star)
        {
            Image marker = CreateImage("MarkerImage", row.transform, Color.white);
            marker.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(MatchHudOneGoObjectiveStarPath);
            marker.preserveAspect = true;
            marker.raycastTarget = false;
            ConfigurePixelRect((RectTransform)marker.transform, 8f, 1f, 28f, 28f, width, height);

            TMP_Text bonusText = CreateText("BonusText", row.transform, "+1", 16f, TextAlignmentOptions.Right);
            bonusText.color = new Color(1f, 0.74f, 0.06f, 1f);
            bonusText.fontStyle = FontStyles.Bold;
            ConfigurePixelRect((RectTransform)bonusText.transform, width - 52f, 0f, 28f, height, width, height);

            Image bonusIcon = CreateImage("BonusIcon", row.transform, Color.white);
            bonusIcon.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(MatchHudObjectiveBonusPath);
            bonusIcon.preserveAspect = true;
            bonusIcon.raycastTarget = false;
            ConfigurePixelRect((RectTransform)bonusIcon.transform, width - 24f, 3f, 22f, 22f, width, height);
        }
        else
        {
            Image box = CreateImage("Checkbox", row.transform, Color.white);
            ConfigurePixelRect((RectTransform)box.transform, 8f, 2f, 26f, 26f, width, height);
            box.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(MatchHudOneGoObjectiveCheckboxPath);
            box.preserveAspect = true;
            box.raycastTarget = false;
        }

        TMP_Text text = CreateText("LabelText", row.transform, label, star ? 16f : 15f, TextAlignmentOptions.Left);
        text.color = new Color(0.91f, 0.95f, 0.96f, 1f);
        ConfigurePixelRect((RectTransform)text.transform, 48f, 0f, star ? width - 104f : width - 54f, height, width, height);
        return row;
    }

