    private static WarlineCaptureSegmentedControlView CreateSettingsLabeledSegmentedControl(string name, Transform parent, string label, string[] labels, int selectedIndex)
    {
        GameObject root = CreateRectObject(name, parent);
        LayoutElement layout = root.AddComponent<LayoutElement>();
        layout.preferredHeight = 72f;

        WarlineCaptureSegmentedControlView view = root.AddComponent<WarlineCaptureSegmentedControlView>();

        TMP_Text labelText = CreateText("LabelText", root.transform, label, 24f, TextAlignmentOptions.Left);
        RectTransform labelRect = (RectTransform)labelText.transform;
        labelRect.anchorMin = new Vector2(0f, 0.12f);
        labelRect.anchorMax = new Vector2(0.28f, 0.88f);
        labelText.color = new Color(0.92f, 0.96f, 0.98f, 1f);

        GameObject segmentRoot = CreateRectObject("SegmentRoot", root.transform);
        RectTransform segmentRect = (RectTransform)segmentRoot.transform;
        segmentRect.anchorMin = new Vector2(0.32f, 0.12f);
        segmentRect.anchorMax = new Vector2(0.96f, 0.88f);
        HorizontalLayoutGroup segmentLayout = segmentRoot.AddComponent<HorizontalLayoutGroup>();
        segmentLayout.spacing = 22f;
        segmentLayout.childControlWidth = true;
        segmentLayout.childControlHeight = true;
        segmentLayout.childForceExpandWidth = true;
        segmentLayout.childForceExpandHeight = true;

        Button[] buttons = new Button[labels.Length];
        TMP_Text[] labelTexts = new TMP_Text[labels.Length];
        for (int i = 0; i < labels.Length; i++)
        {
            buttons[i] = CreateSettingsChromeButton($"Segment_{i + 1}", segmentRoot.transform, labels[i], false, 160f, 54f);
            labelTexts[i] = buttons[i].GetComponentInChildren<TMP_Text>();
            if (labelTexts[i] != null)
            {
                labelTexts[i].fontSize = 22f;
                labelTexts[i].fontStyle = FontStyles.Bold;
            }
        }

        SetSerializedObject(view, "segmentRoot", segmentRoot.transform);
        SetSerializedArray(view, "segmentButtons", buttons);
        SetSerializedArray(view, "segmentLabels", labelTexts);
        view.Bind(labels, selectedIndex);
        ApplySegmentedControlVisualSelection(view, selectedIndex);
        return view;
    }

    private static GameObject CreateSettingsSegmentedControlRow(string[] labels)
    {
        GameObject root = CreateRectObject("SettingsSegmentedControlRow", null);
        SetSize(root, 620f, 72f);
        WarlineCaptureSegmentedControlView view = root.AddComponent<WarlineCaptureSegmentedControlView>();

        GameObject segmentRoot = CreateRectObject("SegmentRoot", root.transform);
        HorizontalLayoutGroup layout = segmentRoot.AddComponent<HorizontalLayoutGroup>();
        layout.spacing = labels.Length > 3 ? 16f : 22f;
        layout.childControlWidth = true;
        layout.childControlHeight = true;
        layout.childForceExpandWidth = true;
        layout.childForceExpandHeight = true;

        Button[] buttons = new Button[labels.Length];
        TMP_Text[] labelTexts = new TMP_Text[labels.Length];
        for (int i = 0; i < labels.Length; i++)
        {
            buttons[i] = CreateSettingsChromeButton($"Segment_{i + 1}", segmentRoot.transform, labels[i], false, 180f, 58f);
            labelTexts[i] = buttons[i].GetComponentInChildren<TMP_Text>();
            if (labelTexts[i] != null)
            {
                labelTexts[i].fontSize = 24f;
                labelTexts[i].fontStyle = FontStyles.Bold;
            }
        }

        SetSerializedObject(view, "segmentRoot", segmentRoot.transform);
        SetSerializedArray(view, "segmentButtons", buttons);
        SetSerializedArray(view, "segmentLabels", labelTexts);
        return root;
    }

    private static void ApplySegmentedControlVisualSelection(WarlineCaptureSegmentedControlView view, int selectedIndex)
    {
        if (view?.SegmentButtons == null)
            return;

        for (int i = 0; i < view.SegmentButtons.Length; i++)
        {
            Button button = view.SegmentButtons[i];
            if (button == null)
                continue;

            bool selected = i == selectedIndex;
            Image background = button.targetGraphic as Image;
            if (background != null)
            {
                background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(selected ? SettingsButtonSelectedPath : SettingsButtonNormalPath);
                background.type = Image.Type.Sliced;
                background.color = Color.white;
            }

            TMP_Text label = button.GetComponentInChildren<TMP_Text>();
            if (label != null)
                label.color = selected ? new Color(0.98f, 1f, 1f, 1f) : new Color(0.88f, 0.94f, 0.95f, 1f);

            ConfigureAnimatedButton(button, selected);
        }
    }

    private static void ApplyQuickCustomSegmentedControlVisualSelection(WarlineCaptureSegmentedControlView view, int selectedIndex)
    {
        if (view?.SegmentButtons == null)
            return;

        for (int i = 0; i < view.SegmentButtons.Length; i++)
        {
            Button button = view.SegmentButtons[i];
            if (button == null)
                continue;

            bool selected = i == selectedIndex;
            Image background = button.targetGraphic as Image;
            if (background != null)
            {
                background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(selected ? QuickCustomButtonSelectedPath : QuickCustomButtonNormalPath);
                background.type = Image.Type.Sliced;
                background.color = Color.white;
            }

            TMP_Text label = button.GetComponentInChildren<TMP_Text>();
            if (label != null)
                label.color = selected ? new Color(0.98f, 1f, 1f, 1f) : new Color(0.88f, 0.94f, 0.95f, 1f);
        }
    }

    private static void ConfigureQuickCustomSegmentVisuals(WarlineCaptureSegmentedControlView view)
    {
        SetSerializedBool(view, "applyVisualSelection", true);
        SetSerializedObject(view, "normalSprite", AssetDatabase.LoadAssetAtPath<Sprite>(QuickCustomButtonNormalPath));
        SetSerializedObject(view, "selectedSprite", AssetDatabase.LoadAssetAtPath<Sprite>(QuickCustomButtonSelectedPath));
        SetSerializedColor(view, "normalLabelColor", new Color(0.88f, 0.94f, 0.95f, 1f));
        SetSerializedColor(view, "selectedLabelColor", new Color(0.98f, 1f, 1f, 1f));
    }

    private static TMP_Dropdown CreateDropdownRow(string name, Transform parent, string label, string[] options)
    {
        GameObject row = CreateRectObject(name, parent);
        LayoutElement layout = row.AddComponent<LayoutElement>();
        layout.preferredHeight = 66f;

        TMP_Text labelText = CreateText("LabelText", row.transform, label, 24f, TextAlignmentOptions.Left);
        RectTransform labelRect = (RectTransform)labelText.transform;
        labelRect.anchorMin = new Vector2(0.0f, 0.16f);
        labelRect.anchorMax = new Vector2(0.42f, 0.88f);
        labelText.color = new Color(0.92f, 0.96f, 0.98f, 1f);

        GameObject dropdownObject = CreateRectObject("Dropdown", row.transform);
        RectTransform dropdownRect = (RectTransform)dropdownObject.transform;
        dropdownRect.anchorMin = new Vector2(1f, 0.5f);
        dropdownRect.anchorMax = new Vector2(1f, 0.5f);
        dropdownRect.pivot = new Vector2(1f, 0.5f);
        dropdownRect.sizeDelta = new Vector2(SettingsDropdownWidth, SettingsDropdownHeight);
        dropdownRect.anchoredPosition = new Vector2(-28f, 0f);
        Image dropdownBackground = dropdownObject.AddComponent<Image>();
        dropdownBackground.color = Color.white;
        dropdownBackground.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsDropdownPath);
        dropdownBackground.type = Image.Type.Sliced;
        TMP_Dropdown dropdown = dropdownObject.AddComponent<TMP_Dropdown>();

        TMP_Text captionText = CreateText("Label", dropdownObject.transform, options.Length > 0 ? options[0] : string.Empty, 22f, TextAlignmentOptions.Left);
        RectTransform captionRect = (RectTransform)captionText.transform;
        captionRect.anchorMin = new Vector2(0.06f, 0.12f);
        captionRect.anchorMax = new Vector2(0.84f, 0.88f);
        captionText.color = new Color(0.90f, 0.95f, 0.96f, 1f);

        Image arrowImage = CreateImage("Arrow", dropdownObject.transform, Color.white);
        RectTransform arrowRect = (RectTransform)arrowImage.transform;
        arrowRect.anchorMin = new Vector2(0.875f, 0.29f);
        arrowRect.anchorMax = new Vector2(0.965f, 0.71f);
        arrowImage.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsDropdownChevronPath);
        arrowImage.preserveAspect = true;
        arrowImage.raycastTarget = false;

        GameObject template = CreateDropdownTemplate(dropdownObject.transform, out TMP_Text itemText);
        dropdown.template = (RectTransform)template.transform;
        dropdown.captionText = captionText;
        dropdown.itemText = itemText;
        dropdown.options.Clear();
        foreach (string option in options)
            dropdown.options.Add(new TMP_Dropdown.OptionData(option));
        dropdown.SetValueWithoutNotify(0);
        template.SetActive(false);
        return dropdown;
    }

    private static GameObject CreateDropdownTemplate(Transform parent, out TMP_Text itemText)
    {
        GameObject template = CreateRectObject("Template", parent);
        RectTransform templateRect = (RectTransform)template.transform;
        templateRect.anchorMin = new Vector2(0f, 0f);
        templateRect.anchorMax = new Vector2(1f, 0f);
        templateRect.pivot = new Vector2(0.5f, 1f);
        templateRect.anchoredPosition = new Vector2(0f, -4f);
        templateRect.sizeDelta = new Vector2(0f, 220f);
        Image templateBackground = template.AddComponent<Image>();
        templateBackground.color = new Color(0.025f, 0.035f, 0.045f, 0.98f);
        ScrollRect scrollRect = template.AddComponent<ScrollRect>();
        scrollRect.horizontal = false;

        GameObject viewport = CreateRectObject("Viewport", template.transform);
        Image viewportImage = viewport.AddComponent<Image>();
        viewportImage.color = new Color(1f, 1f, 1f, 0.02f);
        Mask viewportMask = viewport.AddComponent<Mask>();
        viewportMask.showMaskGraphic = false;

        GameObject content = CreateRectObject("Content", viewport.transform);
        RectTransform contentRect = (RectTransform)content.transform;
        contentRect.anchorMin = new Vector2(0f, 1f);
        contentRect.anchorMax = new Vector2(1f, 1f);
        contentRect.pivot = new Vector2(0.5f, 1f);
        contentRect.sizeDelta = new Vector2(0f, 56f);

        GameObject item = CreateRectObject("Item", content.transform);
        RectTransform itemRect = (RectTransform)item.transform;
        itemRect.anchorMin = new Vector2(0f, 1f);
        itemRect.anchorMax = new Vector2(1f, 1f);
        itemRect.pivot = new Vector2(0.5f, 1f);
        itemRect.sizeDelta = new Vector2(0f, 56f);
        Toggle itemToggle = item.AddComponent<Toggle>();

        GameObject itemBackground = CreateRectObject("Item Background", item.transform);
        Image itemBackgroundImage = itemBackground.AddComponent<Image>();
        itemBackgroundImage.color = new Color(0.07f, 0.1f, 0.12f, 0.96f);

        GameObject itemCheckmark = CreateRectObject("Item Checkmark", item.transform);
        RectTransform checkRect = (RectTransform)itemCheckmark.transform;
        checkRect.anchorMin = new Vector2(0.02f, 0.2f);
        checkRect.anchorMax = new Vector2(0.12f, 0.8f);
        Image checkmarkImage = itemCheckmark.AddComponent<Image>();
        checkmarkImage.color = new Color(0.16f, 0.78f, 0.95f, 1f);

        itemText = CreateText("Item Label", item.transform, "OPTION", 20f, TextAlignmentOptions.Left);
        RectTransform itemLabelRect = (RectTransform)itemText.transform;
        itemLabelRect.anchorMin = new Vector2(0.16f, 0.1f);
        itemLabelRect.anchorMax = new Vector2(0.96f, 0.9f);

        itemToggle.targetGraphic = itemBackgroundImage;
        itemToggle.graphic = checkmarkImage;
        scrollRect.viewport = (RectTransform)viewport.transform;
        scrollRect.content = contentRect;
        return template;
    }

    private static GameObject CreateEmptyScreen(string name, WarlineCaptureRoute route, string title)
