    private static void SaveScreenPrefab(GameObject screen, string path)
    {
        try
        {
            OptimizeGeneratedUiRaycastTargets(screen);
            PrefabUtility.SaveAsPrefabAsset(screen, path);
            NormalizeFontsInPrefab(path);
        }
        finally
        {
            Object.DestroyImmediate(screen);
        }
    }

