    private static Button CreateAssistantEntryButton(Transform parent)
    {
        AssistantButtonView assistantButtonPrefab = AssetDatabase.LoadAssetAtPath<AssistantButtonView>(AssistantButtonPrefabPath);
        if (assistantButtonPrefab != null)
        {
            GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(assistantButtonPrefab.gameObject, parent);
            instance.name = "AssistantEntryButton";
            return instance.GetComponent<Button>();
        }

        Button fallbackButton = CreateMatchChromeButton("AssistantEntryButton", parent, MatchHudOneGoTopButtonPath, 190f, 96f);
        ConfigureAnimatedButton(fallbackButton, false);
        TMP_Text fallbackLabel = CreateText("LabelText", fallbackButton.transform, "ARIA", 20f, TextAlignmentOptions.Center);
        fallbackLabel.fontStyle = FontStyles.Bold;
        fallbackLabel.color = new Color(0.95f, 0.99f, 1f, 1f);
        ConfigureSingleLineText(fallbackLabel);
        Stretch((RectTransform)fallbackLabel.transform);
        return fallbackButton;
    }

