        SetSerializedObject(view, "bodyRoot", bodyRoot.transform);
        SetSerializedObject(view, "buttonRow", buttonRow.transform);
        ApplyScreenTypography(
            root,
            "Frame/Header/TitleText",
            "Frame/BodyRoot/TargetPanel/TargetNameText",
            "Frame/BodyRoot/RiskPanel/IntelConfidenceRow/ValueText",
            "Frame/BodyRoot/RiskPanel/CollateralRiskRow/ValueText",
            "Frame/BodyRoot/RiskPanel/CivilianDensityRow/ValueText",
            "Frame/ButtonRow/CancelButton/LabelText",
            "Frame/ButtonRow/ConfirmButton/LabelText");
        warningText.textWrappingMode = TextWrappingModes.Normal;
        warningText.overflowMode = TextOverflowModes.Overflow;
        return root;
    }

    private static void CreateConfirmRaidMetricRow(string name, Transform parent, string framePath, string iconPath, string label, string value, Color accentColor, float y, int filledSegments, int totalSegments)
    {
        GameObject row = CreateRectObject(name, parent);
        float rowHeight = totalSegments > 0 ? 92f : 74f;
        ConfigurePixelRect((RectTransform)row.transform, 0f, y, 500f, rowHeight, 500f, 420f);
        Image frame = row.AddComponent<Image>();
        frame.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(framePath);
        frame.type = Image.Type.Sliced;
        frame.raycastTarget = false;

        Image icon = CreateImage("IconImage", row.transform, Color.white);
        icon.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(iconPath);
        icon.preserveAspect = true;
        icon.raycastTarget = false;
        ConfigurePixelRect((RectTransform)icon.transform, 18f, 11f, 70f, 70f, 500f, rowHeight);

        TMP_Text labelText = CreateText("LabelText", row.transform, label, 23f, TextAlignmentOptions.Left);
        labelText.color = new Color(0.86f, 0.92f, 0.94f, 1f);
        ConfigurePixelRect((RectTransform)labelText.transform, 108f, 18f, 250f, 36f, 500f, rowHeight);
        ConfigureSingleLineText(labelText);

        TMP_Text valueText = CreateText("ValueText", row.transform, value, 30f, TextAlignmentOptions.Right);
        valueText.fontStyle = FontStyles.Bold;
        valueText.color = accentColor;
        ConfigurePixelRect((RectTransform)valueText.transform, 352f, 13f, 126f, 44f, 500f, rowHeight);
        ConfigureSingleLineText(valueText);

        if (totalSegments <= 0)
            return;

        GameObject meter = CreateRectObject("MeterSegments", row.transform);
        ConfigurePixelRect((RectTransform)meter.transform, 108f, 58f, 370f, 20f, 500f, rowHeight);
        for (int i = 0; i < totalSegments; i++)
        {
            Image segment = CreateImage($"Segment_{i + 1:00}", meter.transform, i < filledSegments ? accentColor : new Color(0.04f, 0.06f, 0.065f, 0.88f));
            segment.raycastTarget = false;
            ConfigurePixelRect((RectTransform)segment.transform, i * 36f, 0f, 32f, 20f, 370f, 20f);
        }
    }

    private static Button CreateConfirmRaidIconButton(string name, Transform parent, string backgroundPath, string iconPath, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        SetSize(buttonObject, width, height);
        Image background = buttonObject.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(backgroundPath);
        background.type = Image.Type.Sliced;
        background.color = Color.white;

        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(button, Color.white, new Color(1f, 0.94f, 0.94f, 1f), new Color(0.92f, 0.42f, 0.38f, 1f));
        ConfigureAnimatedButton(button, false);

        Image icon = CreateImage("IconImage", buttonObject.transform, Color.white);
        icon.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(iconPath);
        icon.preserveAspect = true;
        icon.raycastTarget = false;
        ConfigurePixelRect((RectTransform)icon.transform, 12f, 12f, width - 24f, height - 24f, width, height);
        return button;
    }

    private static Button CreateConfirmRaidButton(string name, Transform parent, string label, string backgroundPath, bool primary, float x, float y, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)buttonObject.transform, x, y, width, height, 856f, 84f);
        Image background = buttonObject.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(backgroundPath);
        background.type = Image.Type.Sliced;
        background.color = Color.white;

        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(button, Color.white, primary ? new Color(1f, 0.84f, 0.74f, 1f) : new Color(0.88f, 0.97f, 1f, 1f), primary ? new Color(0.95f, 0.44f, 0.30f, 1f) : new Color(0.58f, 0.78f, 0.88f, 1f));
        ConfigureAnimatedButton(button, primary);

        TMP_Text labelText = CreateText("LabelText", buttonObject.transform, label, primary ? 34f : 28f, TextAlignmentOptions.Center);
        labelText.fontStyle = FontStyles.Bold;
        labelText.color = primary ? new Color(1f, 0.42f, 0.26f, 1f) : new Color(0.84f, 0.88f, 0.90f, 1f);
        Stretch((RectTransform)labelText.transform);
        ConfigureSingleLineText(labelText);
        return button;
    }

