    private static Button CreateMissionResultButton(string name, Transform parent, string label, string backgroundPath, bool primary, float x, float y, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)buttonObject.transform, x, y, width, height, 906f, 92f);
        Image background = buttonObject.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(backgroundPath);
        background.type = Image.Type.Sliced;
        background.color = Color.white;

        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(button, Color.white, primary ? new Color(1f, 0.94f, 0.72f, 1f) : new Color(0.88f, 0.97f, 1f, 1f), primary ? new Color(0.86f, 0.64f, 0.30f, 1f) : new Color(0.58f, 0.78f, 0.88f, 1f));
        ConfigureAnimatedButton(button, primary);

        TMP_Text labelText = CreateText("LabelText", buttonObject.transform, label, 34f, TextAlignmentOptions.Center);
        labelText.fontStyle = FontStyles.Bold;
        labelText.color = primary ? new Color(1f, 0.86f, 0.36f, 1f) : new Color(0.90f, 0.96f, 1f, 1f);
        ConfigureSingleLineText(labelText);
        return button;
    }

