        CreateEndOfDayEnemyActivityPanel(bodyRoot.transform);
        CreateEndOfDayResourceRow(bodyRoot.transform);
        CreateEndOfDaySaveStatus(bodyRoot.transform);

        GameObject buttonRow = CreateRectObject("ButtonRow", frame.transform);
        ConfigurePixelRect((RectTransform)buttonRow.transform, 150f, 678f, 548f, 88f, 848f, 760f);
        Button saveButton = CreateEndOfDaySaveButton(buttonRow.transform);
        _ = saveButton;

        SetSerializedObject(view, "scrim", scrim);
        SetSerializedObject(view, "frame", frame);
        SetSerializedObject(view, "header", header);
        SetSerializedObject(view, "titleText", titleText);
        SetSerializedObject(view, "bodyRoot", bodyRoot.transform);
        SetSerializedObject(view, "buttonRow", buttonRow.transform);
        ApplyScreenTypography(
            root,
            "Frame/Header/TitleText",
            "Frame/Header/DayTag/DayText",
            "Frame/BodyRoot/DeltaSummary/ValueText",
            "Frame/BodyRoot/EnemyActivityPanel/ThreatValueText",
            "Frame/ButtonRow/SaveContinueButton/LabelText");
        return root;
    }

