    private static void CreateIntelRevealEvidenceCard(string name, Transform parent, string title, string thumbnailPath, string confidence, string overlayIconPath, float x)
    {
        GameObject card = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)card.transform, x, 64f, 270f, 300f, 786f, 448f);
        Image cardFrame = card.AddComponent<Image>();
        cardFrame.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(IntelRevealEvidenceCardFramePath);
