        TMP_Text titleText = CreateText("TitleText", card.transform, title, 25f, TextAlignmentOptions.Center);
        titleText.color = new Color(0.90f, 0.93f, 0.94f, 1f);
        ConfigurePixelRect((RectTransform)titleText.transform, 20f, 14f, 230f, 42f, 270f, 300f);
        ConfigureSingleLineText(titleText);

        GameObject thumbnailFrame = CreateRectObject("ThumbnailFrame", card.transform);
