        thumbnailFrameImage.raycastTarget = false;

        Image thumbnail = CreateImage("ThumbnailImage", thumbnailFrame.transform, Color.white);
        thumbnail.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(thumbnailPath);
        thumbnail.preserveAspect = false;
        thumbnail.raycastTarget = false;
        ConfigurePixelRect((RectTransform)thumbnail.transform, 8f, 8f, 214f, 162f, 230f, 178f);

        if (!string.IsNullOrEmpty(overlayIconPath))
        {
            Image overlayIcon = CreateImage("OverlayIcon", thumbnailFrame.transform, Color.white);
