        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(button, Color.white, primary ? new Color(0.82f, 0.98f, 1f, 1f) : new Color(0.90f, 0.94f, 0.96f, 1f), primary ? new Color(0.45f, 0.82f, 0.96f, 1f) : new Color(0.62f, 0.68f, 0.72f, 1f));
        ConfigureAnimatedButton(button, primary);

        TMP_Text labelText = CreateText("LabelText", buttonObject.transform, label, primary ? 34f : 30f, TextAlignmentOptions.Center);
        labelText.color = primary ? new Color(0.86f, 0.97f, 1f, 1f) : new Color(0.90f, 0.94f, 0.96f, 1f);
        ConfigureSingleLineText(labelText);
        return button;
    }

