        Button lockedButton = CreateAbilityUpgradeButton("LockedButton", buttonRow.transform, "NOT UNLOCKED", AbilityUpgradeDisabledButtonPath, AbilityUpgradeLockIconPath, true, false, 0f, 0f, 430f, 72f);
        lockedButton.interactable = false;
        Button sourceButton = CreateAbilityUpgradeButton("ViewSourceButton", buttonRow.transform, "VIEW SOURCE", AbilityUpgradeSecondaryButtonPath, AbilityUpgradeIntelIconPath, false, true, 456f, 0f, 246f, 72f);
        _ = sourceButton;
        CreateAbilityUpgradeTooltip(buttonRow.transform);

        SetSerializedObject(view, "scrim", scrim.gameObject);
        SetSerializedObject(view, "frame", frame);
        SetSerializedObject(view, "header", header);
        SetSerializedObject(view, "titleText", titleText);
        SetSerializedObject(view, "closeButton", closeButton);
        SetSerializedObject(view, "bodyRoot", bodyRoot.transform);
        SetSerializedObject(view, "buttonRow", buttonRow.transform);
        ApplyScreenTypography(
            root,
            "Frame/Header/TitleText",
            "Frame/BodyRoot/DetailPanel/AbilityTitleText",
            "Frame/BodyRoot/UpgradeTargetRow/UpgradeTitleText",
            "Frame/ButtonRow/LockedButton/LabelText",
            "Frame/ButtonRow/ViewSourceButton/LabelText");
        RestoreAbilityUpgradeMultilineText(root);
        return root;
    }

    private static void RestoreAbilityUpgradeMultilineText(GameObject root)
    {
        ConfigureMultilineText(root.transform.Find("Frame/BodyRoot/ContentPanel/DescriptionText"), TextOverflowModes.Ellipsis);
        ConfigureMultilineText(root.transform.Find("Frame/BodyRoot/DetailPanel/AvailabilityRow/ValueText"), TextOverflowModes.Ellipsis);
        ConfigureMultilineText(root.transform.Find("Frame/BodyRoot/DetailPanel/PrerequisiteRow/ValueText"), TextOverflowModes.Ellipsis);
        ConfigureMultilineText(root.transform.Find("Frame/BodyRoot/EffectsPanel/EffectMarkHostile/DescriptionText"), TextOverflowModes.Ellipsis);
        ConfigureMultilineText(root.transform.Find("Frame/BodyRoot/UpgradeTargetRow/GearModuleText"), TextOverflowModes.Ellipsis);
        ConfigureMultilineText(root.transform.Find("Frame/ButtonRow/ConfigNotice/NoticeText"), TextOverflowModes.Ellipsis);
    }

    private static void ConfigureMultilineText(Transform textTransform, TextOverflowModes overflowMode)
    {
        if (textTransform == null || !textTransform.TryGetComponent(out TMP_Text text))
            return;

        text.textWrappingMode = TextWrappingModes.Normal;
        text.overflowMode = overflowMode;
    }

