    private static Button CreateAbilityUpgradeButton(string name, Transform parent, string label, string backgroundPath, string iconPath, bool locked, bool enabled, float x, float y, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)buttonObject.transform, x, y, width, height, 1112f, 82f);
        Image background = buttonObject.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(backgroundPath);
        background.type = Image.Type.Sliced;
        background.color = Color.white;

        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(button, Color.white, locked ? new Color(1f, 0.86f, 0.42f, 1f) : new Color(0.88f, 0.96f, 1f, 1f), locked ? new Color(0.62f, 0.48f, 0.25f, 1f) : new Color(0.48f, 0.72f, 0.82f, 1f));
        ConfigureAnimatedButton(button, !locked);

        Image icon = CreateImage("IconImage", buttonObject.transform, Color.white);
        icon.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(iconPath);
        icon.preserveAspect = true;
        icon.raycastTarget = false;
        ConfigurePixelRect((RectTransform)icon.transform, locked ? 52f : 26f, 18f, 36f, 36f, width, height);

        TMP_Text labelText = CreateText("LabelText", buttonObject.transform, label, locked ? 29f : 22f, TextAlignmentOptions.Center);
        labelText.color = locked ? new Color(1f, 0.86f, 0.36f, 1f) : new Color(0.76f, 0.92f, 1f, 1f);
        ConfigurePixelRect((RectTransform)labelText.transform, locked ? 100f : 72f, 12f, width - (locked ? 126f : 88f), 48f, width, height);
        ConfigureSingleLineText(labelText);
        button.interactable = enabled;
        return button;
    }

