        ConfigureButtonTint(button, Color.white, primary ? new Color(1f, 0.92f, 0.48f, 1f) : new Color(0.90f, 0.98f, 1f, 1f), primary ? new Color(0.90f, 0.55f, 0.08f, 1f) : new Color(0.66f, 0.84f, 0.92f, 1f));
