    private static Button CreatePauseStackButton(string name, Transform parent, string label, string iconPath, bool selected, bool destructive, float y)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        ConfigurePixelRect((RectTransform)buttonObject.transform, 0f, y, 506f, destructive ? 82f : selected ? 84f : 82f, 510f, 482f);

        Image background = buttonObject.AddComponent<Image>();
        string backgroundPath = destructive
            ? PopupPauseButtonDestructivePath
            : selected
                ? PopupPauseButtonSelectedPath
                : PopupPauseButtonNormalPath;
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(backgroundPath);
        background.type = Image.Type.Sliced;
        background.color = Color.white;

        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(
            button,
            Color.white,
            destructive ? new Color(1f, 0.52f, 0.40f, 1f) : new Color(0.88f, 0.97f, 1f, 1f),
            destructive ? new Color(0.86f, 0.22f, 0.16f, 1f) : new Color(0.58f, 0.78f, 0.88f, 1f));
        ConfigureAnimatedButton(button, selected);
        background.color = Color.white;

        if (!string.IsNullOrEmpty(iconPath))
        {
            Image icon = CreateImage("IconImage", buttonObject.transform, Color.white);
            icon.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(iconPath);
            icon.preserveAspect = true;
            icon.raycastTarget = false;
            icon.color = Color.white;
            ConfigurePixelRect((RectTransform)icon.transform, 54f, 12f, 70f, 58f, 506f, 84f);
        }
        else
        {
            string iconLabel = selected || destructive ? ">" : "?";
            TMP_Text iconText = CreateText("IconText", buttonObject.transform, iconLabel, destructive ? 38f : 42f, TextAlignmentOptions.Center);
            iconText.color = destructive ? new Color(1f, 0.40f, 0.32f, 1f) : selected ? new Color(0.76f, 0.96f, 1f, 1f) : new Color(0.78f, 0.84f, 0.86f, 1f);
            ConfigurePixelRect((RectTransform)iconText.transform, 58f, 12f, 42f, 52f, 506f, 84f);
        }

        TMP_Text labelText = CreateText("LabelText", buttonObject.transform, label, label.Length > 12 ? 28f : 34f, TextAlignmentOptions.Center);
        labelText.fontStyle = FontStyles.Bold;
        labelText.color = destructive ? new Color(1f, 0.46f, 0.36f, 1f) : selected ? new Color(0.78f, 0.96f, 1f, 1f) : new Color(0.86f, 0.90f, 0.91f, 1f);
        labelText.enableAutoSizing = true;
        labelText.fontSizeMin = 23f;
        labelText.fontSizeMax = label.Length > 12 ? 30f : 36f;
        ConfigureSingleLineText(labelText);
        ConfigurePixelRect((RectTransform)labelText.transform, 128f, 8f, 326f, 66f, 506f, 84f);
        return button;
    }

    private static Button CreatePopupIconButton(string name, Transform parent, string label, float width, float height, bool alert)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        SetSize(buttonObject, width, height);
