        visualRect.anchorMin = new Vector2(0.5f, 0.5f);
        visualRect.anchorMax = new Vector2(0.5f, 0.5f);
        visualRect.pivot = new Vector2(0.5f, 0.5f);
        visualRect.anchoredPosition = Vector2.zero;
        visualRect.sizeDelta = new Vector2(Mathf.Min(width, 48f), Mathf.Min(height, 48f));

        Image background = visual.AddComponent<Image>();
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(SettingsButtonNormalPath);
        background.type = Image.Type.Sliced;
        background.color = alert ? new Color(0.68f, 0.25f, 0.20f, 0.92f) : Color.white;
        background.raycastTarget = false;

        TMP_Text labelText = CreateText("LabelText", visual.transform, label, Mathf.Min(32f, Mathf.Min(width, height) * 0.50f), TextAlignmentOptions.Center);
