    private static GameObject CreateSegmentedControlPrefab()
    {
        GameObject root = CreateRectObject("SegmentedControlView", null);
        SetSize(root, 620f, 92f);
        WarlineCaptureSegmentedControlView view = root.AddComponent<WarlineCaptureSegmentedControlView>();
        Image background = root.AddComponent<Image>();
        background.color = new Color(1f, 1f, 1f, 0f);
        background.raycastTarget = false;

        GameObject segmentRoot = CreateRectObject("SegmentRoot", root.transform);
        HorizontalLayoutGroup layout = segmentRoot.AddComponent<HorizontalLayoutGroup>();
        layout.spacing = 16f;
        layout.childControlWidth = true;
        layout.childControlHeight = true;
        layout.childForceExpandWidth = true;
        layout.childForceExpandHeight = true;

        Button[] buttons = new Button[3];
        TMP_Text[] labels = new TMP_Text[3];
        for (int i = 0; i < buttons.Length; i++)
        {
            buttons[i] = CreateSettingsChromeButton($"Segment_{i + 1}", segmentRoot.transform, i == 0 ? "LOW" : i == 1 ? "MEDIUM" : "HIGH", i == 1, 180f, 64f);
            labels[i] = buttons[i].GetComponentInChildren<TMP_Text>();
            if (labels[i] != null)
                labels[i].fontStyle = FontStyles.Bold;
        }

        SetSerializedObject(view, "segmentRoot", segmentRoot.transform);
        SetSerializedArray(view, "segmentButtons", buttons);
        SetSerializedArray(view, "segmentLabels", labels);
        return root;
    }

