    private static Button CreateSettingsChromeButton(string name, Transform parent, string label, bool selected, float width, float height)
    {
        GameObject buttonObject = CreateRectObject(name, parent);
        SetSize(buttonObject, width, height);
        Image background = buttonObject.AddComponent<Image>();
        background.color = Color.white;
        background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(selected ? SettingsButtonSelectedPath : SettingsButtonNormalPath);
        background.type = Image.Type.Sliced;
        Button button = buttonObject.AddComponent<Button>();
        button.targetGraphic = background;
        ConfigureButtonTint(button, Color.white, new Color(0.9f, 0.98f, 1f, 1f), new Color(0.72f, 0.84f, 0.9f, 1f));

        if (name.StartsWith("Tab_", System.StringComparison.Ordinal))
            background.sprite = AssetDatabase.LoadAssetAtPath<Sprite>(selected ? SettingsTabSelectedPath : SettingsTabNormalPath);

        TMP_Text labelText = CreateText("LabelText", buttonObject.transform, label, 24f, TextAlignmentOptions.Center);
        labelText.color = new Color(0.91f, 0.96f, 1f, 1f);
