    private static void ConfigureButtonTint(Button button, Color normal, Color highlighted, Color pressed)
    {
        ColorBlock colors = button.colors;
        colors.normalColor = normal;
        colors.highlightedColor = highlighted;
        colors.selectedColor = highlighted;
        colors.pressedColor = pressed;
        colors.disabledColor = new Color(0.45f, 0.45f, 0.45f, 0.55f);
        colors.colorMultiplier = 1f;
        colors.fadeDuration = 0.08f;
        button.colors = colors;
    }

    private static void ConfigureAnimatedButton(Button button, bool selectedOnEnable)
    {
        Animator animator = button.GetComponent<Animator>();
        if (animator == null)
            animator = button.gameObject.AddComponent<Animator>();

        animator.runtimeAnimatorController = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(UiButtonAnimatorControllerPath);
        animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;

        button.transition = Selectable.Transition.Animation;
        button.animationTriggers = new AnimationTriggers
        {
            normalTrigger = "Normal",
            highlightedTrigger = "Highlighted",
            pressedTrigger = "Pressed",
            selectedTrigger = "Selected",
            disabledTrigger = "Disabled"
        };

        WarlineCaptureButtonAnimationState initialState = button.GetComponent<WarlineCaptureButtonAnimationState>();
        if (initialState == null)
            initialState = button.gameObject.AddComponent<WarlineCaptureButtonAnimationState>();

        SetSerializedString(initialState, "initialStateName", selectedOnEnable ? "Selected" : "Normal");
        SetSerializedBool(initialState, "selectWithEventSystem", selectedOnEnable);

        UiMotionFeedback feedback = button.GetComponent<UiMotionFeedback>();
        if (feedback == null)
            feedback = button.gameObject.AddComponent<UiMotionFeedback>();

        feedback.ConfigureButtonDefaults(selectedOnEnable);

        ApplyButtonAnimationPose(button, selectedOnEnable);
    }

    private static void ApplyButtonAnimationPose(Button button, bool selected)
    {
        string initialClipPath = selected ? UiButtonSelectedClipPath : UiButtonNormalClipPath;
        AnimationClip initialClip = AssetDatabase.LoadAssetAtPath<AnimationClip>(initialClipPath);
        if (initialClip != null)
            initialClip.SampleAnimation(button.gameObject, 0f);
    }

