    private static void AddCleanFrame(Transform parent, Color edgeColor, float thickness)
    {
        AddFrameLine(parent, "Frame_Top", new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0f, -thickness), new Vector2(0f, 0f), edgeColor);
        AddFrameLine(parent, "Frame_Bottom", new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(0f, 0f), new Vector2(0f, thickness), edgeColor);
        AddFrameLine(parent, "Frame_Left", new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0f), new Vector2(thickness, 0f), edgeColor);
        AddFrameLine(parent, "Frame_Right", new Vector2(1f, 0f), new Vector2(1f, 1f), new Vector2(-thickness, 0f), new Vector2(0f, 0f), edgeColor);
    }

    private static void AddHudFrame(Transform parent, Color edgeColor, Color accentColor, float thickness)
    {
        AddFrameLine(parent, "Frame_Top", new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0f, -thickness), new Vector2(0f, 0f), edgeColor);
        AddFrameLine(parent, "Frame_Bottom", new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(0f, 0f), new Vector2(0f, thickness), edgeColor);
        AddFrameLine(parent, "Frame_Left", new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0f), new Vector2(thickness, 0f), edgeColor);
        AddFrameLine(parent, "Frame_Right", new Vector2(1f, 0f), new Vector2(1f, 1f), new Vector2(-thickness, 0f), new Vector2(0f, 0f), edgeColor);
        AddCorner(parent, "Corner_TL", new Vector2(0f, 1f), new Vector2(42f, 10f), accentColor);
        AddCorner(parent, "Corner_BR", new Vector2(1f, 0f), new Vector2(42f, 10f), accentColor);
    }

