    private static void ApplyScreenTypography(GameObject screen, params string[] boldTextPaths)
    {
        TMP_FontAsset lightFont = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(LightFontPath);
        TMP_FontAsset boldFont = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(BoldFontPath);
        if (lightFont == null || boldFont == null)
        {
            Debug.LogError($"[WarlineCaptureUI] Screen typography font missing. light={LightFontPath} bold={BoldFontPath}");
            return;
        }

        var boldTargets = new HashSet<Transform>();
        foreach (string path in boldTextPaths)
        {
            Transform target = screen.transform.Find(path);
            if (target != null)
                boldTargets.Add(target);
        }

        foreach (TMP_Text text in screen.GetComponentsInChildren<TMP_Text>(true))
        {
            bool useBold = boldTargets.Contains(text.transform);
            text.font = useBold ? boldFont : lightFont;
            text.fontStyle = FontStyles.Normal;
            ConfigureSingleLineText(text);
        }
    }

    private static void ConfigureSingleLineText(TMP_Text text)
    {
        text.textWrappingMode = TextWrappingModes.NoWrap;
        text.overflowMode = TextOverflowModes.Ellipsis;
    }

    private static void GenerateBrandArtAssets()
    {
        const string sourceLogoPath = "Assets/Game/Art/UI/Generated/Splash/Logos/Splash_Target_Emblem.png";
        if (!File.Exists(GameLogoPath) && File.Exists(sourceLogoPath))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(GameLogoPath));
            File.Copy(sourceLogoPath, GameLogoPath);
        }

        if (!File.Exists(GameLogoDisplayPath) && File.Exists(sourceLogoPath))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(GameLogoDisplayPath));
            File.Copy(sourceLogoPath, GameLogoDisplayPath);
        }

        AssetDatabase.ImportAsset(GameLogoPath);
        AssetDatabase.ImportAsset(GameLogoDisplayPath);
    }

