    private static void GenerateSettingsArtAssets()
    {
        Color panelFill = new Color(0.004f, 0.020f, 0.023f, 0.96f);
        Color sectionFill = new Color(0.006f, 0.030f, 0.035f, 0.97f);
        Color edge = new Color(0.54f, 0.64f, 0.66f, 0.72f);
        Color dimEdge = new Color(0.32f, 0.43f, 0.46f, 0.68f);
        Color accent = new Color(0.03f, 0.66f, 0.86f, 0.62f);

        WriteSettingsPanelPng(SettingsHeaderPanelPath, 1568, 104, panelFill, dimEdge, accent);
        WriteSettingsPanelPng(SettingsSectionPanelPath, 760, 322, sectionFill, dimEdge, accent);
        WriteSettingsButtonPng(SettingsTabNormalPath, 380, 66, new Color(0.006f, 0.022f, 0.024f, 0.98f), edge, accent, false);
        WriteSettingsButtonPng(SettingsTabSelectedPath, 380, 66, new Color(0.02f, 0.27f, 0.42f, 0.98f), new Color(0.10f, 0.62f, 0.82f, 0.80f), new Color(0.08f, 0.72f, 0.94f, 0.86f), true);
        WriteSettingsButtonPng(SettingsButtonNormalPath, 216, 64, new Color(0.007f, 0.025f, 0.028f, 0.98f), edge, accent, false);
        WriteSettingsButtonPng(SettingsButtonSelectedPath, 216, 64, new Color(0.02f, 0.27f, 0.42f, 0.98f), new Color(0.10f, 0.62f, 0.82f, 0.80f), accent, true);
        WriteSettingsDropdownPng(SettingsDropdownPath, 356, 56, new Color(0.004f, 0.020f, 0.022f, 0.96f), edge);
        WriteDropdownChevronPng(SettingsDropdownChevronPath, 48, 36, new Color(0.03f, 0.78f, 1f, 1f));
