    private static void GeneratePopupArtAssets()
    {
        if (ShouldUsePopupLayerPacks())
        {
            CopyPopupLayerPackAssets();
            ImportPopupArtAssets();
            return;
        }

        string pauseTargetSourcePath = ResolveProjectRelativeFilePath(PauseOptionsPopupTargetSourcePath);
        if (File.Exists(pauseTargetSourcePath))
        {
            var source = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            source.LoadImage(File.ReadAllBytes(pauseTargetSourcePath));
            Vector2[] buttonPolygon = CreateOctagonalChromePolygon(506, 84, 24f, 3f, 24f);
            WriteFlatMaskedChromeCropPng(
                source,
                PopupPauseButtonSelectedPath,
                583,
                source.height - 341 - 84,
                506,
                84,
                new Color(0.006f, 0.062f, 0.086f, 0.98f),
                buttonPolygon,
                new RectInt(44, 12, 82, 60),
                new RectInt(170, 12, 226, 60));
            WriteFlatMaskedChromeCropPng(
                source,
                PopupPauseButtonNormalPath,
                583,
                source.height - 438 - 82,
                506,
                82,
                new Color(0.006f, 0.018f, 0.021f, 0.98f),
                CreateOctagonalChromePolygon(506, 82, 22f, 3f, 22f),
                new RectInt(44, 10, 82, 60),
                new RectInt(150, 10, 268, 60));
            WriteFlatMaskedChromeCropPng(
                source,
                PopupPauseButtonDestructivePath,
                583,
                source.height - 728 - 82,
                506,
                82,
                new Color(0.070f, 0.014f, 0.010f, 0.98f),
                CreateOctagonalChromePolygon(506, 82, 22f, 3f, 22f),
                new RectInt(44, 10, 82, 60),
                new RectInt(128, 10, 332, 60));

            Object.DestroyImmediate(source);

            WriteTargetIconPng(PauseOptionsPopupTargetSourcePath, PopupPauseResumeIconPath, 636, 360, 76, 62, "move", new Color(0.55f, 0.94f, 1f, 1f));
            WriteTargetIconPng(PauseOptionsPopupTargetSourcePath, PopupPauseRestartIconPath, 642, 456, 64, 58, "refresh", new Color(0.82f, 0.84f, 0.84f, 1f));
            WriteTargetIconPng(PauseOptionsPopupTargetSourcePath, PopupPauseSettingsIconPath, 640, 553, 68, 64, "gear", new Color(0.82f, 0.84f, 0.84f, 1f));
            WriteTargetIconPng(PauseOptionsPopupTargetSourcePath, PopupPauseHelpIconPath, 642, 651, 62, 60, "help", new Color(0.82f, 0.84f, 0.84f, 1f));
            WriteTargetIconPng(PauseOptionsPopupTargetSourcePath, PopupPauseExitIconPath, 640, 747, 72, 58, "exit", new Color(1f, 0.42f, 0.34f, 1f));
        }
        else
        {
            WriteSettingsButtonPng(PopupPauseButtonSelectedPath, 506, 84, new Color(0.006f, 0.086f, 0.128f, 0.98f), new Color(0.05f, 0.70f, 0.92f, 0.88f), new Color(0.02f, 0.78f, 1f, 0.92f), true);
            WriteSettingsButtonPng(PopupPauseButtonNormalPath, 506, 82, new Color(0.006f, 0.018f, 0.021f, 0.98f), new Color(0.50f, 0.56f, 0.58f, 0.82f), new Color(0.02f, 0.70f, 0.92f, 0.48f), false);
            WriteSettingsButtonPng(PopupPauseButtonDestructivePath, 506, 82, new Color(0.070f, 0.014f, 0.010f, 0.98f), new Color(1f, 0.30f, 0.22f, 0.82f), new Color(1f, 0.28f, 0.18f, 0.78f), false);
        }

        string targetSourcePath = ResolveProjectRelativeFilePath(ThreatAlertPopupTargetSourcePath);
        if (File.Exists(targetSourcePath))
        {
            var source = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            source.LoadImage(File.ReadAllBytes(targetSourcePath));
            WriteBrightenedCropPng(source, ThreatAlertConvoyImagePath, 822, source.height - 397 - 274, 398, 274, 1.10f, 0.010f);
            WriteFlatMaskedChromeCropPng(
                source,
                PopupThreatInfoRowPath,
                454,
                source.height - 395 - 62,
                350,
                62,
                new Color(0.006f, 0.020f, 0.023f, 0.98f),
                CreateOctagonalChromePolygon(350, 62, 18f, 3f, 18f),
                new RectInt(16, 7, 62, 48),
                new RectInt(76, 8, 126, 44),
                new RectInt(210, 7, 116, 48));
            WriteFrameOverlayCropPng(
                source,
                PopupThreatImageFramePath,
                817,
                source.height - 395 - 294,
                410,
                294,
                CreateOctagonalChromePolygon(410, 294, 30f, 2f, 30f),
                CreateOctagonalChromePolygon(410, 294, 42f, 16f, 42f));
            WriteTargetIconPng(ThreatAlertPopupTargetSourcePath, PopupThreatWarningIconPath, 520, 221, 98, 98, "warning", new Color(1f, 0.24f, 0.18f, 1f));
            WriteTargetIconPng(ThreatAlertPopupTargetSourcePath, PopupThreatEtaIconPath, 472, 411, 44, 44, "clock", new Color(1f, 0.30f, 0.24f, 1f));
            WriteTargetIconPng(ThreatAlertPopupTargetSourcePath, PopupThreatRouteIconPath, 470, 486, 44, 50, "flag", new Color(1f, 0.30f, 0.24f, 1f));
            WriteTargetIconPng(ThreatAlertPopupTargetSourcePath, PopupThreatStrengthIconPath, 468, 560, 50, 54, "shield-small", new Color(1f, 0.30f, 0.24f, 1f));
            Object.DestroyImmediate(source);
        }
        else if (!File.Exists(ThreatAlertConvoyImagePath) && File.Exists(MatchHudIsoApcPath))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(ThreatAlertConvoyImagePath));
            File.Copy(MatchHudIsoApcPath, ThreatAlertConvoyImagePath);
        }

        string buildPlacementTargetSourcePath = ResolveProjectRelativeFilePath(BuildPlacementPopupTargetSourcePath);
        if (File.Exists(buildPlacementTargetSourcePath))
        {
            var source = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            source.LoadImage(File.ReadAllBytes(buildPlacementTargetSourcePath));
            WriteBrightenedCropPng(source, PopupBuildPowerPlantPreviewPath, 390, source.height - 682 - 168, 236, 168, 1.06f, 0.012f);
            WriteTransparentGreenContentCropPng(source, PopupBuildGhostBuildingPath, 390, source.height - 682 - 168, 236, 168);
            Object.DestroyImmediate(source);
