        else if (!File.Exists(PopupBuildPowerPlantPreviewPath) && File.Exists(MatchHudIsoForwardCommandHqPath))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(PopupBuildPowerPlantPreviewPath));
            File.Copy(MatchHudIsoForwardCommandHqPath, PopupBuildPowerPlantPreviewPath);
