        WritePopupStackButtonPng(PopupPauseButtonSelectedPath, 506, 84, true, false);
        WritePopupStackButtonPng(PopupPauseButtonNormalPath, 506, 82, false, false);
        WritePopupStackButtonPng(PopupPauseButtonDestructivePath, 506, 82, false, true);
        WritePopupIconPng(PopupPauseResumeIconPath, "play", new Color(0.58f, 0.94f, 1f, 1f));
