            410,
            294,
            CreateOctagonalChromePolygon(410, 294, 30f, 2f, 30f),
            CreateOctagonalChromePolygon(410, 294, 38f, 8f, 38f),
            new Color(0.18f, 0.30f, 0.34f, 0.78f),
            new Color(0.04f, 0.40f, 0.50f, 0.56f),
