    private static bool ShouldUsePopupLayerPacks()
    {
        RequirePopupLayerPack(PopupPauseLayerPackRoot, "POP-07_PauseOptions");
        RequirePopupLayerPack(PopupThreatLayerPackRoot, "POP-01_ThreatAlert");
        RequirePopupLayerPack(PopupBuildPlacementLayerPackRoot, "POP-03_BuildPlacement");
        RequirePopupLayerPack(MissionResultLayerPackRoot, "POP-05_MissionResult");
        RequirePopupLayerPack(RewardUnlockLayerPackRoot, "POP-04_RewardUnlock");
        RequirePopupLayerPack(EndOfDayLayerPackRoot, "POP-06_EndOfDayReport");
        RequirePopupLayerPack(IntelRevealLayerPackRoot, "POP-08_IntelReveal");
        RequirePopupLayerPack(AbilityUpgradeLayerPackRoot, "POP-09_AbilityUpgradeDetail");
        return true;
    }

