    private static void RequirePopupLayerPack(string packRootRelativePath, string surfaceId)
    {
        RequireProjectRelativeFile($"{packRootRelativePath}/reference/{surfaceId}_Landscape_Target.png");
        RequireProjectRelativeFile($"{packRootRelativePath}/layer_manifest.json");
        RequireProjectRelativeFile($"{packRootRelativePath}/generated_one_go/layers_contact_sheet.png");
        RequireProjectRelativeFile($"{packRootRelativePath}/README.md");
    }

    private static void CopyPopupLayer(string packRootRelativePath, string layerFileName, string destinationAssetPath)
    {
        string sourcePath = RequireProjectRelativeFile($"{packRootRelativePath}/layers/{layerFileName}");
        Directory.CreateDirectory(Path.GetDirectoryName(destinationAssetPath));
        File.Copy(sourcePath, destinationAssetPath, true);
        AssetDatabase.ImportAsset(destinationAssetPath, ImportAssetOptions.ForceSynchronousImport | ImportAssetOptions.ForceUpdate);
    }

    private static string ArmoryLayerPath(string fileName)
    {
        return $"{ArmoryGeneratedRoot}/{fileName}";
    }

    private static string CommandExchangeLayerPath(string relativePath)
    {
        return $"{CommandExchangeGeneratedRoot}/{relativePath}";
    }

    private static string DesignedUnavailableLayerPath(string generatedRoot, string relativePath)
    {
        return $"{generatedRoot}/{relativePath}";
    }

