    private static void GenerateSagaCampaignArtAssets()
    {
        RequirePopupLayerPack(SagaMapLayerPackRoot, "SCN-05_SagaMap");
        RequirePopupLayerPack(MissionBriefingLayerPackRoot, "SCN-06_MissionBriefing");
        RequirePopupLayerPack(LoadoutLayerPackRoot, "SCN-07_LoadoutSquadPrep");
        foreach (string layerFile in SagaMapLayerFiles)
            CopyPopupLayer(SagaMapLayerPackRoot, layerFile, CampaignLayerPath(SagaMapGeneratedRoot, layerFile));
        foreach (string layerFile in MissionBriefingLayerFiles)
            CopyPopupLayer(MissionBriefingLayerPackRoot, layerFile, CampaignLayerPath(MissionBriefingGeneratedRoot, layerFile));
        foreach (string layerFile in LoadoutLayerFiles)
            CopyPopupLayer(LoadoutLayerPackRoot, layerFile, CampaignLayerPath(LoadoutGeneratedRoot, layerFile));
    }

    private static void EnsureSagaCampaignGeneratedSprites()
    {
        EnsureCampaignSprites(SagaMapGeneratedRoot, SagaMapAtlasLabel, SagaMapLayerFiles);
        EnsureCampaignSprites(MissionBriefingGeneratedRoot, MissionBriefingAtlasLabel, MissionBriefingLayerFiles);
        EnsureLoadoutSprites();
    }

    private static void EnsureLoadoutSprites()
    {
        EnsureGeneratedSpriteFolder(LoadoutGeneratedRoot, LoadoutAtlasLabel);
        foreach (string layerFile in LoadoutSlicedLayerFiles)
            EnsureSlicedSpriteImport(CampaignLayerPath(LoadoutGeneratedRoot, layerFile), new Vector4(24f, 24f, 24f, 24f));
        foreach (string layerFile in LoadoutLayerFiles)
            EnsureSpriteImport(CampaignLayerPath(LoadoutGeneratedRoot, layerFile), LoadoutAtlasLabel);
        EnsureSpriteImport(CampaignLayerPath(LoadoutGeneratedRoot, "target_depth_underlay.png"), LoadoutAtlasLabel);
        foreach (string cropFile in LoadoutTargetCropFiles)
            EnsureSpriteImport(CampaignLayerPath(LoadoutTargetCropRoot, cropFile), LoadoutAtlasLabel);
    }

    private static void EnsureCampaignSprites(string generatedRoot, string atlasLabel, string[] layerFiles)
    {
        EnsureGeneratedSpriteFolder(generatedRoot, atlasLabel);
        foreach (string layerFile in SagaCampaignSlicedLayerFiles)
        {
            string path = CampaignLayerPath(generatedRoot, layerFile);
            if (File.Exists(path))
                EnsureSlicedSpriteImport(path, new Vector4(24f, 24f, 24f, 24f));
        }

        foreach (string layerFile in layerFiles)
            EnsureSpriteImport(CampaignLayerPath(generatedRoot, layerFile), atlasLabel);
    }

