    private static void GenerateDesignedUnavailableArtAssets(string packRoot, string generatedRoot, string surfaceId)
    {
        RequireProjectRelativeFile($"{packRoot}/reference/{surfaceId}_Landscape_Target.png");
        RequireProjectRelativeFile($"{packRoot}/layer_manifest.json");
        RequireProjectRelativeFile($"{packRoot}/generated_one_go/layers_contact_sheet.png");
        RequireProjectRelativeFile($"{packRoot}/README.md");
        foreach (CommandExchangeLayerCopy layerFile in CommandExchangeLayerFiles)
            CopyPopupLayer(packRoot, layerFile.SourceFileName, DesignedUnavailableLayerPath(generatedRoot, layerFile.DestinationRelativePath));
    }

    private static void EnsureDesignedUnavailableSprites(string generatedRoot, string atlasLabel)
    {
        EnsureGeneratedSpriteFolder(generatedRoot, atlasLabel);
        EnsureGeneratedSpriteFolder($"{generatedRoot}/Frames", atlasLabel);
        EnsureGeneratedSpriteFolder($"{generatedRoot}/Buttons", atlasLabel);
        EnsureGeneratedSpriteFolder($"{generatedRoot}/Cards", atlasLabel);
        EnsureGeneratedSpriteFolder($"{generatedRoot}/Icons", atlasLabel);
        EnsureGeneratedSpriteFolder($"{generatedRoot}/Content", atlasLabel);

        foreach (CommandExchangeSlicedLayer layerFile in CommandExchangeSlicedLayerFiles)
            EnsureSlicedSpriteImport(DesignedUnavailableLayerPath(generatedRoot, layerFile.DestinationRelativePath), layerFile.Border);

        foreach (CommandExchangeLayerCopy layerFile in CommandExchangeLayerFiles)
            EnsureSpriteImport(DesignedUnavailableLayerPath(generatedRoot, layerFile.DestinationRelativePath), atlasLabel);

        if (generatedRoot == CommanderProfileGeneratedRoot)
        {
            string[] rewardNodeComposites =
            {
                "Content/reward_node_10_full_target.png",
                "Content/reward_node_20_full_target.png",
                "Content/reward_node_30_full_target.png",
                "Content/reward_node_40_full_target.png",
                "Content/reward_node_50_full_target.png",
                "Content/reward_plaque_10_target.png",
                "Content/reward_plaque_20_target.png",
                "Content/reward_plaque_30_target.png",
                "Content/reward_plaque_40_target.png",
                "Content/reward_plaque_50_target.png"
            };

            foreach (string rewardNodeComposite in rewardNodeComposites)
                EnsureSpriteImport(DesignedUnavailableLayerPath(generatedRoot, rewardNodeComposite), atlasLabel);
        }
    }

