    private static void GenerateMatchHudArtAssets()
    {
        string targetSourcePath = ResolveProjectRelativeFilePath(MatchHudTargetSourcePath);
        bool hasTargetSource = File.Exists(targetSourcePath);
        Texture2D source = null;
        if (hasTargetSource)
        {
            source = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            source.LoadImage(File.ReadAllBytes(targetSourcePath));

            Color panelFill = new Color(0.010f, 0.032f, 0.037f, 0.965f);
            WriteCleanPanelBackingPng(
                MatchHudObjectivePanelPath,
                358,
                282,
                CreateOctagonalChromePolygon(358, 282, 16f, 4f, 16f),
                new Color(0.006f, 0.021f, 0.025f, 0.955f),
                new Color(0.001f, 0.008f, 0.010f, 0.97f),
                new Color(0.38f, 0.48f, 0.51f, 0.78f),
                new Color(0.014f, 0.104f, 0.124f, 0.78f),
                new Color(0.02f, 0.78f, 1f, 0.74f));
            WriteBeveledFillPng(
                MatchHudObjectivePanelFillPath,
                358,
                282,
                panelFill,
                new Color(0.004f, 0.018f, 0.021f, 0.965f),
                CreateOctagonalChromePolygon(358, 282, 31f, 10f, 31f));
            WriteCleanPanelBackingPng(
                MatchHudThreatPanelPath,
                296,
                222,
                CreateOctagonalChromePolygon(296, 222, 14f, 4f, 14f),
                new Color(0.006f, 0.021f, 0.025f, 0.955f),
                new Color(0.001f, 0.008f, 0.010f, 0.97f),
                new Color(0.38f, 0.48f, 0.51f, 0.78f),
                new Color(0.014f, 0.104f, 0.124f, 0.78f),
                new Color(0.02f, 0.78f, 1f, 0.74f));
            WriteBeveledFillPng(
                MatchHudThreatPanelFillPath,
                296,
                222,
                panelFill,
                new Color(0.004f, 0.018f, 0.021f, 0.965f),
                CreateOctagonalChromePolygon(296, 222, 29f, 10f, 29f));
            WriteCleanPanelBackingPng(
                MatchHudMiniMapPanelPath,
                314,
                306,
                CreateOctagonalChromePolygon(314, 306, 14f, 4f, 14f),
                new Color(0.006f, 0.020f, 0.024f, 0.94f),
                new Color(0.001f, 0.008f, 0.010f, 0.96f),
                new Color(0.42f, 0.52f, 0.56f, 0.82f),
                new Color(0.020f, 0.115f, 0.135f, 0.86f),
                new Color(0.02f, 0.78f, 1f, 0.74f));
