            WriteMatchHudResourceBarPng(MatchHudResourceBarPath, 636, 62);
            WriteBeveledFillPng(
                MatchHudResourceBarFillPath,
                636,
                62,
                new Color(0.008f, 0.019f, 0.023f, 0.985f),
                new Color(0.002f, 0.008f, 0.010f, 0.985f),
                CreateOctagonalChromePolygon(636, 62, 21f, 8f, 21f));
            WriteMatchHudThreatAlertPng(MatchHudThreatAlertPath, 250, 34);
            WriteCropPng(source, MatchHudMiniMapContentPath, 1364, source.height - 620 - 262, 280, 262);
            WriteMatchHudSquadTrayPng(MatchHudSquadTrayPath, 654, 218);
            WriteBeveledFillPng(
                MatchHudSquadTrayFillPath,
                654,
