                new Color(0.006f, 0.018f, 0.021f, 0.92f),
                new Color(0.001f, 0.008f, 0.010f, 0.94f),
                new Color(0.44f, 0.53f, 0.56f, 0.78f),
                new Color(0.025f, 0.10f, 0.12f, 0.82f),
                new Color(0.02f, 0.75f, 1f, 0.62f));
            WriteBeveledFillPng(
