    private static void CopyCommandWheelLayerPackAssets()
    {
        RequireProjectRelativeFile($"{CommandWheelLayerPackRoot}/reference/SCN-10_UnitCommandWheel_Landscape_Target.png");
        RequireProjectRelativeFile($"{CommandWheelLayerPackRoot}/layer_manifest.json");
        RequireProjectRelativeFile($"{CommandWheelLayerPackRoot}/generated_one_go/layers_contact_sheet.png");
        RequireProjectRelativeFile($"{CommandWheelLayerPackRoot}/README.md");

        CopyPopupLayer(CommandWheelLayerPackRoot, "Frames/context_hint_frame.png", CommandWheelContextHintFramePath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Frames/context_hint_fill.png", CommandWheelContextHintFillPath);
