        CopyPopupLayer(CommandWheelLayerPackRoot, "Content/targeting_ring.png", CommandWheelTargetingRingPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Buttons/wheel_segment_normal.png", CommandWheelSegmentNormalPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Buttons/wheel_segment_selected.png", CommandWheelSegmentSelectedPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Buttons/wheel_close_button.png", CommandWheelCloseButtonPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Icons/command_extract_icon.png", CommandWheelExtractIconPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Icons/command_rope_drop_icon.png", CommandWheelRopeDropIconPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Icons/command_patrol_icon.png", CommandWheelPatrolIconPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Icons/command_hint_info_icon.png", CommandWheelHintInfoIconPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Icons/command_wheel_close_icon.png", CommandWheelCloseIconPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Icons/command_target_brackets.png", CommandWheelTargetBracketsIconPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Icons/command_blackhawk_icon.png", CommandWheelBlackhawkIconPath);
        CopyPopupLayer(CommandWheelLayerPackRoot, "Content/blackhawk_unit_art.png", CommandWheelBlackhawkArtPath);
