    private static void ApplyDefaultFont(TMP_Text text)
    {
        text.font = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(DefaultFontPath);
    }

    private static void NormalizeFontsInPrefab(string path)
    {
        TMP_FontAsset defaultFont = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(DefaultFontPath);
        if (defaultFont == null)
        {
            Debug.LogError($"[WarlineCaptureUI] Default TMP font missing at {DefaultFontPath}");
            return;
        }

        GameObject prefabRoot = PrefabUtility.LoadPrefabContents(path);
        try
        {
            string prefabName = Path.GetFileName(path);
            if (prefabName == "Screen_Settings.prefab")
            {
                ApplyScreenTypography(prefabRoot, "HeaderBar/TitleText");
            }
            else if (prefabName == "Screen_QuickCustomSetup.prefab")
            {
                ApplyScreenTypography(prefabRoot, "HeaderBar/TitleText", "LaunchButton/LabelText");
            }
            else
            {
                ApplyScreenTypography(
                    prefabRoot,
                    "HeaderBar/TitleText",
                    "TitleText",
                    "MissionTitleText",
                    "ChapterTitleText",
                    "HeroPanel/HeroTitleText",
                    "OutcomeText",
                    "DeployButton/LabelText",
                    "StartMissionButton/LabelText",
                    "LaunchButton/LabelText",
                    "ContinueButton/LabelText",
                    "ConfirmButton/LabelText",
                    "PrimaryButton/LabelText",
                    "EndDayButton/LabelText");
            }

            PrefabUtility.SaveAsPrefabAsset(prefabRoot, path);
        }
        finally
        {
            PrefabUtility.UnloadPrefabContents(prefabRoot);
        }
    }

