    private static void EnsureSpriteAtlas(string atlasPath, int maxTextureSize, string[] packablePaths)
    {
        SpriteAtlas atlas = AssetDatabase.LoadAssetAtPath<SpriteAtlas>(atlasPath);
        if (atlas == null)
        {
            atlas = new SpriteAtlas();
            AssetDatabase.CreateAsset(atlas, atlasPath);
        }

        var packables = new List<Object>();
        foreach (string packablePath in packablePaths)
        {
            Object packable = AssetDatabase.LoadAssetAtPath<Object>(packablePath);
            if (packable != null)
                packables.Add(packable);
        }

        Object[] existingPackables = SpriteAtlasExtensions.GetPackables(atlas);
        if (existingPackables.Length > 0)
            SpriteAtlasExtensions.Remove(atlas, existingPackables);

        if (packables.Count > 0)
            SpriteAtlasExtensions.Add(atlas, packables.ToArray());

        var packingSettings = new SpriteAtlasPackingSettings
        {
            blockOffset = 1,
            enableRotation = false,
            enableTightPacking = false,
            padding = 4
        };
        SpriteAtlasExtensions.SetPackingSettings(atlas, packingSettings);

        var textureSettings = new SpriteAtlasTextureSettings
        {
            filterMode = FilterMode.Bilinear,
            generateMipMaps = false,
            readable = false,
            sRGB = true
        };
        SpriteAtlasExtensions.SetTextureSettings(atlas, textureSettings);

        SetAtlasPlatformSettings(atlas, "DefaultTexturePlatform", maxTextureSize, TextureImporterFormat.Automatic);
        SetAtlasPlatformSettings(atlas, "Android", maxTextureSize, TextureImporterFormat.ASTC_6x6);
        SpriteAtlasExtensions.SetIncludeInBuild(atlas, true);
        EditorUtility.SetDirty(atlas);
    }

    private static void SetAtlasPlatformSettings(SpriteAtlas atlas, string platformName, int maxTextureSize, TextureImporterFormat format)
    {
        var platformSettings = new TextureImporterPlatformSettings
        {
            name = platformName,
            overridden = platformName != "DefaultTexturePlatform",
            maxTextureSize = maxTextureSize,
            format = format,
            compressionQuality = 50
        };
        SpriteAtlasExtensions.SetPlatformSettings(atlas, platformSettings);
    }

    private static void WriteCropPng(Texture2D source, string outputPath, int x, int y, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        crop.SetPixels(source.GetPixels(x, y, width, height));
        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteBrightenedCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, float multiplier, float lift)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        Color[] pixels = source.GetPixels(x, y, width, height);
        for (int i = 0; i < pixels.Length; i++)
        {
            Color pixel = pixels[i];
            pixel.r = Mathf.Clamp01(pixel.r * multiplier + lift);
            pixel.g = Mathf.Clamp01(pixel.g * multiplier + lift);
            pixel.b = Mathf.Clamp01(pixel.b * multiplier + lift);
            pixels[i] = pixel;
        }

        crop.SetPixels(pixels);
        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteTransparentGreenContentCropPng(Texture2D source, string outputPath, int x, int y, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        Color[] pixels = source.GetPixels(x, y, width, height);
        for (int i = 0; i < pixels.Length; i++)
        {
            Color pixel = pixels[i];
            float brightness = (pixel.r + pixel.g + pixel.b) / 3f;
            float greenBias = Mathf.Clamp01(pixel.g - Mathf.Max(pixel.r, pixel.b) * 0.55f);
            float alpha = Mathf.Clamp01((brightness - 0.14f) * 3.2f + greenBias * 0.65f) * 0.78f;
            if (alpha < 0.10f)
            {
                pixels[i] = Color.clear;
                continue;
            }

            float intensity = Mathf.Clamp01(0.42f + brightness * 1.05f);
            pixels[i] = new Color(0.42f * intensity, 1.0f * intensity, 0.55f * intensity, alpha);
        }

        crop.SetPixels(pixels);
        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteBuildPlacementGridOverlayPng(string outputPath)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        const int width = 724;
        const int height = 396;
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        for (int yy = 0; yy < height; yy++)
        {
            for (int xx = 0; xx < width; xx++)
                texture.SetPixel(xx, yy, Color.clear);
        }

        Vector2 topLeft = new(110f, 228f);
        Vector2 topRight = new(484f, 34f);
        Vector2 bottomRight = new(686f, 198f);
        Vector2 bottomLeft = new(304f, 372f);
        Vector2[] floor = { topLeft, topRight, bottomRight, bottomLeft };
        DrawFilledPolygon(texture, floor, new Color(0.12f, 0.95f, 0.18f, 0.16f));

        Color major = new(0.42f, 1f, 0.48f, 0.82f);
        Color minor = new(0.42f, 1f, 0.48f, 0.44f);
        for (int i = 0; i < floor.Length; i++)
            DrawThickLine(texture, floor[i], floor[(i + 1) % floor.Length], 2f, major);

        for (int i = 1; i < 7; i++)
        {
            float t = i / 7f;
            DrawThickLine(texture, Vector2.Lerp(topLeft, bottomLeft, t), Vector2.Lerp(topRight, bottomRight, t), 1.25f, minor);
            DrawThickLine(texture, Vector2.Lerp(topLeft, topRight, t), Vector2.Lerp(bottomLeft, bottomRight, t), 1.25f, minor);
        }

        DrawThickLine(texture, new Vector2(316f, 328f), new Vector2(332f, 342f), 2f, new Color(0.72f, 1f, 0.82f, 0.88f));
        DrawThickLine(texture, new Vector2(332f, 342f), new Vector2(350f, 326f), 2f, new Color(0.72f, 1f, 0.82f, 0.88f));
        DrawThickLine(texture, new Vector2(552f, 196f), new Vector2(568f, 210f), 2f, new Color(0.72f, 1f, 0.82f, 0.78f));
        DrawThickLine(texture, new Vector2(568f, 210f), new Vector2(586f, 194f), 2f, new Color(0.72f, 1f, 0.82f, 0.78f));
        DrawDisc(texture, new Vector2(268f, 214f), 4f, new Color(0.78f, 1f, 0.86f, 0.86f));
        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

