    private static void WriteMaskedCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, Color fillColor, params RectInt[] masksFromTop)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        crop.SetPixels(source.GetPixels(x, y, width, height));

        foreach (RectInt mask in masksFromTop)
        {
            int startX = Mathf.Clamp(mask.x, 0, width);
            int endX = Mathf.Clamp(mask.x + mask.width, 0, width);
            int startY = Mathf.Clamp(height - mask.y - mask.height, 0, height);
            int endY = Mathf.Clamp(height - mask.y, 0, height);

            for (int yy = startY; yy < endY; yy++)
            {
                float vertical = height <= 1 ? 0f : yy / (float)(height - 1);
                Color verticalFill = Color.Lerp(new Color(fillColor.r * 0.72f, fillColor.g * 0.72f, fillColor.b * 0.72f, fillColor.a), fillColor, Mathf.SmoothStep(0f, 1f, vertical));
                Color leftEdge = startX > 0 ? crop.GetPixel(startX - 1, yy) : verticalFill;
                Color rightEdge = endX < width ? crop.GetPixel(endX, yy) : verticalFill;

                for (int xx = startX; xx < endX; xx++)
                {
                    float horizontal = endX - startX <= 1 ? 0f : (xx - startX) / (float)(endX - startX - 1);
                    Color edgeFill = Color.Lerp(leftEdge, rightEdge, Mathf.SmoothStep(0f, 1f, horizontal));
                    crop.SetPixel(xx, yy, Color.Lerp(edgeFill, verticalFill, 0.45f));
                }
            }
        }

        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteTransparentMaskedCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, params RectInt[] masksFromTop)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        crop.SetPixels(source.GetPixels(x, y, width, height));

        foreach (RectInt mask in masksFromTop)
        {
            int startX = Mathf.Clamp(mask.x, 0, width);
            int endX = Mathf.Clamp(mask.x + mask.width, 0, width);
            int startY = Mathf.Clamp(height - mask.y - mask.height, 0, height);
            int endY = Mathf.Clamp(height - mask.y, 0, height);

            for (int yy = startY; yy < endY; yy++)
            {
                for (int xx = startX; xx < endX; xx++)
                    crop.SetPixel(xx, yy, Color.clear);
            }
        }

        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteFlatMaskedCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, Color fillColor, params RectInt[] masksFromTop)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        crop.SetPixels(source.GetPixels(x, y, width, height));

        foreach (RectInt mask in masksFromTop)
        {
            int startX = Mathf.Clamp(mask.x, 0, width);
            int endX = Mathf.Clamp(mask.x + mask.width, 0, width);
            int startY = Mathf.Clamp(height - mask.y - mask.height, 0, height);
            int endY = Mathf.Clamp(height - mask.y, 0, height);
            Color sampledFill = SampleMaskedCropFill(crop, startX, endX, startY, endY, fillColor);

            for (int yy = startY; yy < endY; yy++)
            {
                float vertical = height <= 1 ? 0f : yy / (float)(height - 1);
                Color blendedFill = Color.Lerp(
                    new Color(sampledFill.r * 0.86f, sampledFill.g * 0.86f, sampledFill.b * 0.86f, sampledFill.a),
                    sampledFill,
                    Mathf.SmoothStep(0f, 1f, vertical));
                for (int xx = startX; xx < endX; xx++)
                    crop.SetPixel(xx, yy, blendedFill);
            }
        }

        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteFlatMaskedChromeCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, Color fillColor, Vector2[] opaquePolygon, params RectInt[] masksFromTop)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        crop.SetPixels(source.GetPixels(x, y, width, height));

        foreach (RectInt mask in masksFromTop)
            FillMaskFromTop(crop, mask, fillColor);

        ApplyAlphaOutsidePolygon(crop, opaquePolygon);
        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteSolidMaskedChromeCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, Color fillColor, Color edgeColor, Vector2[] opaquePolygon, params RectInt[] masksFromTop)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        crop.SetPixels(source.GetPixels(x, y, width, height));

        foreach (RectInt mask in masksFromTop)
            FillSolidMaskFromTop(crop, mask, fillColor);

        ApplyAlphaOutsidePolygon(crop, opaquePolygon);
        for (int i = 0; i < opaquePolygon.Length; i++)
            DrawThickLine(crop, opaquePolygon[i], opaquePolygon[(i + 1) % opaquePolygon.Length], 1.15f, edgeColor);

        DrawThickLine(
            crop,
            new Vector2(opaquePolygon[0].x + 6f, opaquePolygon[0].y + 2f),
            new Vector2(opaquePolygon[1].x - 6f, opaquePolygon[1].y + 2f),
            1.05f,
            new Color(edgeColor.r, edgeColor.g, edgeColor.b, edgeColor.a * 0.72f));
        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteTransparentMaskedChromeCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, Vector2[] opaquePolygon, params RectInt[] masksFromTop)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        crop.SetPixels(source.GetPixels(x, y, width, height));

        foreach (RectInt mask in masksFromTop)
            ClearMaskFromTop(crop, mask);

        ApplyAlphaOutsidePolygon(crop, opaquePolygon);
        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteFrameOverlayCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, Vector2[] outerPolygon, Vector2[] innerClearPolygon, params RectInt[] clearMasksFromTop)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        crop.SetPixels(source.GetPixels(x, y, width, height));

        for (int yy = 0; yy < height; yy++)
        {
            for (int xx = 0; xx < width; xx++)
            {
                Vector2 point = new Vector2(xx + 0.5f, yy + 0.5f);
                bool keepFramePixel = IsPointInsideConvexPolygon(point, outerPolygon) &&
                    !IsPointInsideConvexPolygon(point, innerClearPolygon);
                Color framePixel = crop.GetPixel(xx, yy);
                if (!keepFramePixel || !IsMatchHudFramePixel(framePixel))
                {
                    crop.SetPixel(xx, yy, Color.clear);
                    continue;
                }

                crop.SetPixel(xx, yy, NormalizeMatchHudFramePixel(framePixel));
            }
        }

        foreach (RectInt mask in clearMasksFromTop)
            ClearMaskFromTop(crop, mask);

        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WriteCleanFrameOverlayPng(string outputPath, int width, int height, Vector2[] outerPolygon, Vector2[] innerClearPolygon, Color outerEdge, Color innerEdge, Color accent)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        Color[] clearPixels = new Color[width * height];
        for (int i = 0; i < clearPixels.Length; i++)
            clearPixels[i] = Color.clear;
        texture.SetPixels(clearPixels);

        for (int yy = 0; yy < height; yy++)
        {
            float vertical = height <= 1 ? 0f : yy / (float)(height - 1);
            for (int xx = 0; xx < width; xx++)
            {
                Vector2 point = new Vector2(xx + 0.5f, yy + 0.5f);
                if (!IsPointInsideConvexPolygon(point, outerPolygon) || IsPointInsideConvexPolygon(point, innerClearPolygon))
                    continue;

                float edgeFade = Mathf.Clamp01(Mathf.Min(
                    Mathf.Min(xx, width - 1 - xx) / 18f,
                    Mathf.Min(yy, height - 1 - yy) / 16f));
                Color pixel = Color.Lerp(outerEdge, innerEdge, Mathf.SmoothStep(0f, 1f, vertical) * 0.55f + edgeFade * 0.25f);
                pixel.a *= 0.92f;
                texture.SetPixel(xx, yy, pixel);
            }
        }

        for (int i = 0; i < outerPolygon.Length; i++)
            DrawThickLine(texture, outerPolygon[i], outerPolygon[(i + 1) % outerPolygon.Length], 1.3f, outerEdge);
        for (int i = 0; i < innerClearPolygon.Length; i++)
            DrawThickLine(texture, innerClearPolygon[i], innerClearPolygon[(i + 1) % innerClearPolygon.Length], 1f, innerEdge);

        DrawThickLine(texture, new Vector2(42f, height - 7f), new Vector2(150f, height - 7f), 1.1f, accent);
        DrawThickLine(texture, new Vector2(width - 160f, 7f), new Vector2(width - 48f, 7f), 1.1f, new Color(accent.r, accent.g, accent.b, accent.a * 0.55f));

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteCleanPanelBackingPng(string outputPath, int width, int height, Vector2[] outerPolygon, Color topFill, Color bottomFill, Color outerEdge, Color innerEdge, Color accent)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);

        for (int yy = 0; yy < height; yy++)
        {
            float vertical = height <= 1 ? 0f : yy / (float)(height - 1);
            Color fill = Color.Lerp(bottomFill, topFill, Mathf.SmoothStep(0f, 1f, vertical));
            for (int xx = 0; xx < width; xx++)
            {
                Vector2 point = new Vector2(xx + 0.5f, yy + 0.5f);
                if (!IsPointInsideConvexPolygon(point, outerPolygon))
                {
                    texture.SetPixel(xx, yy, Color.clear);
                    continue;
                }

                float edgeFade = Mathf.Clamp01(Mathf.Min(
                    Mathf.Min(xx, width - 1 - xx) / 28f,
                    Mathf.Min(yy, height - 1 - yy) / 24f));
                Color pixel = Color.Lerp(
                    new Color(fill.r * 0.58f, fill.g * 0.58f, fill.b * 0.58f, fill.a),
                    fill,
                    Mathf.SmoothStep(0f, 1f, edgeFade));
                texture.SetPixel(xx, yy, pixel);
            }
        }

        Vector2[] innerLine = CreateOctagonalChromePolygon(width, height, 22f, 11f, 22f);
        for (int i = 0; i < outerPolygon.Length; i++)
            DrawThickLine(texture, outerPolygon[i], outerPolygon[(i + 1) % outerPolygon.Length], 1.3f, outerEdge);
        for (int i = 0; i < innerLine.Length; i++)
            DrawThickLine(texture, innerLine[i], innerLine[(i + 1) % innerLine.Length], 1f, innerEdge);

        DrawThickLine(texture, new Vector2(42f, height - 7f), new Vector2(150f, height - 7f), 1.1f, accent);
        DrawThickLine(texture, new Vector2(width - 160f, 7f), new Vector2(width - 48f, 7f), 1.1f, new Color(accent.r, accent.g, accent.b, accent.a * 0.55f));

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteBeveledFillPng(string outputPath, int width, int height, Color topColor, Color bottomColor, Vector2[] fillPolygon)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);

        for (int yy = 0; yy < height; yy++)
        {
            float vertical = height <= 1 ? 0f : yy / (float)(height - 1);
            Color fill = Color.Lerp(bottomColor, topColor, Mathf.SmoothStep(0f, 1f, vertical));
            for (int xx = 0; xx < width; xx++)
            {
                Vector2 point = new Vector2(xx + 0.5f, yy + 0.5f);
                if (!IsPointInsideConvexPolygon(point, fillPolygon))
                {
                    texture.SetPixel(xx, yy, Color.clear);
                    continue;
                }

                float horizontal = width <= 1 ? 0f : xx / (float)(width - 1);
                float edgeShade = Mathf.Clamp01(Mathf.Min(horizontal, 1f - horizontal) * 8f);
                Color pixel = Color.Lerp(new Color(fill.r * 0.72f, fill.g * 0.72f, fill.b * 0.72f, fill.a), fill, edgeShade);
                texture.SetPixel(xx, yy, pixel);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void FillMaskFromTop(Texture2D texture, RectInt mask, Color fillColor)
    {
        int startX = Mathf.Clamp(mask.x, 0, texture.width);
        int endX = Mathf.Clamp(mask.x + mask.width, 0, texture.width);
        int startY = Mathf.Clamp(texture.height - mask.y - mask.height, 0, texture.height);
        int endY = Mathf.Clamp(texture.height - mask.y, 0, texture.height);

        for (int yy = startY; yy < endY; yy++)
        {
            for (int xx = startX; xx < endX; xx++)
            {
                float horizontal = endX - startX <= 1 ? 0.5f : (xx - startX) / (float)(endX - startX - 1);
                float vertical = endY - startY <= 1 ? 0.5f : (yy - startY) / (float)(endY - startY - 1);

                Color left = FindMaskFillSample(texture, startX, endX, yy, -1, fillColor);
                Color right = FindMaskFillSample(texture, startX, endX, yy, 1, fillColor);
                Color sideFill = Color.Lerp(left, right, Mathf.SmoothStep(0f, 1f, horizontal));

                Color top = FindMaskFillSample(texture, startY, endY, xx, -1, fillColor, true);
                Color bottom = FindMaskFillSample(texture, startY, endY, xx, 1, fillColor, true);
                Color verticalFill = Color.Lerp(top, bottom, Mathf.SmoothStep(0f, 1f, vertical));

                Color blendedFill = Color.Lerp(sideFill, verticalFill, 0.28f);
                Color localFill = SampleLocalChromeBackground(texture, xx, yy, fillColor);
                blendedFill = Color.Lerp(blendedFill, localFill, 0.72f);
                blendedFill.a = Mathf.Max(fillColor.a, Mathf.Max(sideFill.a, verticalFill.a));
                texture.SetPixel(xx, yy, blendedFill);
            }
        }
    }

    private static void FillSolidMaskFromTop(Texture2D texture, RectInt mask, Color fillColor)
    {
        int startX = Mathf.Clamp(mask.x, 0, texture.width);
        int endX = Mathf.Clamp(mask.x + mask.width, 0, texture.width);
        int startY = Mathf.Clamp(texture.height - mask.y - mask.height, 0, texture.height);
        int endY = Mathf.Clamp(texture.height - mask.y, 0, texture.height);

        for (int yy = startY; yy < endY; yy++)
        {
            float vertical = texture.height <= 1 ? 0.5f : yy / (float)(texture.height - 1);
            Color maskedFill = Color.Lerp(
                new Color(fillColor.r * 0.72f, fillColor.g * 0.72f, fillColor.b * 0.72f, fillColor.a),
                fillColor,
                Mathf.SmoothStep(0f, 1f, vertical));
            for (int xx = startX; xx < endX; xx++)
                texture.SetPixel(xx, yy, maskedFill);
        }
    }

    private static Color SampleLocalChromeBackground(Texture2D texture, int centerX, int centerY, Color fallback)
    {
        const int radius = 12;
        Color sum = Color.clear;
        int count = 0;

        for (int yy = Mathf.Max(0, centerY - radius); yy <= Mathf.Min(texture.height - 1, centerY + radius); yy++)
        {
            for (int xx = Mathf.Max(0, centerX - radius); xx <= Mathf.Min(texture.width - 1, centerX + radius); xx++)
            {
                Color sample = texture.GetPixel(xx, yy);
                if (!IsReusableChromeFillSample(sample))
                    continue;

                sum += sample;
                count++;
            }
        }

        if (count < 4)
            return fallback;

        Color averaged = sum / count;
        averaged.a = Mathf.Max(averaged.a, fallback.a);
        return averaged;
    }

    private static Color FindMaskFillSample(Texture2D texture, int maskStart, int maskEnd, int fixedAxis, int direction, Color fallback, bool searchVertically = false)
    {
        const int maxDistance = 36;
        for (int distance = 2; distance <= maxDistance; distance++)
        {
            int sampleVariable = direction < 0 ? maskStart - distance : maskEnd + distance - 1;
            int sampleX = searchVertically ? fixedAxis : sampleVariable;
            int sampleY = searchVertically ? sampleVariable : fixedAxis;
            if (sampleX < 0 || sampleX >= texture.width || sampleY < 0 || sampleY >= texture.height)
                continue;

            Color sample = texture.GetPixel(sampleX, sampleY);
            if (IsReusableChromeFillSample(sample))
                return sample;
        }

        return fallback;
    }

    private static bool IsReusableChromeFillSample(Color sample)
    {
        float maxChannel = Mathf.Max(sample.r, Mathf.Max(sample.g, sample.b));
        float minChannel = Mathf.Min(sample.r, Mathf.Min(sample.g, sample.b));
        float luma = sample.r * 0.299f + sample.g * 0.587f + sample.b * 0.114f;
        float chroma = maxChannel - minChannel;
        return sample.a > 0.20f && luma < 0.26f && chroma < 0.18f;
    }

    private static bool IsMatchHudFramePixel(Color sample)
    {
        if (sample.a <= 0.08f)
            return false;

        float maxChannel = Mathf.Max(sample.r, Mathf.Max(sample.g, sample.b));
        float minChannel = Mathf.Min(sample.r, Mathf.Min(sample.g, sample.b));
        float luma = sample.r * 0.299f + sample.g * 0.587f + sample.b * 0.114f;
        float chroma = maxChannel - minChannel;
        bool cyanChrome = sample.b > 0.22f && sample.g > 0.18f && sample.r < 0.16f && sample.b - sample.r > 0.12f;
        bool darkNeutralChrome = maxChannel > 0.035f && maxChannel < 0.18f && chroma < 0.10f;
        bool neutralChrome = luma > 0.16f && chroma < 0.16f;
        bool paleHighlight = luma > 0.32f && chroma < 0.28f;
        return cyanChrome || darkNeutralChrome || neutralChrome || paleHighlight;
    }

    private static Color NormalizeMatchHudFramePixel(Color sample)
    {
        float maxChannel = Mathf.Max(sample.r, Mathf.Max(sample.g, sample.b));
        float minChannel = Mathf.Min(sample.r, Mathf.Min(sample.g, sample.b));
        float luma = sample.r * 0.299f + sample.g * 0.587f + sample.b * 0.114f;
        bool cyanChrome = sample.b > 0.22f && sample.g > 0.18f && sample.r < 0.16f && sample.b - sample.r > 0.12f;
        if (cyanChrome)
            return new Color(sample.r, sample.g, sample.b, sample.a);

        float intensity = Mathf.Clamp01((luma - 0.05f) / 0.38f);
        Color darkChrome = new Color(0.018f, 0.030f, 0.033f, sample.a);
        Color lightChrome = new Color(0.48f, 0.56f, 0.58f, sample.a);
        Color normalized = Color.Lerp(darkChrome, lightChrome, intensity);
        normalized.a = sample.a;

        if (maxChannel - minChannel > 0.18f)
            normalized.a *= 0.72f;

        return normalized;
    }

    private static void ClearMaskFromTop(Texture2D texture, RectInt mask)
    {
        int startX = Mathf.Clamp(mask.x, 0, texture.width);
        int endX = Mathf.Clamp(mask.x + mask.width, 0, texture.width);
        int startY = Mathf.Clamp(texture.height - mask.y - mask.height, 0, texture.height);
        int endY = Mathf.Clamp(texture.height - mask.y, 0, texture.height);

        for (int yy = startY; yy < endY; yy++)
        {
            for (int xx = startX; xx < endX; xx++)
                texture.SetPixel(xx, yy, Color.clear);
        }
    }

    private static void ApplyAlphaOutsidePolygon(Texture2D texture, Vector2[] opaquePolygon)
    {
        if (opaquePolygon == null || opaquePolygon.Length == 0)
            return;

        for (int yy = 0; yy < texture.height; yy++)
        {
            for (int xx = 0; xx < texture.width; xx++)
            {
                Vector2 point = new Vector2(xx + 0.5f, yy + 0.5f);
                if (IsPointInsideConvexPolygon(point, opaquePolygon))
                    continue;

                texture.SetPixel(xx, yy, Color.clear);
            }
        }
    }

    private static Vector2[] CreateOctagonalChromePolygon(int width, int height, float cornerInset, float edgeInset, float diagonalInset)
    {
        return new[]
        {
            new Vector2(cornerInset, edgeInset),
            new Vector2(width - cornerInset, edgeInset),
            new Vector2(width - edgeInset, diagonalInset),
            new Vector2(width - edgeInset, height - diagonalInset),
            new Vector2(width - cornerInset, height - edgeInset),
            new Vector2(cornerInset, height - edgeInset),
            new Vector2(edgeInset, height - diagonalInset),
            new Vector2(edgeInset, diagonalInset)
        };
    }

    private static Color SampleMaskedCropFill(Texture2D crop, int startX, int endX, int startY, int endY, Color fallback)
    {
        const int margin = 4;
        Color sum = Color.clear;
        int count = 0;
        int minX = Mathf.Clamp(startX - margin, 0, crop.width - 1);
        int maxX = Mathf.Clamp(endX + margin, 0, crop.width);
        int minY = Mathf.Clamp(startY - margin, 0, crop.height - 1);
        int maxY = Mathf.Clamp(endY + margin, 0, crop.height);

        for (int yy = minY; yy < maxY; yy++)
        {
            for (int xx = minX; xx < maxX; xx++)
            {
                bool insideMask = xx >= startX && xx < endX && yy >= startY && yy < endY;
                if (insideMask)
                    continue;

                Color pixel = crop.GetPixel(xx, yy);
                float luma = pixel.r * 0.299f + pixel.g * 0.587f + pixel.b * 0.114f;
                if (pixel.a < 0.2f || luma > 0.34f)
                    continue;

                sum += pixel;
                count++;
            }
        }

        if (count == 0)
            return fallback;

        Color sampled = sum / count;
        sampled.a = Mathf.Max(sampled.a, fallback.a);
        return Color.Lerp(fallback, sampled, 0.76f);
    }

    private static void WriteLumaKeyedCropPng(Texture2D source, string outputPath, int x, int y, int width, int height, float threshold, float softness)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var crop = new Texture2D(width, height, TextureFormat.RGBA32, false);
        Color[] pixels = source.GetPixels(x, y, width, height);

        for (int i = 0; i < pixels.Length; i++)
        {
            Color pixel = pixels[i];
            float luma = pixel.r * 0.299f + pixel.g * 0.587f + pixel.b * 0.114f;
            pixel.a = Mathf.Clamp01((luma - threshold) / Mathf.Max(0.001f, softness));
            pixels[i] = pixel;
        }

        crop.SetPixels(pixels);
        crop.Apply();
        File.WriteAllBytes(outputPath, crop.EncodeToPNG());
        Object.DestroyImmediate(crop);
    }

    private static void WritePlacedArtStripPng(Texture2D source, string outputPath, int stripSourceX, int stripSourceY, int cleanArtSourceX, int cleanArtSourceY, int cleanArtWidth, int cleanArtHeight, int outputWidth, int outputHeight, int cleanArtTop, Color leftFill, Color accentColor)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var strip = new Texture2D(outputWidth, outputHeight, TextureFormat.RGBA32, false);
        int cleanArtOffset = cleanArtSourceX - stripSourceX;
        int cleanArtBottom = outputHeight - cleanArtTop - cleanArtHeight;

        for (int yy = 0; yy < outputHeight; yy++)
        {
            for (int xx = 0; xx < outputWidth; xx++)
            {
                Color pixel = SamplePlacedArtStripPixel(source, stripSourceX, stripSourceY, cleanArtSourceX, cleanArtSourceY, cleanArtWidth, cleanArtHeight, outputHeight, cleanArtOffset, cleanArtBottom, leftFill, xx, yy);
                strip.SetPixel(xx, yy, SuppressBakedArtFrame(source, stripSourceX, stripSourceY, cleanArtSourceX, cleanArtSourceY, cleanArtWidth, cleanArtHeight, outputWidth, outputHeight, cleanArtOffset, cleanArtBottom, leftFill, accentColor, xx, yy, pixel));
            }
        }

        strip.Apply();
        File.WriteAllBytes(outputPath, strip.EncodeToPNG());
        Object.DestroyImmediate(strip);
    }

    private static Color SuppressBakedArtFrame(Texture2D source, int stripSourceX, int stripSourceY, int cleanArtSourceX, int cleanArtSourceY, int cleanArtWidth, int cleanArtHeight, int outputWidth, int outputHeight, int cleanArtOffset, int cleanArtBottom, Color leftFill, Color accentColor, int x, int y, Color pixel)
    {
        const int rightFrameInset = 96;
        const int verticalFrameInset = 36;

        bool nearFrameEdge = x >= outputWidth - rightFrameInset || y < verticalFrameInset || y >= outputHeight - verticalFrameInset;
        if (!nearFrameEdge)
            return pixel;

        float accentDistance = Mathf.Abs(pixel.r - accentColor.r) + Mathf.Abs(pixel.g - accentColor.g) + Mathf.Abs(pixel.b - accentColor.b);
        float accentScore = pixel.a * Mathf.Clamp01(1f - accentDistance / 0.55f);
        bool isQuickCustomAccent = IsQuickCustomAccent(accentColor);
        bool quickCustomFrameTint = isQuickCustomAccent
            && (x >= outputWidth - rightFrameInset || y < verticalFrameInset)
            && pixel.g > pixel.r * 1.08f
            && pixel.g > pixel.b * 1.25f
            && pixel.g > 0.25f;
        if (accentScore < 0.04f && !quickCustomFrameTint)
            return pixel;

        if (isQuickCustomAccent && (quickCustomFrameTint || accentScore >= 0.12f))
        {
            Color quickCustomNeutralPixel = new Color(leftFill.r * 0.58f, leftFill.g * 0.58f, leftFill.b * 0.58f, pixel.a);
            Color scrubbedQuickCustom = Color.Lerp(pixel, quickCustomNeutralPixel, Mathf.Max(0.92f, accentScore));
            scrubbedQuickCustom.a = pixel.a;
            return scrubbedQuickCustom;
        }

        int safeX = x >= outputWidth - rightFrameInset ? outputWidth - rightFrameInset - 1 : x;
        int safeY = y < verticalFrameInset ? verticalFrameInset : y;
        if (safeY >= outputHeight - verticalFrameInset)
            safeY = outputHeight - verticalFrameInset - 1;

        Color innerPixel = SamplePlacedArtStripPixel(source, stripSourceX, stripSourceY, cleanArtSourceX, cleanArtSourceY, cleanArtWidth, cleanArtHeight, outputHeight, cleanArtOffset, cleanArtBottom, leftFill, safeX, safeY);
        float accentBlend = Mathf.SmoothStep(0.04f, 0.28f, accentScore);
        float neutralFillStrength = isQuickCustomAccent ? 0.82f : 0.12f;
        Color neutralPixel = Color.Lerp(innerPixel, new Color(leftFill.r * 0.62f, leftFill.g * 0.62f, leftFill.b * 0.62f, innerPixel.a), neutralFillStrength);
        Color scrubbed = Color.Lerp(pixel, neutralPixel, accentBlend);
        scrubbed.a = Mathf.Max(pixel.a, innerPixel.a);
        return scrubbed;
    }

    private static bool IsQuickCustomAccent(Color accentColor)
    {
        return accentColor.g > 0.75f && accentColor.r > 0.45f && accentColor.b < 0.45f;
    }

    private static Color SamplePlacedArtStripPixel(Texture2D source, int stripSourceX, int stripSourceY, int cleanArtSourceX, int cleanArtSourceY, int cleanArtWidth, int cleanArtHeight, int outputHeight, int cleanArtOffset, int cleanArtBottom, Color leftFill, int x, int y)
    {
        int cleanX = x - cleanArtOffset;
        int cleanY = y - cleanArtBottom;

        if (cleanX < 0)
        {
            float horizontal = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(x / Mathf.Max(1f, cleanArtOffset)));
            Color pixel = Color.Lerp(new Color(leftFill.r * 0.42f, leftFill.g * 0.42f, leftFill.b * 0.42f, 1f), leftFill, horizontal);
            pixel.a = horizontal * 0.88f;
            return pixel;
        }

        if (cleanX >= cleanArtWidth)
        {
            int sampleY = Mathf.Clamp(cleanY, 0, cleanArtHeight - 1);
            Color edgePixel = source.GetPixel(cleanArtSourceX + cleanArtWidth - 1, cleanArtSourceY + sampleY);
            edgePixel.a = 1f;
            return edgePixel;
        }

        if (cleanY < 0 || cleanY >= cleanArtHeight)
        {
            int sampleX = Mathf.Clamp(cleanX, 0, cleanArtWidth - 1);
            int sampleY = Mathf.Clamp(cleanY, 0, cleanArtHeight - 1);
            Color edgePixel = source.GetPixel(cleanArtSourceX + sampleX, cleanArtSourceY + sampleY);
            float verticalDistance = cleanY < 0 ? -cleanY / Mathf.Max(1f, cleanArtBottom) : (cleanY - cleanArtHeight + 1) / Mathf.Max(1f, outputHeight - cleanArtBottom - cleanArtHeight);
            float sourceBlend = Mathf.SmoothStep(0.25f, 1f, Mathf.Clamp01(verticalDistance));
            Color softFill = Color.Lerp(new Color(leftFill.r * 0.55f, leftFill.g * 0.55f, leftFill.b * 0.55f, 1f), leftFill, 0.45f);
            Color pixel = Color.Lerp(edgePixel, softFill, 0.22f * sourceBlend);
            pixel.a = 1f;
            return pixel;
        }

        Color cleanPixel = source.GetPixel(cleanArtSourceX + cleanX, cleanArtSourceY + cleanY);
        if (cleanX < 96)
        {
            float blend = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(cleanX / 96f));
            cleanPixel = Color.Lerp(leftFill, cleanPixel, blend);
        }

        cleanPixel.a = 1f;
        return cleanPixel;
    }

    private static void WritePaddedCropPng(Texture2D source, string outputPath, int x, int y, int cropWidth, int cropHeight, int outputWidth, int outputHeight, Color fillColor)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var output = new Texture2D(outputWidth, outputHeight, TextureFormat.RGBA32, false);
        var fillPixels = new Color[outputWidth * outputHeight];
        for (int i = 0; i < fillPixels.Length; i++)
            fillPixels[i] = fillColor;
        output.SetPixels(fillPixels);

        int targetX = Mathf.Max(0, outputWidth - cropWidth);
        int targetY = Mathf.Max(0, (outputHeight - cropHeight) / 2);
        Color[] cropPixels = source.GetPixels(x, y, cropWidth, cropHeight);
        int fadeWidth = Mathf.Min(180, cropWidth);
        for (int yy = 0; yy < cropHeight; yy++)
        {
            for (int xx = 0; xx < cropWidth; xx++)
            {
                Color sourceColor = cropPixels[yy * cropWidth + xx];
                float fade = fadeWidth <= 1 ? 1f : Mathf.Clamp01(xx / (float)(fadeWidth - 1));
                Color color = Color.Lerp(fillColor, sourceColor, Mathf.SmoothStep(0f, 1f, fade));
                output.SetPixel(targetX + xx, targetY + yy, color);
            }
        }
        output.Apply();
        File.WriteAllBytes(outputPath, output.EncodeToPNG());
        Object.DestroyImmediate(output);
    }

    private static void WriteCardPanelMaskPng(string outputPath, int width, int height, float chamfer)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        float right = width - 1f;
        float top = height - 1f;

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                float distance = Mathf.Min(
                    Mathf.Min(x + y - chamfer, x + (top - y) - chamfer),
                    Mathf.Min((right - x) + y - chamfer, (right - x) + (top - y) - chamfer));
                float alpha = Mathf.Clamp01(distance / 3f);
                texture.SetPixel(x, y, new Color(1f, 1f, 1f, alpha));
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteCardContentMaskPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        var clearPixels = new Color[width * height];
        for (int i = 0; i < clearPixels.Length; i++)
            clearPixels[i] = Color.clear;
        texture.SetPixels(clearPixels);

        Vector2[] innerPath =
        {
            new Vector2(36f, 7f),
            new Vector2(width - 36f, 7f),
            new Vector2(width - 8f, 35f),
            new Vector2(width - 8f, height - 35f),
            new Vector2(width - 36f, height - 8f),
            new Vector2(36f, height - 8f),
            new Vector2(8f, height - 35f),
            new Vector2(8f, 35f)
        };

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                Vector2 point = new Vector2(x + 0.5f, y + 0.5f);
                if (!IsPointInsideConvexPolygon(point, innerPath))
                    continue;

                float nearest = float.MaxValue;
                for (int i = 0; i < innerPath.Length; i++)
                    nearest = Mathf.Min(nearest, DistanceToSegment(point, innerPath[i], innerPath[(i + 1) % innerPath.Length]));

                float alpha = Mathf.Clamp01(nearest / 1.5f);
                texture.SetPixel(x, y, new Color(1f, 1f, 1f, alpha));
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteCardTintMaskPng(string outputPath, int width, int height, float chamfer)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        float top = height - 1f;

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 1f : y / (float)(height - 1);
            float verticalFeather = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(vertical * 8f)) * Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((1f - vertical) * 8f));
            for (int x = 0; x < width; x++)
            {
                float horizontal = width <= 1 ? 0f : x / (float)(width - 1);
                float leftCornerDistance = Mathf.Min(x + y - chamfer, x + (top - y) - chamfer);
                float silhouetteAlpha = Mathf.Clamp01(leftCornerDistance / 3f);
                float alpha = Mathf.SmoothStep(1f, 0f, horizontal) * verticalFeather * silhouetteAlpha;
                texture.SetPixel(x, y, new Color(1f, 1f, 1f, alpha));
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteCardFrameMaskFromTargetPng(Texture2D source, string outputPath, int x, int y, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        var transparent = new Color[width * height];
        for (int i = 0; i < transparent.Length; i++)
            transparent[i] = Color.clear;
        texture.SetPixels(transparent);

        Vector2[] framePath =
        {
            new Vector2(34f, 4f),
            new Vector2(width - 34f, 4f),
            new Vector2(width - 5f, 33f),
            new Vector2(width - 5f, height - 33f),
            new Vector2(width - 34f, height - 5f),
            new Vector2(34f, height - 5f),
            new Vector2(5f, height - 33f),
            new Vector2(5f, 33f)
        };

        for (int yy = 0; yy < height; yy++)
        {
            for (int xx = 0; xx < width; xx++)
            {
                Vector2 point = new Vector2(xx + 0.5f, yy + 0.5f);
                float nearest = float.MaxValue;
                for (int i = 0; i < framePath.Length; i++)
                    nearest = Mathf.Min(nearest, DistanceToSegment(point, framePath[i], framePath[(i + 1) % framePath.Length]));

                float frameBand = Mathf.Clamp01((6.75f - nearest) / 1.75f);
                if (frameBand <= 0f)
                    continue;

                Color sourcePixel = source.GetPixel(x + xx, y + yy);
                float brightest = Mathf.Max(sourcePixel.r, Mathf.Max(sourcePixel.g, sourcePixel.b));
                float darkest = Mathf.Min(sourcePixel.r, Mathf.Min(sourcePixel.g, sourcePixel.b));
                float saturation = brightest - darkest;
                float cyanSignal = Mathf.Min(sourcePixel.g, sourcePixel.b) - sourcePixel.r * 0.85f;
                float cyanGate = Mathf.Clamp01((cyanSignal - 0.075f) / 0.18f);
                float saturationGate = Mathf.Clamp01((saturation - 0.10f) / 0.22f);
                float brightnessGate = Mathf.Clamp01((brightest - 0.20f) / 0.30f);
                float alpha = Mathf.SmoothStep(0f, 1f, cyanGate * saturationGate * brightnessGate) * frameBand;

                if (alpha > 0f)
                    texture.SetPixel(xx, yy, new Color(1f, 1f, 1f, alpha));
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteSliderMaskPng(string outputPath, int width, int height, float radius)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                float alpha = RoundedRectCoverage(x + 0.5f, y + 0.5f, width, height, radius);
                texture.SetPixel(x, y, new Color(1f, 1f, 1f, alpha));
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

