    private static void WriteSettingsToggleHandlePng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        float radius = Mathf.Min(width, height) * 0.5f;

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                float outer = RoundedRectCoverage(x + 0.5f, y + 0.5f, width, height, radius);
                if (outer <= 0f)
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float inner = RoundedRectCoverage(x + 0.5f - 3f, y + 0.5f - 3f, width - 6f, height - 6f, Mathf.Max(1f, radius - 3f));
                float topLight = Mathf.Clamp01((y + 0.5f) / height);
                Color edge = new Color(0.58f, 0.65f, 0.65f, 1f);
                Color body = Color.Lerp(new Color(0.84f, 0.88f, 0.84f, 1f), new Color(0.98f, 1f, 0.97f, 1f), topLight);
                Color color = Color.Lerp(edge, body, inner);
                color.a *= outer;
                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteSettingsRoundedControlPng(string outputPath, int width, int height, float radius, Color body, Color edge, float edgeWidth, bool blueFill)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                float outer = RoundedRectCoverage(x + 0.5f, y + 0.5f, width, height, radius);
                if (outer <= 0f)
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float inner = RoundedRectCoverage(
                    x + 0.5f - edgeWidth,
                    y + 0.5f - edgeWidth,
                    width - edgeWidth * 2f,
                    height - edgeWidth * 2f,
                    Mathf.Max(1f, radius - edgeWidth));
                float vertical = height <= 1 ? 0f : y / (float)(height - 1);
                Color top = blueFill
                    ? new Color(Mathf.Min(body.r * 1.18f, 1f), Mathf.Min(body.g * 1.18f, 1f), Mathf.Min(body.b * 1.18f, 1f), body.a)
                    : new Color(body.r * 0.62f, body.g * 0.72f, body.b * 0.76f, body.a);
                Color fill = Color.Lerp(body, top, Mathf.SmoothStep(0f, 1f, vertical));
                Color color = Color.Lerp(edge, fill, inner);
                color.a *= outer;
                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WritePopupStackButtonPng(string outputPath, int width, int height, bool selected, bool destructive)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        Vector2[] outer = CreateOctagonalChromePolygon(width, height, selected ? 28f : 24f, 3f, selected ? 28f : 24f);
        Vector2[] inner = CreateOctagonalChromePolygon(width, height, selected ? 42f : 36f, 12f, selected ? 42f : 36f);
        Color top = selected
            ? new Color(0.010f, 0.166f, 0.236f, 0.98f)
            : destructive
                ? new Color(0.104f, 0.025f, 0.014f, 0.98f)
                : new Color(0.012f, 0.024f, 0.028f, 0.98f);
        Color bottom = selected
            ? new Color(0.006f, 0.060f, 0.092f, 0.98f)
            : destructive
                ? new Color(0.034f, 0.008f, 0.006f, 0.98f)
                : new Color(0.004f, 0.012f, 0.015f, 0.98f);
        Color outerEdge = selected
            ? new Color(0.04f, 0.78f, 1f, 0.92f)
            : destructive
                ? new Color(1f, 0.28f, 0.20f, 0.84f)
                : new Color(0.56f, 0.62f, 0.64f, 0.76f);
        Color innerEdge = selected
            ? new Color(0.33f, 0.92f, 1f, 0.62f)
            : destructive
                ? new Color(1f, 0.32f, 0.22f, 0.38f)
                : new Color(0.12f, 0.24f, 0.28f, 0.48f);

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            Color fill = Color.Lerp(bottom, top, Mathf.SmoothStep(0f, 1f, vertical));
            for (int x = 0; x < width; x++)
            {
                Vector2 point = new Vector2(x + 0.5f, y + 0.5f);
                if (!IsPointInsideConvexPolygon(point, outer))
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float edgeFade = Mathf.Clamp01(Mathf.Min(
                    Mathf.Min(x, width - 1 - x) / 42f,
                    Mathf.Min(y, height - 1 - y) / 26f));
                Color pixel = Color.Lerp(new Color(fill.r * 0.62f, fill.g * 0.62f, fill.b * 0.62f, fill.a), fill, Mathf.SmoothStep(0f, 1f, edgeFade));
                if (((x + y * 2) % 11) == 0)
                    pixel = Color.Lerp(pixel, new Color(outerEdge.r, outerEdge.g, outerEdge.b, pixel.a), selected ? 0.12f : destructive ? 0.06f : 0.035f);
                texture.SetPixel(x, y, pixel);
            }
        }

        for (int i = 0; i < outer.Length; i++)
            DrawThickLine(texture, outer[i], outer[(i + 1) % outer.Length], selected ? 1.5f : 1.15f, outerEdge);
        for (int i = 0; i < inner.Length; i++)
            DrawThickLine(texture, inner[i], inner[(i + 1) % inner.Length], 0.95f, innerEdge);
        DrawThickLine(texture, new Vector2(42f, height - 8f), new Vector2(width - 42f, height - 8f), 1.05f, new Color(outerEdge.r, outerEdge.g, outerEdge.b, selected ? 0.50f : 0.28f));
        DrawThickLine(texture, new Vector2(42f, 7f), new Vector2(width - 42f, 7f), 0.9f, new Color(innerEdge.r, innerEdge.g, innerEdge.b, destructive ? 0.36f : 0.30f));

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WritePopupInfoRowPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        Vector2[] outer = CreateOctagonalChromePolygon(width, height, 18f, 3f, 18f);
        Vector2[] inner = CreateOctagonalChromePolygon(width, height, 31f, 11f, 31f);
        Color top = new Color(0.012f, 0.030f, 0.034f, 0.98f);
        Color bottom = new Color(0.004f, 0.014f, 0.017f, 0.98f);
        Color outerEdge = new Color(0.48f, 0.56f, 0.58f, 0.70f);
        Color innerEdge = new Color(0.06f, 0.22f, 0.26f, 0.45f);

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            Color fill = Color.Lerp(bottom, top, Mathf.SmoothStep(0f, 1f, vertical));
            for (int x = 0; x < width; x++)
            {
                Vector2 point = new Vector2(x + 0.5f, y + 0.5f);
                if (!IsPointInsideConvexPolygon(point, outer))
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float edgeFade = Mathf.Clamp01(Mathf.Min(
                    Mathf.Min(x, width - 1 - x) / 26f,
                    Mathf.Min(y, height - 1 - y) / 18f));
                texture.SetPixel(x, y, Color.Lerp(new Color(fill.r * 0.66f, fill.g * 0.66f, fill.b * 0.66f, fill.a), fill, Mathf.SmoothStep(0f, 1f, edgeFade)));
            }
        }

        for (int i = 0; i < outer.Length; i++)
            DrawThickLine(texture, outer[i], outer[(i + 1) % outer.Length], 1.05f, outerEdge);
        for (int i = 0; i < inner.Length; i++)
            DrawThickLine(texture, inner[i], inner[(i + 1) % inner.Length], 0.8f, innerEdge);
        DrawThickLine(texture, new Vector2(28f, height - 6f), new Vector2(126f, height - 6f), 1f, new Color(0.04f, 0.78f, 1f, 0.22f));
        DrawThickLine(texture, new Vector2(width - 114f, 6f), new Vector2(width - 36f, 6f), 1f, new Color(0.04f, 0.78f, 1f, 0.18f));

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WritePopupIconPng(string outputPath, string motif, Color color)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        const int width = 128;
        const int height = 128;
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
                texture.SetPixel(x, y, Color.clear);
        }

        Color glow = new Color(color.r, color.g, color.b, 0.22f);
        Vector2 center = new Vector2(width * 0.5f, height * 0.5f);
        if (motif == "play")
        {
            Vector2[] triangle = { new(43f, 31f), new(91f, 64f), new(43f, 97f) };
            DrawFilledPolygon(texture, triangle, glow);
            DrawFilledPolygon(texture, new[] { new Vector2(47f, 37f), new Vector2(84f, 64f), new Vector2(47f, 91f) }, color);
            for (int i = 0; i < triangle.Length; i++)
                DrawThickLine(texture, triangle[i], triangle[(i + 1) % triangle.Length], 2.2f, new Color(0.78f, 0.98f, 1f, 0.92f));
        }
        else if (motif == "restart")
        {
            Vector2 previous = Vector2.zero;
            bool hasPrevious = false;
            for (int i = 0; i <= 42; i++)
            {
                float t = Mathf.Lerp(-0.30f, 1.38f, i / 42f) * Mathf.PI;
                Vector2 point = center + new Vector2(Mathf.Cos(t), Mathf.Sin(t)) * 28f;
                if (hasPrevious)
                    DrawThickLine(texture, previous, point, 4.5f, color);
                previous = point;
                hasPrevious = true;
            }

            DrawThickLine(texture, new Vector2(86f, 70f), new Vector2(97f, 89f), 4.5f, color);
            DrawThickLine(texture, new Vector2(86f, 70f), new Vector2(70f, 82f), 4.5f, color);
        }
        else if (motif == "settings")
        {
            DrawDisc(texture, center, 24f, color);
            DrawDisc(texture, center, 11f, new Color(0.010f, 0.020f, 0.024f, 1f));
            for (int i = 0; i < 8; i++)
            {
                float angle = i * Mathf.PI * 0.25f;
                Vector2 start = center + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * 28f;
                Vector2 end = center + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * 40f;
                DrawThickLine(texture, start, end, 6f, color);
            }
        }
        else if (motif == "help")
        {
            DrawDisc(texture, center, 30f, new Color(color.r, color.g, color.b, 0.18f));
            DrawDisc(texture, center, 27f, new Color(0.006f, 0.018f, 0.021f, 0.96f));
            DrawDisc(texture, center, 23f, new Color(color.r, color.g, color.b, 0.18f));
            DrawThickLine(texture, new Vector2(50f, 47f), new Vector2(64f, 36f), 5f, color);
            DrawThickLine(texture, new Vector2(64f, 36f), new Vector2(79f, 44f), 5f, color);
            DrawThickLine(texture, new Vector2(79f, 44f), new Vector2(69f, 60f), 5f, color);
            DrawThickLine(texture, new Vector2(69f, 60f), new Vector2(64f, 69f), 5f, color);
            DrawDisc(texture, new Vector2(64f, 85f), 5f, color);
        }
        else if (motif == "exit")
        {
            DrawThickLine(texture, new Vector2(43f, 34f), new Vector2(43f, 94f), 5f, color);
            DrawThickLine(texture, new Vector2(43f, 34f), new Vector2(74f, 34f), 5f, color);
            DrawThickLine(texture, new Vector2(43f, 94f), new Vector2(74f, 94f), 5f, color);
            DrawThickLine(texture, new Vector2(63f, 64f), new Vector2(92f, 64f), 5f, color);
            DrawThickLine(texture, new Vector2(92f, 64f), new Vector2(78f, 50f), 5f, color);
            DrawThickLine(texture, new Vector2(92f, 64f), new Vector2(78f, 78f), 5f, color);
        }
        else if (motif == "warning")
        {
            Vector2[] triangle = { new(64f, 98f), new(101f, 24f), new(27f, 24f) };
            DrawFilledPolygon(texture, triangle, new Color(color.r, color.g, color.b, 0.16f));
            for (int i = 0; i < triangle.Length; i++)
                DrawThickLine(texture, triangle[i], triangle[(i + 1) % triangle.Length], 5f, color);
            DrawThickLine(texture, new Vector2(64f, 48f), new Vector2(64f, 72f), 5f, color);
            DrawDisc(texture, new Vector2(64f, 38f), 5f, color);
        }
        else if (motif == "clock")
        {
            DrawDisc(texture, center, 27f, new Color(color.r, color.g, color.b, 0.18f));
            DrawDisc(texture, center, 23f, new Color(0.010f, 0.020f, 0.024f, 0.96f));
            DrawDisc(texture, center, 21f, new Color(color.r, color.g, color.b, 0.16f));
            DrawThickLine(texture, center, new Vector2(64f, 42f), 4.5f, color);
            DrawThickLine(texture, center, new Vector2(80f, 70f), 4.5f, color);
            for (int i = 0; i < 4; i++)
            {
                float angle = i * Mathf.PI * 0.5f;
                Vector2 start = center + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * 18f;
                Vector2 end = center + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * 25f;
                DrawThickLine(texture, start, end, 2.2f, color);
            }
        }
        else if (motif == "pin")
        {
            DrawDisc(texture, new Vector2(64f, 53f), 21f, color);
            DrawDisc(texture, new Vector2(64f, 53f), 9f, new Color(0.010f, 0.020f, 0.024f, 1f));
            DrawFilledPolygon(texture, new[] { new Vector2(48f, 64f), new Vector2(80f, 64f), new Vector2(64f, 104f) }, color);
        }
        else if (motif == "shield")
        {
            Vector2[] shield =
            {
                new(64f, 24f), new(91f, 38f), new(87f, 76f), new(64f, 102f), new(41f, 76f), new(37f, 38f)
            };
            DrawFilledPolygon(texture, shield, new Color(color.r, color.g, color.b, 0.12f));
            for (int i = 0; i < shield.Length; i++)
                DrawThickLine(texture, shield[i], shield[(i + 1) % shield.Length], 4.5f, color);
            DrawDisc(texture, center, 6f, color);
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void DrawFilledPolygon(Texture2D texture, Vector2[] polygon, Color color)
    {
        if (polygon == null || polygon.Length == 0)
            return;

        float minX = polygon[0].x;
        float maxX = polygon[0].x;
        float minY = polygon[0].y;
        float maxY = polygon[0].y;
        foreach (Vector2 point in polygon)
        {
            minX = Mathf.Min(minX, point.x);
            maxX = Mathf.Max(maxX, point.x);
            minY = Mathf.Min(minY, point.y);
            maxY = Mathf.Max(maxY, point.y);
        }

        for (int y = Mathf.FloorToInt(minY); y <= Mathf.CeilToInt(maxY); y++)
        {
            for (int x = Mathf.FloorToInt(minX); x <= Mathf.CeilToInt(maxX); x++)
            {
                if (x < 0 || y < 0 || x >= texture.width || y >= texture.height)
                    continue;

                if (IsPointInsideConvexPolygon(new Vector2(x + 0.5f, y + 0.5f), polygon))
                    texture.SetPixel(x, y, color);
            }
        }
    }

    private static string ResolveProjectRelativeFilePath(string relativePath)
    {
        string projectRoot = Directory.GetParent(Application.dataPath)?.FullName;
        var candidates = new List<string>();
        if (!string.IsNullOrEmpty(projectRoot))
        {
            candidates.Add(Path.Combine(projectRoot, relativePath));
            candidates.Add(Path.GetFullPath(Path.Combine(projectRoot, "..", "WarlineCapture", relativePath)));
        }

        candidates.Add(Path.GetFullPath(relativePath));
        foreach (string candidate in candidates)
        {
            if (File.Exists(candidate))
                return candidate;
        }

        return candidates.Count > 0 ? candidates[0] : relativePath;
    }

    private static string RequireProjectRelativeFile(string relativePath)
    {
        string path = ResolveProjectRelativeFilePath(relativePath);
        if (!File.Exists(path))
            throw new FileNotFoundException($"Missing required project file: {relativePath}", path);

        return path;
    }

    private static void WriteQuickCustomTargetIconPng(string outputPath, int sourceX, int sourceTopY, int sourceWidth, int sourceHeight, string fallbackMotif, Color fallbackColor)
    {
        WriteTargetIconPng(QuickCustomTargetSourcePath, outputPath, sourceX, sourceTopY, sourceWidth, sourceHeight, fallbackMotif, fallbackColor);
    }

    private static void WriteTargetIconPng(string targetSourceRelativePath, string outputPath, int sourceX, int sourceTopY, int sourceWidth, int sourceHeight, string fallbackMotif, Color fallbackColor)
    {
        string targetSourcePath = ResolveProjectRelativeFilePath(targetSourceRelativePath);
        if (!File.Exists(targetSourcePath))
        {
            WriteQuickCustomIconPng(outputPath, fallbackMotif, fallbackColor);
            return;
        }

        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var source = new Texture2D(2, 2, TextureFormat.RGBA32, false);
        source.LoadImage(File.ReadAllBytes(targetSourcePath));

        const int outputSize = 128;
        var texture = new Texture2D(outputSize, outputSize, TextureFormat.RGBA32, false);
        for (int y = 0; y < outputSize; y++)
        {
            for (int x = 0; x < outputSize; x++)
                texture.SetPixel(x, y, Color.clear);
        }

        float scale = Mathf.Min(outputSize / (float)sourceWidth, outputSize / (float)sourceHeight) * 0.92f;
        int targetWidth = Mathf.Max(1, Mathf.RoundToInt(sourceWidth * scale));
        int targetHeight = Mathf.Max(1, Mathf.RoundToInt(sourceHeight * scale));
        int targetX = (outputSize - targetWidth) / 2;
        int targetY = (outputSize - targetHeight) / 2;
        int sourceY = Mathf.Clamp(source.height - sourceTopY - sourceHeight, 0, source.height - sourceHeight);

        for (int y = 0; y < targetHeight; y++)
        {
            float v = targetHeight <= 1 ? 0f : y / (float)(targetHeight - 1);
            int sampleY = sourceY + Mathf.Clamp(Mathf.RoundToInt(v * (sourceHeight - 1)), 0, sourceHeight - 1);
            for (int x = 0; x < targetWidth; x++)
            {
                float u = targetWidth <= 1 ? 0f : x / (float)(targetWidth - 1);
                int sampleX = sourceX + Mathf.Clamp(Mathf.RoundToInt(u * (sourceWidth - 1)), 0, sourceWidth - 1);
                Color pixel = source.GetPixel(sampleX, sampleY);
                float luma = pixel.r * 0.299f + pixel.g * 0.587f + pixel.b * 0.114f;
                float chroma = Mathf.Max(pixel.r, Mathf.Max(pixel.g, pixel.b)) - Mathf.Min(pixel.r, Mathf.Min(pixel.g, pixel.b));
                float maxChannel = Mathf.Max(pixel.r, Mathf.Max(pixel.g, pixel.b));
                float alpha = Mathf.Clamp01((Mathf.Max(luma, chroma * 1.45f) - 0.08f) / 0.16f);
                bool matchesFallbackHue = ColorDistance(pixel, fallbackColor) < 0.76f;
                if (luma < 0.22f && maxChannel < 0.32f)
                    alpha = 0f;
                else if (luma < 0.14f && chroma < 0.20f)
                    alpha = 0f;
                else if (matchesFallbackHue)
                    alpha = Mathf.Max(alpha, Mathf.Clamp01((maxChannel - 0.10f) / 0.16f));
                pixel.a *= alpha;
                texture.SetPixel(targetX + x, targetY + y, pixel);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
        Object.DestroyImmediate(source);
    }

    private static void WriteQuickCustomCheckboxBoxPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        Color fill = new Color(0.012f, 0.028f, 0.032f, 0.94f);
        Color outer = new Color(0.42f, 0.54f, 0.56f, 0.94f);
        Color inner = new Color(0.03f, 0.78f, 1f, 0.36f);
        const float radius = 4f;

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                float outerCoverage = RoundedRectCoverage(x + 0.5f, y + 0.5f, width, height, radius);
                if (outerCoverage <= 0f)
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float innerCoverage = RoundedRectCoverage(x + 0.5f - 4f, y + 0.5f - 4f, width - 8f, height - 8f, Mathf.Max(1f, radius - 2f));
                float lineCoverage = Mathf.Clamp01(outerCoverage - innerCoverage);
                Color color = Color.Lerp(fill, outer, lineCoverage);
                if (x >= 6 && x < width - 6 && y >= 6 && y < height - 6)
                    color = Color.Lerp(color, inner, 0.12f);
                color.a *= Mathf.Max(outerCoverage, lineCoverage);
                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

