    private static void WriteQuickCustomResetIconPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
                texture.SetPixel(x, y, Color.clear);
        }

        Color color = new Color(0.86f, 0.94f, 0.96f, 1f);
        Vector2 center = new Vector2(width * 0.50f, height * 0.50f);
        float radius = Mathf.Min(width, height) * 0.30f;
        Vector2 previous = Vector2.zero;
        const int steps = 54;
        for (int i = 0; i <= steps; i++)
        {
            float angle = Mathf.Lerp(-42f, 258f, i / (float)steps) * Mathf.Deg2Rad;
            Vector2 point = center + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius;
            if (i > 0)
                DrawThickLine(texture, previous, point, 5.2f, color);
            previous = point;
        }

        Vector2 arrowTip = previous;
        DrawThickLine(texture, arrowTip, arrowTip + new Vector2(-17f, 1f), 5.2f, color);
        DrawThickLine(texture, arrowTip, arrowTip + new Vector2(-6f, 16f), 5.2f, color);
        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteSliderFrameMaskPng(string outputPath, int width, int height, float chamfer)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        float inset = 2.25f;

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                float outer = RoundedRectCoverage(x + 0.5f, y + 0.5f, width, height, chamfer);
                float inner = RoundedRectCoverage(x + 0.5f - inset, y + 0.5f - inset, width - inset * 2f, height - inset * 2f, Mathf.Max(1f, chamfer - inset));
                float alpha = Mathf.Clamp01(outer - inner);
                float highlight = (y > height - 5 && x > 28 && x < width - 28) ? 0.28f : 0f;
                texture.SetPixel(x, y, new Color(1f, 1f, 1f, Mathf.Max(alpha, alpha * highlight)));
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static float RoundedRectCoverage(float x, float y, float width, float height, float radius)
    {
        float halfWidth = width * 0.5f;
        float halfHeight = height * 0.5f;
        float clampedRadius = Mathf.Min(radius, Mathf.Min(halfWidth, halfHeight));
        Vector2 p = new Vector2(Mathf.Abs(x - halfWidth), Mathf.Abs(y - halfHeight));
        Vector2 q = p - new Vector2(halfWidth - clampedRadius, halfHeight - clampedRadius);
        float outsideDistance = Vector2.Max(q, Vector2.zero).magnitude;
        float insideDistance = Mathf.Min(Mathf.Max(q.x, q.y), 0f);
        float signedDistance = outsideDistance + insideDistance - clampedRadius;
        return Mathf.Clamp01(0.5f - signedDistance);
    }

    private static bool IsPointInsideConvexPolygon(Vector2 point, Vector2[] polygon)
    {
        float sign = 0f;
        for (int i = 0; i < polygon.Length; i++)
        {
            Vector2 a = polygon[i];
            Vector2 b = polygon[(i + 1) % polygon.Length];
            Vector2 edge = b - a;
            Vector2 toPoint = point - a;
            float cross = edge.x * toPoint.y - edge.y * toPoint.x;
            if (Mathf.Abs(cross) < 0.0001f)
                continue;

            if (Mathf.Abs(sign) < 0.0001f)
                sign = Mathf.Sign(cross);
            else if (Mathf.Sign(cross) != Mathf.Sign(sign))
                return false;
        }

        return true;
    }

    private static float ColorDistance(Color a, Color b)
    {
        return Mathf.Abs(a.r - b.r) + Mathf.Abs(a.g - b.g) + Mathf.Abs(a.b - b.b);
    }

    private static float DistanceToSegment(Vector2 p, Vector2 a, Vector2 b)
    {
        Vector2 ab = b - a;
        float lengthSquared = Vector2.Dot(ab, ab);
        if (lengthSquared <= 0.0001f)
            return Vector2.Distance(p, a);

        float t = Mathf.Clamp01(Vector2.Dot(p - a, ab) / lengthSquared);
        return Vector2.Distance(p, a + ab * t);
    }

    private static void WriteHorizontalGradientPng(string outputPath, int width, int height, Color left, Color right)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        for (int x = 0; x < width; x++)
        {
            float t = width <= 1 ? 1f : x / (float)(width - 1);
            Color color = Color.Lerp(left, right, Mathf.SmoothStep(0f, 1f, t));
            for (int y = 0; y < height; y++)
                texture.SetPixel(x, y, color);
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

