    private static void WriteSlicedPanelPng(string outputPath, int width, int height, Color fill, Color edge, Color accent)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            Color body = Color.Lerp(new Color(fill.r * 0.72f, fill.g * 0.72f, fill.b * 0.72f, fill.a), fill, Mathf.SmoothStep(0f, 1f, vertical));
            for (int x = 0; x < width; x++)
            {
                bool outerEdge = x < 2 || x >= width - 2 || y < 2 || y >= height - 2;
                bool innerEdge = x == 3 || x == width - 4 || y == 3 || y == height - 4;
                bool accentRun = (x < 34 && y >= height - 5) || (x >= width - 34 && y < 5);
                Color color = body;

                if (outerEdge)
                    color = edge;
                else if (innerEdge)
                    color = new Color(edge.r, edge.g, edge.b, edge.a * 0.45f);

                if (accentRun)
                    color = accent;

                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteSettingsDropdownPng(string outputPath, int width, int height, Color fill, Color edge)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        const float bevel = 8f;
        const float inset = 1.35f;
        Color border = new Color(edge.r * 0.92f, edge.g * 0.96f, edge.b, 0.82f);

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            Color body = Color.Lerp(
                new Color(fill.r * 0.62f, fill.g * 0.66f, fill.b * 0.70f, fill.a),
                new Color(Mathf.Min(fill.r * 1.12f, 1f), Mathf.Min(fill.g * 1.10f, 1f), Mathf.Min(fill.b * 1.08f, 1f), fill.a),
                Mathf.SmoothStep(0f, 1f, vertical));

            for (int x = 0; x < width; x++)
            {
                float sampleX = x + 0.5f;
                float sampleY = y + 0.5f;
                float outer = BeveledRectCoverage(sampleX, sampleY, width, height, bevel);
                if (outer <= 0f)
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float inner = BeveledRectCoverage(sampleX - inset, sampleY - inset, width - inset * 2f, height - inset * 2f, Mathf.Max(0f, bevel - inset));
                float stroke = Mathf.Clamp01(outer - inner);
                Color color = Color.Lerp(body, border, Mathf.Clamp01(stroke * 2.2f));
                color.a = Mathf.Max(body.a * inner, border.a * stroke);
                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteSettingsButtonPng(string outputPath, int width, int height, Color fill, Color edge, Color accent, bool selected)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        float bevel = height > 80 ? 16f : height > 60 ? 7f : 5f;
        float inset = selected ? 1.25f : 1.05f;
        Color border = selected
            ? new Color(Mathf.Min(edge.r * 1.10f, 1f), Mathf.Min(edge.g * 1.10f, 1f), Mathf.Min(edge.b * 1.06f, 1f), 0.90f)
            : new Color(edge.r * 0.92f, edge.g * 0.98f, edge.b, 0.72f);
        Color innerLine = selected
            ? new Color(accent.r, accent.g, accent.b, 0.44f)
            : new Color(0.08f, 0.23f, 0.27f, 0.46f);

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            Color low = new Color(fill.r * 0.70f, fill.g * 0.74f, fill.b * 0.78f, fill.a);
            Color high = selected
                ? new Color(Mathf.Min(fill.r * 1.16f, 1f), Mathf.Min(fill.g * 1.12f, 1f), Mathf.Min(fill.b * 1.08f, 1f), fill.a)
                : new Color(Mathf.Min(fill.r * 1.06f, 1f), Mathf.Min(fill.g * 1.06f, 1f), Mathf.Min(fill.b * 1.06f, 1f), fill.a);
            Color body = Color.Lerp(low, high, Mathf.SmoothStep(0f, 1f, vertical));

            for (int x = 0; x < width; x++)
            {
                float sampleX = x + 0.5f;
                float sampleY = y + 0.5f;
                float outer = BeveledRectCoverage(sampleX, sampleY, width, height, bevel);
                if (outer <= 0f)
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float inner = BeveledRectCoverage(sampleX - inset, sampleY - inset, width - inset * 2f, height - inset * 2f, Mathf.Max(0f, bevel - inset));
                float stroke = Mathf.Clamp01(outer - inner);
                float innerAccent = BeveledRectCoverage(sampleX - 4f, sampleY - 4f, width - 8f, height - 8f, Mathf.Max(0f, bevel - 4f));
                float innerStroke = Mathf.Clamp01(inner - innerAccent);
                Color color = Color.Lerp(body, border, Mathf.Clamp01(stroke * 2.1f));
                color = Color.Lerp(color, innerLine, Mathf.Clamp01(innerStroke * 0.9f));
                color.a = Mathf.Max(body.a * inner, border.a * stroke);
                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

