    private static void WriteMatchHudSquadTrayPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        var clearPixels = new Color[width * height];
        for (int i = 0; i < clearPixels.Length; i++)
            clearPixels[i] = Color.clear;
        texture.SetPixels(clearPixels);

        Vector2[] outer = CreateOctagonalChromePolygon(width, height, 18f, 4f, 18f);
        Vector2[] inner = CreateOctagonalChromePolygon(width, height, 36f, 13f, 36f);
        Color outerEdge = new Color(0.46f, 0.54f, 0.57f, 0.76f);
        Color midEdge = new Color(0.11f, 0.22f, 0.25f, 0.58f);
        Color innerEdge = new Color(0.03f, 0.72f, 0.94f, 0.34f);

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                Vector2 point = new Vector2(x + 0.5f, y + 0.5f);
                if (!IsPointInsideConvexPolygon(point, outer) || IsPointInsideConvexPolygon(point, inner))
                    continue;

                float horizontal = width <= 1 ? 0f : x / (float)(width - 1);
                float edgeGlow = Mathf.SmoothStep(0f, 1f, Mathf.Min(horizontal, 1f - horizontal) * 5f);
                Color pixel = Color.Lerp(outerEdge, midEdge, edgeGlow);
                texture.SetPixel(x, y, pixel);
            }
        }

        for (int i = 0; i < outer.Length; i++)
            DrawThickLine(texture, outer[i], outer[(i + 1) % outer.Length], 1.2f, outerEdge);
        for (int i = 0; i < inner.Length; i++)
            DrawThickLine(texture, inner[i], inner[(i + 1) % inner.Length], 1f, innerEdge);
        DrawThickLine(texture, new Vector2(44f, height - 7f), new Vector2(156f, height - 7f), 1.1f, new Color(0.02f, 0.70f, 0.92f, 0.50f));
        DrawThickLine(texture, new Vector2(width - 160f, 7f), new Vector2(width - 52f, 7f), 1.1f, new Color(0.02f, 0.70f, 0.92f, 0.32f));

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

