    private static void WriteMatchHudThreatAlertPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        var clearPixels = new Color[width * height];
        for (int i = 0; i < clearPixels.Length; i++)
            clearPixels[i] = Color.clear;
        texture.SetPixels(clearPixels);

        Vector2[] outer =
        {
            new(12f, 2f),
            new(width - 14f, 2f),
            new(width - 3f, height * 0.50f),
            new(width - 14f, height - 3f),
            new(12f, height - 3f),
            new(3f, height * 0.50f)
        };

        Color top = new Color(0.65f, 0.26f, 0.015f, 0.92f);
        Color bottom = new Color(0.28f, 0.075f, 0.010f, 0.92f);
        Color border = new Color(1f, 0.58f, 0.08f, 0.90f);
        Color inner = new Color(1f, 0.78f, 0.10f, 0.26f);

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            Color fill = Color.Lerp(bottom, top, Mathf.SmoothStep(0f, 1f, vertical));
            for (int x = 0; x < width; x++)
            {
                Vector2 point = new Vector2(x + 0.5f, y + 0.5f);
                if (!IsPointInsideConvexPolygon(point, outer))
                    continue;

                float center = 1f - Mathf.Abs(x / (float)(width - 1) - 0.5f) * 2f;
                texture.SetPixel(x, y, Color.Lerp(fill, new Color(0.84f, 0.35f, 0.02f, fill.a), center * 0.08f));
            }
        }

        for (int i = 0; i < outer.Length; i++)
            DrawThickLine(texture, outer[i], outer[(i + 1) % outer.Length], 1.2f, border);
        DrawThickLine(texture, new Vector2(24f, height - 7f), new Vector2(width - 24f, height - 7f), 1f, inner);

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

