    private static void WriteMatchHudSquadSelectionBorderPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        const float bevel = 24f;
        const float strokeWidth = 3.75f;
        Color cyan = new Color(0.02f, 0.76f, 1f, 0.96f);
        Color glow = new Color(0.02f, 0.76f, 1f, 0.20f);

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                float sampleX = x + 0.5f;
                float sampleY = y + 0.5f;
                float outer = BeveledRectCoverage(sampleX, sampleY, width, height, bevel);
                if (outer <= 0f)
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float inner = BeveledRectCoverage(
                    sampleX - strokeWidth,
                    sampleY - strokeWidth,
                    width - strokeWidth * 2f,
                    height - strokeWidth * 2f,
                    bevel - strokeWidth);
                float haloInner = BeveledRectCoverage(
                    sampleX - 8f,
                    sampleY - 8f,
                    width - 16f,
                    height - 16f,
                    bevel - 8f);
                float stroke = Mathf.Clamp01(outer - inner);
                float halo = Mathf.Clamp01(inner - haloInner);
                Color color = Color.Lerp(glow, cyan, Mathf.Clamp01(stroke * 2.6f));
                color.a = Mathf.Max(stroke * cyan.a, halo * glow.a);
                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteMatchHudPortraitFallbackPng(string outputPath, string motif)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        const int width = 136;
        const int height = 112;
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        for (int y = 0; y < height; y++)
        {
            float vertical = y / (float)(height - 1);
            for (int x = 0; x < width; x++)
            {
                float horizontal = x / (float)(width - 1);
                Color color = Color.Lerp(
                    new Color(0.030f, 0.045f, 0.045f, 1f),
                    new Color(0.120f, 0.150f, 0.140f, 1f),
                    vertical * 0.75f + horizontal * 0.12f);
                texture.SetPixel(x, y, color);
            }
        }

        Color line = new Color(0.48f, 0.62f, 0.64f, 0.55f);
        DrawThickLine(texture, new Vector2(24f, 78f), new Vector2(112f, 48f), 4f, line);
        DrawThickLine(texture, new Vector2(32f, 36f), new Vector2(108f, 74f), 3f, line);
        DrawDisc(texture, new Vector2(width * 0.50f, height * 0.48f), motif == "rifle" ? 28f : 24f, new Color(0.12f, 0.20f, 0.20f, 0.78f));
        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

