                float angle = i * Mathf.PI * 0.25f;
                Vector2 start = c + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * 24f;
                Vector2 end = c + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * 34f;
