        }

        texture.Apply();
        var output = new Texture2D(outputWidth, outputHeight, TextureFormat.RGBA32, false);
        for (int y = 0; y < outputHeight; y++)
        {
            int sampleY = Mathf.Clamp(Mathf.RoundToInt(y / (float)(outputHeight - 1) * (height - 1)), 0, height - 1);
