            }
        }

        output.Apply();
        File.WriteAllBytes(outputPath, output.EncodeToPNG());
        Object.DestroyImmediate(output);
        Object.DestroyImmediate(texture);
    }

    private static void WriteMatchHudTargetIconPng(string outputPath, int sourceX, int sourceTopY, int sourceWidth, int sourceHeight, string fallbackMotif, Color fallbackColor)
    {
        string targetSourcePath = ResolveProjectRelativeFilePath(MatchHudTargetSourcePath);
        if (!File.Exists(targetSourcePath))
        {
            WriteMatchHudCommandIconPng(outputPath, fallbackMotif, fallbackColor);
            return;
        }

        WriteTargetIconPng(MatchHudTargetSourcePath, outputPath, sourceX, sourceTopY, sourceWidth, sourceHeight, fallbackMotif, fallbackColor);
    }

    private static void WriteMatchHudResourceBarFromTargetPng(Texture2D source, string outputPath, int sourceX, int sourceY, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);

        Vector2[] outer =
        {
            new(20f, 2f),
            new(width - 24f, 2f),
            new(width - 3f, 20f),
            new(width - 3f, height - 21f),
            new(width - 25f, height - 3f),
            new(20f, height - 3f),
            new(3f, height - 21f),
            new(3f, 20f)
        };

        Vector2[] inner =
        {
            new(26f, 8f),
            new(width - 30f, 8f),
            new(width - 10f, 24f),
            new(width - 10f, height - 25f),
            new(width - 31f, height - 9f),
            new(26f, height - 9f),
            new(10f, height - 25f),
            new(10f, 24f)
        };

        Color fillTop = new Color(0.010f, 0.021f, 0.025f, 0.985f);
        Color fillBottom = new Color(0.004f, 0.009f, 0.011f, 0.985f);
        RectInt[] contentMasks =
        {
            new(18, 10, 118, 42),
            new(176, 10, 124, 42),
            new(338, 10, 138, 42),
            new(490, 10, 136, 42)
        };

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            Color fill = Color.Lerp(fillBottom, fillTop, Mathf.SmoothStep(0f, 1f, vertical));
            for (int x = 0; x < width; x++)
            {
                Vector2 point = new Vector2(x + 0.5f, y + 0.5f);
                if (!IsPointInsideConvexPolygon(point, outer))
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                int sampleX = Mathf.Clamp(sourceX + x, 0, source.width - 1);
                int sampleY = Mathf.Clamp(sourceY + y, 0, source.height - 1);
                Color sourcePixel = source.GetPixel(sampleX, sampleY);
                RectInt contentMask = default;
                bool dynamicContentPixel = false;
                foreach (RectInt mask in contentMasks)
                {
                    if (mask.Contains(new Vector2Int(x, height - 1 - y)))
                    {
                        contentMask = mask;
                        dynamicContentPixel = true;
                        break;
                    }
                }

                if (dynamicContentPixel && IsPointInsideConvexPolygon(point, inner))
                {
                    float centerGlow = 1f - Mathf.Abs((x / (float)(width - 1)) - 0.5f) * 2f;
                    Color sampledFill;
                    if (contentMask.xMin >= 490)
                    {
                        sampledFill = source.GetPixel(Mathf.Clamp(sourceX + 573, 0, source.width - 1), sampleY);
                    }
                    else
                    {
                        int leftSampleX = Mathf.Clamp(sourceX + contentMask.xMin - 1, 0, source.width - 1);
                        int rightSampleX = Mathf.Clamp(sourceX + contentMask.xMax, 0, source.width - 1);
                        float horizontal = contentMask.width <= 1 ? 0f : (x - contentMask.xMin) / (float)(contentMask.width - 1);
                        Color leftFill = source.GetPixel(leftSampleX, sampleY);
                        Color rightFill = source.GetPixel(rightSampleX, sampleY);
                        sampledFill = Color.Lerp(leftFill, rightFill, Mathf.SmoothStep(0f, 1f, horizontal));
                    }
                    Color generatedFill = Color.Lerp(fill, new Color(0.03f, 0.06f, 0.07f, fill.a), centerGlow * 0.05f);
                    Color replacement = Color.Lerp(sampledFill, generatedFill, 0.05f);
                    int topY = height - 1 - y;
                    int edgeDistance = Mathf.Min(
                        Mathf.Min(x - contentMask.xMin, contentMask.xMax - 1 - x),
                        Mathf.Min(topY - contentMask.yMin, contentMask.yMax - 1 - topY));
                    float replaceStrength = Mathf.Clamp01(edgeDistance / 3f);
                    sourcePixel = Color.Lerp(sourcePixel, replacement, replaceStrength);
                }

                texture.SetPixel(x, y, sourcePixel);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteMatchHudResourceBarPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        var clearPixels = new Color[width * height];
        for (int i = 0; i < clearPixels.Length; i++)
            clearPixels[i] = Color.clear;
        texture.SetPixels(clearPixels);

        Vector2[] outer =
        {
            new(20f, 2f),
            new(width - 24f, 2f),
            new(width - 3f, 20f),
            new(width - 3f, height - 21f),
            new(width - 25f, height - 3f),
            new(20f, height - 3f),
            new(3f, height - 21f),
            new(3f, 20f)
        };

        Vector2[] inner =
        {
            new(26f, 8f),
            new(width - 30f, 8f),
            new(width - 10f, 24f),
            new(width - 10f, height - 25f),
            new(width - 31f, height - 9f),
            new(26f, height - 9f),
            new(10f, height - 25f),
            new(10f, 24f)
        };

        Color outerEdge = new Color(0.48f, 0.56f, 0.59f, 0.88f);
        Color midEdge = new Color(0.24f, 0.34f, 0.38f, 0.84f);
        Color innerEdge = new Color(0.07f, 0.14f, 0.17f, 0.92f);
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                Vector2 point = new Vector2(x + 0.5f, y + 0.5f);
                if (!IsPointInsideConvexPolygon(point, outer))
                    continue;

                bool insideInner = IsPointInsideConvexPolygon(point, inner);
                if (insideInner)
                    continue;

                Color pixel = Color.Lerp(outerEdge, midEdge, 0.42f);
                float centerGlow = 1f - Mathf.Abs((x / (float)(width - 1)) - 0.5f) * 2f;
                pixel = Color.Lerp(pixel, new Color(0.03f, 0.06f, 0.07f, pixel.a), centerGlow * 0.06f);
                texture.SetPixel(x, y, pixel);
            }
        }

        for (int i = 0; i < outer.Length; i++)
            DrawThickLine(texture, outer[i], outer[(i + 1) % outer.Length], 1.2f, outerEdge);
        for (int i = 0; i < inner.Length; i++)
            DrawThickLine(texture, inner[i], inner[(i + 1) % inner.Length], 1f, innerEdge);

        DrawThickLine(texture, new Vector2(40f, height - 6f), new Vector2(118f, height - 6f), 1.15f, new Color(0.04f, 0.78f, 1f, 0.34f));
        DrawThickLine(texture, new Vector2(width - 130f, 6f), new Vector2(width - 48f, 6f), 1.15f, new Color(0.04f, 0.78f, 1f, 0.30f));

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteQuickCustomLaunchButtonPng(string outputPath, int width, int height)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        const float bevel = 24f;
        Color outerGold = new Color(1f, 0.76f, 0.12f, 1f);
        Color innerGold = new Color(1f, 0.94f, 0.28f, 0.92f);

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            Color body = Color.Lerp(
                new Color(0.64f, 0.29f, 0.00f, 0.98f),
                new Color(1f, 0.61f, 0.02f, 0.99f),
                Mathf.SmoothStep(0f, 1f, vertical));

            for (int x = 0; x < width; x++)
            {
                float sampleX = x + 0.5f;
                float sampleY = y + 0.5f;
                float outer = BeveledRectCoverage(sampleX, sampleY, width, height, bevel);
                if (outer <= 0f)
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float inner = BeveledRectCoverage(sampleX - 4f, sampleY - 4f, width - 8f, height - 8f, bevel - 4f);
                float highlight = BeveledRectCoverage(sampleX - 11f, sampleY - 11f, width - 22f, height - 22f, bevel - 11f);
                float stroke = Mathf.Clamp01(outer - inner);
                float innerStroke = Mathf.Clamp01(inner - highlight);
                Color color = Color.Lerp(body, outerGold, Mathf.Clamp01(stroke * 1.4f));
                color = Color.Lerp(color, innerGold, Mathf.Clamp01(innerStroke * 0.95f));
                color.a = Mathf.Max(body.a * inner, outerGold.a * stroke);
                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteQuickCustomLaunchButtonFromTarget(string outputPath, int width, int height, string targetSourcePath)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var source = new Texture2D(2, 2, TextureFormat.RGBA32, false);
        source.LoadImage(File.ReadAllBytes(targetSourcePath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);

        const int sourceX = 1038;
        const int sourceTopY = 756;
        const int sourceWidth = 584;
        const int sourceHeight = 106;
        int sourceY = source.height - sourceTopY - sourceHeight;

        for (int y = 0; y < height; y++)
        {
            float v = height <= 1 ? 0f : y / (float)(height - 1);
            int sampleY = sourceY + Mathf.Clamp(Mathf.RoundToInt(v * (sourceHeight - 1)), 0, sourceHeight - 1);
            for (int x = 0; x < width; x++)
            {
                float u = width <= 1 ? 0f : x / (float)(width - 1);
                int sampleX = sourceX + Mathf.Clamp(Mathf.RoundToInt(u * (sourceWidth - 1)), 0, sourceWidth - 1);
                texture.SetPixel(x, y, source.GetPixel(sampleX, sampleY));
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
        Object.DestroyImmediate(source);
    }

    private static void WriteQuickCustomLaunchArrowPng(string outputPath, int width, int height, float direction)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
                texture.SetPixel(x, y, Color.clear);
        }

        float centerX = direction > 0f ? width * 0.40f : width * 0.60f;
        DrawLaunchChevrons(texture, centerX, height * 0.50f, direction, new Color(0.50f, 0.22f, 0.00f, 0.78f));
        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void DrawLaunchChevrons(Texture2D texture, float centerX, float centerY, float direction, Color color)
    {
        for (int i = 0; i < 2; i++)
        {
            float offset = i * 22f * direction;
            Vector2 mid = new Vector2(centerX + offset, centerY);
            DrawThickLine(texture, new Vector2(mid.x + 13f * direction, mid.y - 17f), mid, 5f, color);
            DrawThickLine(texture, mid, new Vector2(mid.x + 13f * direction, mid.y + 17f), 5f, color);
        }
    }

    private static float BeveledRectCoverage(float x, float y, float width, float height, float bevel)
    {
        float coverage = 0f;
        coverage += IsInsideBeveledRectSample(x - 0.25f, y - 0.25f, width, height, bevel) ? 0.25f : 0f;
        coverage += IsInsideBeveledRectSample(x + 0.25f, y - 0.25f, width, height, bevel) ? 0.25f : 0f;
        coverage += IsInsideBeveledRectSample(x - 0.25f, y + 0.25f, width, height, bevel) ? 0.25f : 0f;
        coverage += IsInsideBeveledRectSample(x + 0.25f, y + 0.25f, width, height, bevel) ? 0.25f : 0f;
        return coverage;
    }

    private static bool IsInsideBeveledRectSample(float x, float y, float width, float height, float bevel)
    {
        if (x < 0f || y < 0f || x >= width || y >= height)
            return false;

        float right = width - x;
        float top = height - y;
        float safeBevel = Mathf.Max(0f, bevel);
        if (x < safeBevel && y < safeBevel && x + y < safeBevel)
            return false;
        if (right < safeBevel && y < safeBevel && right + y < safeBevel)
            return false;
        if (x < safeBevel && top < safeBevel && x + top < safeBevel)
            return false;
        if (right < safeBevel && top < safeBevel && right + top < safeBevel)
            return false;

        return true;
    }

