        }

        DrawThickLine(texture, new Vector2(width * 0.22f, height * 0.66f), new Vector2(width * 0.50f, height * 0.34f), 3.4f, color);
        DrawThickLine(texture, new Vector2(width * 0.50f, height * 0.34f), new Vector2(width * 0.78f, height * 0.66f), 3.4f, color);
        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static void WriteSettingsPanelPng(string outputPath, int width, int height, Color fill, Color edge, Color accent)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
        int bevel = height <= 70 ? 14 : height <= 120 ? 22 : width > 1000 ? 34 : 24;
        int border = height <= 70 ? 3 : 2;
        int innerInset = height <= 70 ? 7 : 9;
        bool selectedTone = fill.b > 0.20f && fill.g > 0.20f;
        Color cornerAccent = selectedTone ? accent : Color.Lerp(edge, accent, 0.28f);

        for (int y = 0; y < height; y++)
        {
            float vertical = height <= 1 ? 0f : y / (float)(height - 1);
            for (int x = 0; x < width; x++)
            {
                if (!IsInsideBeveledRect(x, y, width, height, bevel))
                {
                    texture.SetPixel(x, y, Color.clear);
                    continue;
                }

                float horizontal = width <= 1 ? 0f : x / (float)(width - 1);
                float centerGlow = 1f - Mathf.Abs(horizontal - 0.5f) * 2f;
                Color low = new Color(fill.r * 0.58f, fill.g * 0.58f, fill.b * 0.58f, fill.a);
                Color high = selectedTone
                    ? new Color(Mathf.Min(fill.r * 1.14f, 1f), Mathf.Min(fill.g * 1.16f, 1f), Mathf.Min(fill.b * 1.20f, 1f), fill.a)
                    : fill;
                Color color = Color.Lerp(low, high, Mathf.SmoothStep(0f, 1f, vertical));
                color = Color.Lerp(color, new Color(edge.r, edge.g, edge.b, color.a), centerGlow * (selectedTone ? 0.10f : 0.04f));

                bool outerStroke = !IsInsideBeveledRect(x - border, y - border, width - border * 2, height - border * 2, Mathf.Max(0, bevel - border));
                bool innerStroke = IsBeveledRectInsetStroke(x, y, width, height, bevel, innerInset, 1);
                bool topLeftAccent = (x >= bevel && x < bevel + Mathf.Clamp(width / 8, 42, 170) && y >= height - border - 2)
                    || (x < border + 2 && y <= height - bevel && y > height - bevel - Mathf.Clamp(height / 3, 20, 72));
                bool bottomRightAccent = (x < width - bevel && x >= width - bevel - Mathf.Clamp(width / 9, 38, 150) && y < border + 2)
                    || (x >= width - border - 2 && y >= bevel && y < bevel + Mathf.Clamp(height / 3, 20, 72));

                if (outerStroke)
                    color = edge;
                else if (innerStroke)
                    color = new Color(edge.r, edge.g, edge.b, edge.a * 0.48f);

                if (topLeftAccent || bottomRightAccent)
                    color = cornerAccent;

                texture.SetPixel(x, y, color);
            }
        }

        texture.Apply();
        File.WriteAllBytes(outputPath, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);
    }

    private static bool IsInsideBeveledRect(int x, int y, int width, int height, int bevel)
    {
        if (x < 0 || y < 0 || x >= width || y >= height)
            return false;

        int right = width - 1 - x;
        int top = height - 1 - y;
        int safeBevel = Mathf.Max(0, bevel);
        return x + y >= safeBevel
            && right + y >= safeBevel
            && x + top >= safeBevel
            && right + top >= safeBevel;
    }

    private static bool IsBeveledRectInsetStroke(int x, int y, int width, int height, int bevel, int inset, int thickness)
    {
        int innerWidth = width - inset * 2;
        int innerHeight = height - inset * 2;
        if (innerWidth <= 0 || innerHeight <= 0)
            return false;

        bool insideOuterLine = IsInsideBeveledRect(x - inset, y - inset, innerWidth, innerHeight, Mathf.Max(0, bevel - inset));
        bool insideInnerLine = IsInsideBeveledRect(
            x - inset - thickness,
            y - inset - thickness,
            innerWidth - thickness * 2,
            innerHeight - thickness * 2,
            Mathf.Max(0, bevel - inset - thickness));
        return insideOuterLine && !insideInnerLine;
    }

