    private static void WriteQuickCustomMapPreviewPng(string outputPath)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
        const int outputWidth = 740;
        const int outputHeight = 688;
        var output = new Texture2D(outputWidth, outputHeight, TextureFormat.RGBA32, false);

        string targetSourcePath = ResolveProjectRelativeFilePath(QuickCustomTargetSourcePath);
        if (File.Exists(targetSourcePath))
        {
            var source = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            source.LoadImage(File.ReadAllBytes(targetSourcePath));
            const int sourceX = 1220;
            const int sourceTopY = 194;
            const int sourceWidth = 382;
            const int sourceHeight = 340;
            int sourceY = source.height - sourceTopY - sourceHeight;

            for (int y = 0; y < outputHeight; y++)
            {
                int srcY = sourceY + Mathf.Clamp(Mathf.RoundToInt(y / (float)(outputHeight - 1) * (sourceHeight - 1)), 0, sourceHeight - 1);
                for (int x = 0; x < outputWidth; x++)
                {
                    int srcX = sourceX + Mathf.Clamp(Mathf.RoundToInt(x / (float)(outputWidth - 1) * (sourceWidth - 1)), 0, sourceWidth - 1);
                    output.SetPixel(x, y, source.GetPixel(srcX, srcY));
                }
            }

            Object.DestroyImmediate(source);
        }
        else if (File.Exists(outputPath))
        {
            Object.DestroyImmediate(output);
            return;
        }
        else
        {
            for (int y = 0; y < outputHeight; y++)
            {
                float vertical = y / (float)(outputHeight - 1);
                for (int x = 0; x < outputWidth; x++)
                {
                    float horizontal = x / (float)(outputWidth - 1);
                    Color sand = Color.Lerp(new Color(0.45f, 0.34f, 0.22f, 1f), new Color(0.77f, 0.66f, 0.48f, 1f), vertical);
                    Color city = Color.Lerp(sand, new Color(0.16f, 0.23f, 0.25f, 1f), Mathf.PerlinNoise(horizontal * 9f, vertical * 6f) * 0.45f);
                    output.SetPixel(x, y, city);
                }
            }
        }

        output.Apply();
        File.WriteAllBytes(outputPath, output.EncodeToPNG());
        Object.DestroyImmediate(output);
    }

