    private static void DrawThickLine(Texture2D texture, Vector2 start, Vector2 end, float radius, Color color)
    {
        float distance = Vector2.Distance(start, end);
        int steps = Mathf.Max(1, Mathf.CeilToInt(distance * 2f));
        for (int i = 0; i <= steps; i++)
        {
            Vector2 point = Vector2.Lerp(start, end, i / (float)steps);
            DrawDisc(texture, point, radius, color);
        }
    }

    private static void DrawDisc(Texture2D texture, Vector2 center, float radius, Color color)
    {
        int minX = Mathf.FloorToInt(center.x - radius);
        int maxX = Mathf.CeilToInt(center.x + radius);
        int minY = Mathf.FloorToInt(center.y - radius);
        int maxY = Mathf.CeilToInt(center.y + radius);
        float radiusSquared = radius * radius;

        for (int y = minY; y <= maxY; y++)
        {
            for (int x = minX; x <= maxX; x++)
            {
                if (x < 0 || y < 0 || x >= texture.width || y >= texture.height)
                    continue;

                Vector2 delta = new Vector2(x + 0.5f, y + 0.5f) - center;
                if (delta.sqrMagnitude <= radiusSquared)
                    texture.SetPixel(x, y, color);
            }
        }
    }

    private static void SetGraphicsAlpha(GameObject root, float alpha)
    {
        foreach (Graphic graphic in root.GetComponentsInChildren<Graphic>(true))
        {
            Color color = graphic.color;
            color.a = alpha;
            graphic.color = color;
        }
    }

    private static void OptimizeGeneratedUiRaycastTargets(GameObject root)
    {
        var interactiveGraphics = new HashSet<Graphic>();
        foreach (Selectable selectable in root.GetComponentsInChildren<Selectable>(true))
        {
            if (selectable.targetGraphic != null)
                interactiveGraphics.Add(selectable.targetGraphic);
        }

        foreach (ScrollRect scrollRect in root.GetComponentsInChildren<ScrollRect>(true))
        {
            Graphic scrollGraphic = scrollRect.GetComponent<Graphic>();
            if (scrollGraphic != null)
                interactiveGraphics.Add(scrollGraphic);

            if (scrollRect.viewport != null)
            {
                Graphic viewportGraphic = scrollRect.viewport.GetComponent<Graphic>();
                if (viewportGraphic != null)
                    interactiveGraphics.Add(viewportGraphic);
            }
        }

        foreach (Graphic graphic in root.GetComponentsInChildren<Graphic>(true))
            graphic.raycastTarget = interactiveGraphics.Contains(graphic) || IsRaycastBlockingGraphic(graphic);
    }

    private static bool IsRaycastBlockingGraphic(Graphic graphic)
    {
        return string.Equals(graphic.name, "Scrim", System.StringComparison.OrdinalIgnoreCase);
    }

    private static void EnsureSpriteImport(string path, string atlasLabel = null)
    {
        var importer = AssetImporter.GetAtPath(path) as TextureImporter;
        if (importer == null)
            return;

        bool changed = false;
        changed |= ConfigureUiSpriteImporter(importer);

        if (changed)
            importer.SaveAndReimport();

        EnsureAssetLabels(path, atlasLabel);
    }

    private static void EnsureSlicedSpriteImport(string path, Vector4 border)
    {
        var importer = AssetImporter.GetAtPath(path) as TextureImporter;
        if (importer == null)
            return;

        bool changed = false;
        changed |= ConfigureUiSpriteImporter(importer);

        if (importer.spriteBorder != border)
        {
            importer.spriteBorder = border;
            changed = true;
        }

        if (changed)
            importer.SaveAndReimport();
    }

    private static bool ConfigureUiSpriteImporter(TextureImporter importer)
    {
        bool changed = false;
        if (importer.textureType != TextureImporterType.Sprite)
        {
            importer.textureType = TextureImporterType.Sprite;
            changed = true;
        }

        if (importer.spriteImportMode != SpriteImportMode.Single)
        {
            importer.spriteImportMode = SpriteImportMode.Single;
            changed = true;
        }

        if (importer.mipmapEnabled)
        {
            importer.mipmapEnabled = false;
            changed = true;
        }

        if (!importer.alphaIsTransparency)
        {
            importer.alphaIsTransparency = true;
            changed = true;
        }

        if (importer.wrapMode != TextureWrapMode.Clamp)
        {
            importer.wrapMode = TextureWrapMode.Clamp;
            changed = true;
        }

        if (importer.filterMode != FilterMode.Bilinear)
        {
            importer.filterMode = FilterMode.Bilinear;
            changed = true;
        }

        if (importer.spritePixelsPerUnit != 100f)
        {
            importer.spritePixelsPerUnit = 100f;
            changed = true;
        }

        changed |= EnsureTexturePlatformSettings(importer, "DefaultTexturePlatform", false, 2048, TextureImporterFormat.Automatic);
        changed |= EnsureTexturePlatformSettings(importer, "Android", true, 2048, TextureImporterFormat.ASTC_6x6);
        return changed;
    }

    private static bool EnsureTexturePlatformSettings(TextureImporter importer, string platformName, bool overridden, int maxTextureSize, TextureImporterFormat format)
    {
        TextureImporterPlatformSettings settings = importer.GetPlatformTextureSettings(platformName);
        bool changed = settings.overridden != overridden
            || settings.maxTextureSize != maxTextureSize
            || settings.format != format
            || settings.compressionQuality != 50;

        if (!changed)
            return false;

        settings.name = platformName;
        settings.overridden = overridden;
        settings.maxTextureSize = maxTextureSize;
        settings.format = format;
        settings.compressionQuality = 50;
        importer.SetPlatformTextureSettings(settings);
        return true;
    }

    private static void EnsureAssetLabels(string path, string atlasLabel)
    {
        Object asset = AssetDatabase.LoadMainAssetAtPath(path);
        if (asset == null)
            return;

        var labels = new List<string>(AssetDatabase.GetLabels(asset));
        bool changed = AddLabelIfMissing(labels, "WarlineCaptureUI");
        if (!string.IsNullOrEmpty(atlasLabel))
            changed |= AddLabelIfMissing(labels, atlasLabel);

        if (changed)
            AssetDatabase.SetLabels(asset, labels.ToArray());
    }

    private static bool AddLabelIfMissing(List<string> labels, string label)
    {
        if (labels.Contains(label))
            return false;

        labels.Add(label);
        return true;
    }

    private static void EnsureTextureReadable(string path)
    {
        var importer = AssetImporter.GetAtPath(path) as TextureImporter;
        if (importer == null || importer.isReadable)
            return;

        importer.isReadable = true;
        importer.SaveAndReimport();
    }

    private static GameObject CreateRectObject(string name, Transform parent)
    {
        var gameObject = new GameObject(name, typeof(RectTransform));
        if (parent != null)
            gameObject.transform.SetParent(parent, false);

        Stretch((RectTransform)gameObject.transform);
        return gameObject;
    }

    private static void SetSize(GameObject gameObject, float width, float height)
    {
        RectTransform rectTransform = (RectTransform)gameObject.transform;
        rectTransform.sizeDelta = new Vector2(width, height);
    }

    private static void Stretch(RectTransform rectTransform)
    {
        rectTransform.anchorMin = Vector2.zero;
        rectTransform.anchorMax = Vector2.one;
        rectTransform.offsetMin = Vector2.zero;
        rectTransform.offsetMax = Vector2.zero;
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureVerticalBand(RectTransform rectTransform, float anchorMinY, float anchorMaxY)
    {
        rectTransform.anchorMin = new Vector2(0f, anchorMinY);
        rectTransform.anchorMax = new Vector2(1f, anchorMaxY);
        rectTransform.offsetMin = Vector2.zero;
        rectTransform.offsetMax = Vector2.zero;
    }

    private static void ConfigureTextBand(RectTransform rectTransform, float anchorMinY, float anchorMaxY)
    {
        rectTransform.anchorMin = new Vector2(0.12f, anchorMinY);
        rectTransform.anchorMax = new Vector2(0.88f, anchorMaxY);
        rectTransform.offsetMin = Vector2.zero;
        rectTransform.offsetMax = Vector2.zero;
    }

    private static void ConfigurePixelRect(RectTransform rectTransform, float x, float yFromTop, float width, float height, float referenceWidth, float referenceHeight)
    {
        rectTransform.anchorMin = new Vector2(x / referenceWidth, 1f - (yFromTop + height) / referenceHeight);
        rectTransform.anchorMax = new Vector2((x + width) / referenceWidth, 1f - yFromTop / referenceHeight);
        rectTransform.offsetMin = Vector2.zero;
        rectTransform.offsetMax = Vector2.zero;
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureFixedTopCenterRect(RectTransform rectTransform, float yFromTop, float width, float height)
    {
        rectTransform.anchorMin = new Vector2(0.5f, 1f);
        rectTransform.anchorMax = new Vector2(0.5f, 1f);
        rectTransform.pivot = new Vector2(0.5f, 1f);
        rectTransform.anchoredPosition = new Vector2(0f, -yFromTop);
        rectTransform.sizeDelta = new Vector2(width, height);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureFixedLeftProportionalY(RectTransform rectTransform, float left, float top, float width, float height, float referenceHeight)
    {
        rectTransform.anchorMin = new Vector2(0f, 1f - (top + height) / referenceHeight);
        rectTransform.anchorMax = new Vector2(0f, 1f - top / referenceHeight);
        rectTransform.offsetMin = new Vector2(left, 0f);
        rectTransform.offsetMax = new Vector2(left + width, 0f);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureFixedRightProportionalY(RectTransform rectTransform, float right, float top, float width, float height, float referenceHeight)
    {
        rectTransform.anchorMin = new Vector2(1f, 1f - (top + height) / referenceHeight);
        rectTransform.anchorMax = new Vector2(1f, 1f - top / referenceHeight);
        rectTransform.offsetMin = new Vector2(-(right + width), 0f);
        rectTransform.offsetMax = new Vector2(-right, 0f);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureStretchWidthProportionalY(RectTransform rectTransform, float left, float right, float top, float height, float referenceHeight)
    {
        rectTransform.anchorMin = new Vector2(0f, 1f - (top + height) / referenceHeight);
        rectTransform.anchorMax = new Vector2(1f, 1f - top / referenceHeight);
        rectTransform.offsetMin = new Vector2(left, 0f);
        rectTransform.offsetMax = new Vector2(-right, 0f);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureFixedWidthVerticalBand(RectTransform rectTransform, float left, float width, float anchorMinY, float anchorMaxY)
    {
        rectTransform.anchorMin = new Vector2(0f, anchorMinY);
        rectTransform.anchorMax = new Vector2(0f, anchorMaxY);
        rectTransform.offsetMin = new Vector2(left, 0f);
        rectTransform.offsetMax = new Vector2(left + width, 0f);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureStretchHorizontalVerticalBand(RectTransform rectTransform, float left, float right, float anchorMinY, float anchorMaxY)
    {
        rectTransform.anchorMin = new Vector2(0f, anchorMinY);
        rectTransform.anchorMax = new Vector2(1f, anchorMaxY);
        rectTransform.offsetMin = new Vector2(left, 0f);
        rectTransform.offsetMax = new Vector2(-right, 0f);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureFixedFromTopLeft(RectTransform rectTransform, float left, float top, float width, float height)
    {
        rectTransform.anchorMin = new Vector2(0f, 1f);
        rectTransform.anchorMax = new Vector2(0f, 1f);
        rectTransform.pivot = new Vector2(0f, 1f);
        rectTransform.anchoredPosition = new Vector2(left, -top);
        rectTransform.sizeDelta = new Vector2(width, height);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureFixedFromTopRight(RectTransform rectTransform, float right, float top, float width, float height)
    {
        rectTransform.anchorMin = new Vector2(1f, 1f);
        rectTransform.anchorMax = new Vector2(1f, 1f);
        rectTransform.pivot = new Vector2(1f, 1f);
        rectTransform.anchoredPosition = new Vector2(-right, -top);
        rectTransform.sizeDelta = new Vector2(width, height);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureStretchFromTop(RectTransform rectTransform, float left, float top, float right, float height)
    {
        rectTransform.anchorMin = new Vector2(0f, 1f);
        rectTransform.anchorMax = new Vector2(1f, 1f);
        rectTransform.offsetMin = new Vector2(left, -(top + height));
        rectTransform.offsetMax = new Vector2(-right, -top);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureStretchFromBottom(RectTransform rectTransform, float left, float bottom, float right, float height)
    {
        rectTransform.anchorMin = new Vector2(0f, 0f);
        rectTransform.anchorMax = new Vector2(1f, 0f);
        rectTransform.offsetMin = new Vector2(left, bottom);
        rectTransform.offsetMax = new Vector2(-right, bottom + height);
        rectTransform.localScale = Vector3.one;
    }

    private static void ConfigureStretchFromTopBottom(RectTransform rectTransform, float left, float top, float right, float bottom)
    {
        rectTransform.anchorMin = Vector2.zero;
        rectTransform.anchorMax = Vector2.one;
        rectTransform.offsetMin = new Vector2(left, bottom);
        rectTransform.offsetMax = new Vector2(-right, -top);
        rectTransform.localScale = Vector3.one;
    }

